window.GRAMMAR_PAGES = {"1":{"line":"Every noun is <b>masculine</b> (le, un) or <b>feminine</b> (la, une), even a table. Learn each noun with its article. Endings help: <b>-age, -ment, -eau</b> are usually masculine; <b>-tion, -té, -ure</b> usually feminine. Plural: add <b>-s</b> (not heard); -eau → -eaux, -al → -aux.","words":"Everyday nouns with pictures: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:17\">Vocab 17 · The « Survival 50 » Nouns</a>.","steps":[{"tool":"sort","title":"Masculine or feminine?","sub":"Tap the box for each noun. The ending is a clue, with a few traps.","boxes":[{"k":"m","label":"le / un","sub":"masculine"},{"k":"f","label":"la / une","sub":"feminine"}],"cards":[{"t":"fromage","box":"m","why":"-age: usually masculine, <b>le fromage</b>.","en":"cheese"},{"t":"nation","box":"f","why":"-tion: feminine, <b>la nation</b>.","en":"nation"},{"t":"gouvernement","box":"m","why":"-ment: masculine, <b>le gouvernement</b>.","en":"government"},{"t":"liberté","box":"f","why":"-té: feminine, <b>la liberté</b>.","en":"freedom"},{"t":"bateau","box":"m","why":"-eau: masculine, <b>le bateau</b>.","en":"boat"},{"t":"voiture","box":"f","why":"-ure: feminine, <b>la voiture</b>.","en":"car"},{"t":"plage","box":"f","why":"A trap: -age but feminine, <b>la plage</b>.","en":"beach"},{"t":"problème","box":"m","why":"A trap: -e but masculine, <b>le problème</b>.","en":"problem"},{"t":"maison","box":"f","why":"<b>la maison</b>: learn it with la.","en":"house"}]},{"tool":"agree","title":"One or more?","sub":"Switch to the plural: the letters that change light up. The -s is written, not heard.","cols":["one","more than one"],"rows":[{"forms":["le livre","les livres"],"en":["the book","the books"]},{"forms":["la table","les tables"],"en":["the table","the tables"]},{"forms":["le gâteau","les gâteaux"],"en":["the cake","the cakes · -eau → -eaux"]},{"forms":["le journal","les journaux"],"en":["the newspaper","the newspapers · -al → -aux"]},{"forms":["le prix","les prix"],"en":["the price","the prices · -x stays"]},{"forms":["le nez","les nez"],"en":["the nose","the noses · -z stays"]}]},{"tool":"flip","title":"A man, a woman","sub":"Tap a card: the job or the person turns feminine.","cards":[{"a":"un étudiant","b":"une étudiante","tag":"+ e"},{"a":"un acteur","b":"une actrice","tag":"-teur → -trice"},{"a":"un chanteur","b":"une chanteuse","tag":"-eur → -euse"},{"a":"un Italien","b":"une Italienne","tag":"-en → -enne"},{"a":"un boulanger","b":"une boulangère","tag":"-er → -ère"},{"a":"un journaliste","b":"une journaliste","tag":"-e: no change"}]}],"practice":{"choose":[{"q":"___ fromage","en":"cheese","opts":["le","la"],"a":"le","why":"What does -age usually take?","hint":"-age is usually masculine: <b>le fromage</b>."},{"q":"___ nation","en":"nation","opts":["la","le"],"a":"la","why":"What does -tion take?","hint":"-tion is feminine: <b>la nation</b>."},{"q":"___ problème","en":"problem","opts":["le","la"],"a":"le","why":"It ends in -e, but it is one of the traps.","hint":"<b>le problème</b>: masculine."},{"q":"___ plage","en":"beach","opts":["la","le"],"a":"la","why":"It ends in -age, but it is one of the traps.","hint":"<b>la plage</b>: feminine."},{"q":"le gâteau → les ___","en":"the cakes","opts":["gâteaux","gâteaus","gâteau"],"a":"gâteaux","why":"What does -eau take in the plural?","hint":"-eau → <b>-eaux</b>."},{"q":"le journal → les ___","en":"the newspapers","opts":["journaux","journals","journales"],"a":"journaux","why":"What does -al become?","hint":"-al → <b>-aux</b>."},{"q":"un acteur → une ___","en":"an actress","opts":["actrice","acteuse","acteure"],"a":"actrice","why":"-teur has its own feminine.","hint":"-teur → <b>-trice</b>."}],"build":[{"en":"The newspapers are on the table.","tiles":["Les","journaux","sont","sur","la","table."],"trap":"journals","why":"-al in the plural…","hint":"les <b>journaux</b>."},{"en":"She is a student.","tiles":["C'est","une","étudiante."],"trap":"un","why":"She: the feminine.","hint":"<b>une</b> étudiante."},{"en":"I like cakes.","tiles":["J'aime","les","gâteaux."],"trap":"gâteaus","why":"-eau in the plural…","hint":"les <b>gâteaux</b>."},{"en":"The problem is simple.","tiles":["Le","problème","est","simple."],"trap":"La","why":"problème is a trap.","hint":"<b>le</b> problème."},{"en":"The beach is beautiful.","tiles":["La","plage","est","belle."],"trap":"Le","why":"plage is a trap.","hint":"<b>la</b> plage."}],"spot":[{"words":["J'aime","la","fromage."],"bad":1,"fix":"le","hint":"<b>le</b> fromage (-age).","look":"Look at the article."},{"words":["Les","journals","sont là."],"bad":1,"fix":"journaux","hint":"-al → <b>-aux</b>.","look":"Look at the plural."},{"words":["C'est","un","actrice."],"bad":1,"fix":"une","hint":"actrice is a woman: <b>une</b>.","look":"Look at the article."},{"words":["Le","plage","est loin."],"bad":0,"fix":"La","hint":"<b>la</b> plage.","look":"Look at the article."},{"words":["Il y a","deux","gâteau."],"bad":2,"fix":"gâteaux.","hint":"Two cakes: <b>gâteaux</b>.","look":"Two of them…"}]},"drill":[["Which article? ___ plage","la plage","-age is usually masculine, but plage is feminine: <b>la plage</b>."],["Plural of le journal","les journaux","-al → <b>-aux</b>: les journaux."],["Plural of le prix","les prix","Nouns in -s, -x or -z do not change: les prix."],["Feminine of un acteur","une actrice","-teur → <b>-trice</b>."],["Plural of le gâteau","les gâteaux","-eau → <b>-eaux</b>."],["Which article? ___ problème","le problème","A trap: -e but masculine, <b>le problème</b>."]]},"27":{"line":"Cities take <b>à</b>: à Paris. Feminine countries (most end in -e) take <b>en</b>: en France. Masculine ones take <b>au</b> (à + le): au Canada. Plural ones take <b>aux</b>: aux États-Unis. From: de Paris, de France, <b>du</b> Canada, <b>des</b> États-Unis.","words":"The countries and nationalities: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:10\">Vocab 10 · Les Nationalités & Pays</a>.","steps":[{"tool":"join","title":"à + the country","sub":"Tap a pair: au and aux are à + le and à + les; a feminine country takes en.","pairs":[{"a":"à","b":"le Canada","res":"au Canada","ex":"J'habite au Canada.","en":"I live in Canada."},{"a":"à","b":"les États-Unis","res":"aux États-Unis","ex":"Elle vit aux États-Unis.","en":"She lives in the United States."},{"a":"à","b":"la France","res":"en France","ex":"Nous allons en France.","en":"We are going to France."},{"a":"à","b":"l'Italie","res":"en Italie","ex":"Il travaille en Italie.","en":"He works in Italy."},{"a":"à","b":"Paris","res":"à Paris","stay":true,"ex":"Je suis à Paris.","en":"I am in Paris."},{"a":"de","b":"le Japon","res":"du Japon","ex":"Il vient du Japon.","en":"He comes from Japan."},{"a":"de","b":"la France","res":"de France","ex":"Elle revient de France.","en":"She is coming back from France."}]},{"tool":"sort","title":"en, au, aux or à?","sub":"Tap the box for each place. Watch the masculine countries that end in -e.","boxes":[{"k":"en","label":"en","sub":"feminine, or starts with a vowel"},{"k":"au","label":"au","sub":"masculine"},{"k":"aux","label":"aux","sub":"plural"},{"k":"a","label":"à","sub":"a city"}],"cards":[{"t":"France","box":"en","why":"<b>en</b> France (la France)."},{"t":"Canada","box":"au","why":"<b>au</b> Canada (le Canada)."},{"t":"États-Unis","box":"aux","why":"<b>aux</b> États-Unis (les États-Unis)."},{"t":"Paris","box":"a","why":"A city: <b>à</b> Paris."},{"t":"Espagne","box":"en","why":"<b>en</b> Espagne (l'Espagne)."},{"t":"Japon","box":"au","why":"<b>au</b> Japon (le Japon)."},{"t":"Mexique","box":"au","why":"A trap: -e but masculine: <b>au</b> Mexique."},{"t":"Iran","box":"en","why":"A vowel: <b>en</b> Iran."},{"t":"Pays-Bas","box":"aux","why":"<b>aux</b> Pays-Bas."},{"t":"Londres","box":"a","why":"A city: <b>à</b> Londres."},{"t":"Portugal","box":"au","why":"<b>au</b> Portugal."},{"t":"Cambodge","box":"au","why":"A trap: -e but masculine: <b>au</b> Cambodge."}]},{"tool":"flip","title":"Going to → coming from","sub":"Tap a card: « to » turns into « from ».","cards":[{"a":"Je vais en France.","b":"Je viens de France.","tag":"en → de"},{"a":"Je vais au Canada.","b":"Je viens du Canada.","tag":"au → du"},{"a":"Je vais aux États-Unis.","b":"Je viens des États-Unis.","tag":"aux → des"},{"a":"Je vais à Paris.","b":"Je viens de Paris.","tag":"à → de"},{"a":"Je vais en Italie.","b":"Je viens d'Italie.","tag":"en → d'"},{"a":"Je vais au Japon.","b":"Je viens du Japon.","tag":"au → du"}]}],"practice":{"choose":[{"q":"J'habite ___ France.","en":"I live in France.","opts":["en","au","à","aux"],"a":"en","why":"la France is feminine.","hint":"Feminine country: <b>en</b>."},{"q":"Nous allons ___ Canada.","en":"We are going to Canada.","opts":["au","en","à","aux"],"a":"au","why":"le Canada is masculine.","hint":"à + le = <b>au</b>."},{"q":"Elle vit ___ États-Unis.","en":"She lives in the United States.","opts":["aux","au","en","à"],"a":"aux","why":"les États-Unis is plural.","hint":"à + les = <b>aux</b>."},{"q":"Il travaille ___ Paris.","en":"He works in Paris.","opts":["à","en","au","dans"],"a":"à","why":"Paris is a city.","hint":"A city: <b>à</b>."},{"q":"Je vais ___ Mexique.","en":"I am going to Mexico.","opts":["au","en","à","aux"],"a":"au","why":"It ends in -e, but le Mexique is masculine.","hint":"<b>au</b> Mexique."},{"q":"Il vient ___ Japon.","en":"He comes from Japan.","opts":["du","de","des","au"],"a":"du","why":"From + le Japon…","hint":"de + le = <b>du</b>."},{"q":"Elle revient ___ Italie.","en":"She is coming back from Italy.","opts":["d'","de","du","en"],"a":"d'","why":"Italie starts with a vowel.","hint":"<b>d'</b>Italie."}],"build":[{"en":"I live in Spain.","tiles":["J'habite","en","Espagne."],"trap":"au","why":"l'Espagne is feminine.","hint":"<b>en</b> Espagne."},{"en":"We are going to Portugal.","tiles":["Nous","allons","au","Portugal."],"trap":"en","why":"le Portugal is masculine.","hint":"<b>au</b> Portugal."},{"en":"She comes from the United States.","tiles":["Elle","vient","des","États-Unis."],"trap":"de les","why":"de + les join.","hint":"<b>des</b> États-Unis."},{"en":"He works in London.","tiles":["Il","travaille","à","Londres."],"trap":"en","why":"London is a city.","hint":"<b>à</b> Londres."},{"en":"I come from Canada.","tiles":["Je","viens","du","Canada."],"trap":"de le","why":"de + le join.","hint":"<b>du</b> Canada."}],"spot":[{"words":["J'habite","au","France."],"bad":1,"fix":"en","hint":"Feminine country: <b>en</b> France.","look":"Look at the little word before France."},{"words":["Nous allons","en","Canada."],"bad":1,"fix":"au","hint":"Masculine country: <b>au</b> Canada.","look":"Look at the little word before Canada."},{"words":["Il vit","en","Paris."],"bad":1,"fix":"à","hint":"A city: <b>à</b> Paris.","look":"Is Paris a country or a city?"},{"words":["Elle vient","de les","États-Unis."],"bad":1,"fix":"des","hint":"de + les = <b>des</b>.","look":"Two little words that should join."},{"words":["Je vais","en","Mexique."],"bad":1,"fix":"au","hint":"<b>au</b> Mexique: masculine, although it ends in -e.","look":"Mexique is one of the traps."}]},"drill":[["I live in France","J'habite en France. / Je vis en France.","Feminine country: <b>en</b> France."],["We are going to Canada","Nous allons au Canada.","Masculine country: à + le = <b>au</b> Canada."],["She comes from the United States","Elle vient des États-Unis.","From a plural country: de + les = <b>des</b>."],["He lives in Japan","Il habite au Japon. / Il vit au Japon.","le Japon: <b>au</b> Japon."],["I'm going to Spain.","Je vais en Espagne.","l'Espagne is feminine: <b>en</b> Espagne."],["He comes from Japan.","Il vient du Japon.","de + le = <b>du</b> Japon."]]},"3":{"line":"« Some » of something you can't count: <b>du</b> (le), <b>de la</b> (la), <b>de l'</b> (before a vowel), <b>des</b> (plural): je bois du café, de l'eau. English often says nothing; French always does. After a no: <b>pas de</b>. After a quantity: <b>beaucoup de</b>, un kilo de. Likes take le: j'aime le café.","words":"Food and ordering: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:18\">Vocab 18 · Café, Food & Ordering</a>.","steps":[{"tool":"join","title":"de + the article","sub":"Tap a pair: de + le and de + les join; de la and de l' stay.","pairs":[{"a":"de","b":"le pain","res":"du pain","ex":"Je mange du pain.","en":"I eat (some) bread."},{"a":"de","b":"la confiture","res":"de la confiture","stay":true,"ex":"Tu veux de la confiture ?","en":"Do you want (some) jam?"},{"a":"de","b":"l'eau","res":"de l'eau","stay":true,"ex":"Je bois de l'eau.","en":"I drink water."},{"a":"de","b":"les pâtes","res":"des pâtes","ex":"On mange des pâtes ce soir.","en":"We are having pasta tonight."}]},{"tool":"sort","title":"Some of it, or all of it?","sub":"Tap the box: an amount (some) or the thing in general (likes and dislikes)?","boxes":[{"k":"some","label":"du / de la / des","sub":"some, an amount"},{"k":"all","label":"le / la / les","sub":"in general: aimer, adorer, détester"}],"cards":[{"t":"Je bois … café le matin.","box":"some","why":"An amount you drink: <b>du</b> café.","say":"Je bois du café le matin."},{"t":"J'adore … café.","box":"all","why":"Likes take le: <b>le</b> café.","say":"J'adore le café."},{"t":"Tu veux … pain ?","box":"some","why":"Some bread: <b>du</b> pain.","say":"Tu veux du pain ?"},{"t":"Je déteste … fromage.","box":"all","why":"Dislikes take le: <b>le</b> fromage.","say":"Je déteste le fromage."},{"t":"On achète … pommes.","box":"some","why":"Some apples: <b>des</b> pommes.","say":"On achète des pommes."},{"t":"Les enfants aiment … chocolat.","box":"all","why":"Likes take le: <b>le</b> chocolat.","say":"Les enfants aiment le chocolat."}]},{"tool":"flip","title":"After a no, after a quantity","sub":"Tap a card: du, de la, des become de.","cards":[{"a":"Je bois du café.","b":"Je ne bois pas de café.","tag":"du → pas de"},{"a":"Il y a de la soupe.","b":"Il n'y a pas de soupe.","tag":"de la → pas de"},{"a":"Elle mange des pommes.","b":"Elle mange beaucoup de pommes.","tag":"des → beaucoup de"},{"a":"J'achète du fromage.","b":"J'achète un kilo de fromage.","tag":"du → un kilo de"},{"a":"Il boit de l'eau.","b":"Il ne boit pas d'eau.","tag":"de l' → pas d'"}]}],"practice":{"choose":[{"q":"Je voudrais ___ eau.","en":"I'd like some water.","opts":["de l'","du","de la","des"],"a":"de l'","why":"eau starts with a vowel.","hint":"<b>de l'</b>eau."},{"q":"Tu veux ___ pain ?","en":"Do you want some bread?","opts":["du","de la","le","des"],"a":"du","why":"le pain: some of it…","hint":"de + le = <b>du</b>."},{"q":"Elle mange ___ salade.","en":"She is eating (some) salad.","opts":["de la","du","la","des"],"a":"de la","why":"la salade: some of it…","hint":"<b>de la</b> salade."},{"q":"J'aime ___ fromage.","en":"I like cheese.","opts":["le","du","de","un"],"a":"le","why":"Liking something: some, or in general?","hint":"Likes take <b>le</b>."},{"q":"Il ne mange pas ___ viande.","en":"He doesn't eat meat.","opts":["de","de la","la","du"],"a":"de","why":"It is a no.","hint":"After a no: <b>pas de</b>."},{"q":"Il y a beaucoup ___ gens.","en":"There are a lot of people.","opts":["de","des","du","les"],"a":"de","why":"After beaucoup…","hint":"<b>beaucoup de</b>."},{"q":"On achète ___ tomates.","en":"We are buying (some) tomatoes.","opts":["des","de","les","du"],"a":"des","why":"Some tomatoes, more than one.","hint":"<b>des</b> tomates."}],"build":[{"en":"I drink water.","tiles":["Je","bois","de l'","eau."],"trap":"du","why":"eau starts with a vowel.","hint":"<b>de l'</b>eau."},{"en":"She doesn't eat meat.","tiles":["Elle","ne","mange","pas","de","viande."],"trap":"de la","why":"It is a no.","hint":"pas <b>de</b> viande."},{"en":"Do you want some bread?","tiles":["Tu","veux","du","pain ?"],"trap":"de le","why":"de + le join.","hint":"<b>du</b> pain."},{"en":"There are a lot of people.","tiles":["Il","y a","beaucoup","de","monde."],"trap":"du","why":"After beaucoup…","hint":"beaucoup <b>de</b>."},{"en":"I like chocolate.","tiles":["J'aime","le","chocolat."],"trap":"du","why":"Likes take le.","hint":"j'aime <b>le</b> chocolat."}],"spot":[{"words":["Je","bois","de le","café."],"bad":2,"fix":"du","hint":"de + le = <b>du</b>.","look":"Two little words that should join."},{"words":["Elle","ne mange pas","de la","viande."],"bad":2,"fix":"de","hint":"After a no: <b>pas de</b>.","look":"Look at the word after pas."},{"words":["J'aime","du","chocolat."],"bad":1,"fix":"le","hint":"Likes take <b>le</b>.","look":"With aimer, which article?"},{"words":["Il y a","beaucoup","des","gens."],"bad":2,"fix":"de","hint":"<b>beaucoup de</b>, never beaucoup des.","look":"Look at the word after beaucoup."},{"words":["Je voudrais","du","eau."],"bad":1,"fix":"de l'","hint":"eau starts with a vowel: <b>de l'</b>eau.","look":"eau starts with a vowel.","say":"Je voudrais de l'eau."}]},"drill":[["I'd like some water","Je voudrais de l'eau. / J'aimerais de l'eau.","Before a vowel: <b>de l'</b>eau."],["She doesn't eat meat","Elle ne mange pas de viande.","After a no: <b>pas de</b>."],["a lot of people","beaucoup de monde / beaucoup de gens","After beaucoup: <b>de</b>."],["Do you want some bread?","Tu veux du pain ? / Vous voulez du pain ? / Veux-tu du pain ?","de + le = <b>du</b> pain."],["I like cheese.","J'aime le fromage.","Likes take <b>le</b>: j'aime le fromage."],["There isn't any milk.","Il n'y a pas de lait.","After a no: <b>pas de</b> lait."]]},"4":{"line":"French verbs need a subject: <b>je</b> (j' before a vowel), <b>tu, il, elle, on, nous, vous, ils, elles</b>. <b>tu</b> = one person you know well; <b>vous</b> = polite, or more than one person. <b>ils</b> for a group with at least one man, <b>elles</b> only women. Things are il or elle too. <b>on</b> = we, in everyday French.","words":"","steps":[{"tool":"sort","title":"tu or vous?","sub":"Who are you talking to? Tap the box.","boxes":[{"k":"tu","label":"tu","sub":"one person you know well"},{"k":"vous","label":"vous","sub":"polite, or more than one"}],"cards":[{"t":"your best friend","box":"tu","why":"A friend: <b>tu</b>."},{"t":"your boss","box":"vous","why":"Polite: <b>vous</b>."},{"t":"a child","box":"tu","why":"A child: <b>tu</b>."},{"t":"a waiter in a café","box":"vous","why":"Someone you do not know: <b>vous</b>."},{"t":"your mother","box":"tu","why":"Family: <b>tu</b>."},{"t":"two friends together","box":"vous","why":"More than one person: <b>vous</b>, even friends."},{"t":"a doctor","box":"vous","why":"Polite: <b>vous</b>."}]},{"tool":"sort","title":"il, elle, ils or elles?","sub":"Tap the pronoun for each one.","boxes":[{"k":"il","label":"il"},{"k":"elle","label":"elle"},{"k":"ils","label":"ils"},{"k":"elles","label":"elles"}],"cards":[{"t":"Paul","box":"il"},{"t":"Marie","box":"elle"},{"t":"Marie et Julie","box":"elles","why":"Only women: <b>elles</b>."},{"t":"Marie et Paul","box":"ils","why":"One man is enough: <b>ils</b>."},{"t":"le livre","box":"il","why":"Things too: le livre → <b>il</b>."},{"t":"la table","box":"elle","why":"la table → <b>elle</b>."},{"t":"les enfants (girls and boys)","box":"ils","why":"Mixed: <b>ils</b>."},{"t":"les filles","box":"elles"}]},{"tool":"flip","title":"je → j', and on","sub":"Tap a card. Before a vowel or a silent h, je becomes j'. In everyday French, on means we.","cards":[{"a":"je + aime","b":"j'aime","tag":"je → j'"},{"a":"je + habite","b":"j'habite","tag":"silent h: j'"},{"a":"je + écoute","b":"j'écoute","tag":"je → j'"},{"a":"je + parle","b":"je parle","tag":"no vowel: no change"},{"a":"Nous allons au cinéma.","b":"On va au cinéma.","tag":"nous → on (everyday)"}]}],"practice":{"choose":[{"q":"Marie et Julie → ___","en":"","opts":["elles","ils","elle","vous"],"a":"elles","why":"Two women…","hint":"Only women: <b>elles</b>."},{"q":"Marie et Paul → ___","en":"","opts":["ils","elles","il","on"],"a":"ils","why":"There is a man in the group.","hint":"One man is enough: <b>ils</b>."},{"q":"« ___ êtes prêt, monsieur ? »","en":"Are you ready, sir?","opts":["Vous","Tu","Il","Nous"],"a":"Vous","why":"Talking to « monsieur »…","hint":"Polite: <b>vous</b>."},{"q":"« ___ viens ce soir ? » (to a friend)","en":"Are you coming tonight?","opts":["Tu","Vous","Il","Je"],"a":"Tu","why":"A friend…","hint":"A friend: <b>tu</b>."},{"q":"___ aime le café. (I)","en":"I like coffee.","opts":["J'","Je","Tu","Il"],"a":"J'","why":"aime starts with a vowel.","hint":"Before a vowel: <b>j'</b>aime."},{"q":"Le livre ? ___ est sur la table.","en":"The book? It is on the table.","opts":["Il","Elle","Le","On"],"a":"Il","why":"le livre is masculine.","hint":"le livre → <b>il</b>."},{"q":"La voiture ? ___ est rouge.","en":"The car? It is red.","opts":["Elle","Il","La","On"],"a":"Elle","why":"la voiture is feminine.","hint":"la voiture → <b>elle</b>."}],"build":[{"en":"We're going to the cinema (everyday French).","tiles":["On","va","au","cinéma."],"trap":"allons","why":"on takes the il form.","hint":"<b>on va</b>."},{"en":"I live in Lyon.","tiles":["J'habite","à","Lyon."],"trap":"Je","why":"habite starts with a silent h.","hint":"<b>j'</b>habite."},{"en":"They (Marie and Paul) are here.","tiles":["Ils","sont","là."],"trap":"Elles","why":"There is a man in the group.","hint":"<b>ils</b> sont là."},{"en":"Are you ready, sir?","tiles":["Vous","êtes","prêt,","monsieur ?"],"trap":"Tu","why":"Polite…","hint":"<b>vous</b> êtes."},{"en":"She is tired.","tiles":["Elle","est","fatiguée."],"trap":"Il","why":"She…","hint":"<b>elle</b> est."}],"spot":[{"words":["Je aime","le chocolat."],"bad":0,"fix":"J'aime","hint":"Before a vowel: <b>j'</b>aime.","look":"aime starts with a vowel."},{"words":["Marie et Paul,","elles","sont là."],"bad":1,"fix":"ils","hint":"One man is enough: <b>ils</b>.","look":"Look at who is in the group."},{"words":["Monsieur,","tu","êtes","en retard."],"bad":1,"fix":"vous","hint":"Polite, and êtes is the vous form: <b>vous</b>.","look":"Look at the verb: which pronoun does it go with?"},{"words":["On","allons","au parc."],"bad":1,"fix":"va","hint":"on takes the il form: <b>on va</b>.","look":"Look at the verb after on."},{"words":["La table ?","Il","est","grande."],"bad":1,"fix":"Elle","hint":"la table → <b>elle</b>.","look":"Is table masculine or feminine?"}]},"drill":[["Speaking to your boss: tu or vous?","vous","Polite: <b>vous</b>."],["Marie and Julie","elles","Only women: <b>elles</b>."],["Marie and Paul","ils","One man is enough: <b>ils</b>."],["je + aime","J'aime","Before a vowel, je becomes <b>j'</b>."],["Le livre → pronoun","il","Things are il or elle too: le livre → <b>il</b>."],["je + habite","J'habite","A silent h counts as a vowel: <b>j'</b>habite."]]},"29":{"line":"<b>moi, toi, lui, elle, nous, vous, eux, elles</b> stand on their own. Use them after <b>c'est</b> (c'est moi), after a little word like <b>avec, chez, pour</b> (avec toi, chez lui), to stress (<b>Moi</b>, je préfère le thé), and in short answers (Moi aussi, Moi non plus).","words":"","steps":[{"tool":"swap","title":"Put the stress on it","sub":"Pick a sentence and tap « Stress it »: the stressed pronoun comes to the front.","button":["Stress it","Plain again"],"legend":[["p","the stressed pronoun"]],"items":[{"label":"Je préfère le thé.","en":["I prefer tea.","Me, I prefer tea."],"a":[["s","Je",""],["v","préfère",""],["o","le thé.",""]],"b":[["m","Moi,","p"],["s","je",""],["v","préfère",""],["o","le thé.",""]],"note":"<b>Moi</b> at the front puts the weight on « I »."},{"label":"Tu as raison.","en":["You are right.","You, you are right."],"a":[["s","Tu",""],["v","as",""],["o","raison.",""]],"b":[["m","Toi,","p"],["s","tu",""],["v","as",""],["o","raison.",""]],"note":"tu → <b>toi</b>."},{"label":"Il est grand.","en":["He is tall.","Him, he is tall."],"a":[["s","Il",""],["v","est",""],["o","grand.",""]],"b":[["m","Lui,","p"],["s","il",""],["v","est",""],["o","grand.",""]],"note":"il → <b>lui</b>."},{"label":"Ils sont partis.","en":["They left.","Them, they left."],"a":[["s","Ils",""],["v","sont",""],["o","partis.",""]],"b":[["m","Eux,","p"],["s","ils",""],["v","sont",""],["o","partis.",""]],"note":"ils → <b>eux</b> (men, or a mixed group)."}]},{"tool":"flip","title":"After c'est and little words","sub":"Tap a card: the subject pronoun turns into its stressed form.","cards":[{"a":"je","b":"C'est moi.","tag":"je → moi"},{"a":"tu","b":"avec toi","tag":"tu → toi"},{"a":"il","b":"chez lui","tag":"il → lui"},{"a":"elle","b":"pour elle","tag":"elle → elle"},{"a":"nous","b":"sans nous","tag":"nous → nous"},{"a":"ils","b":"avec eux","tag":"ils → eux"},{"a":"elles","b":"chez elles","tag":"elles → elles"}]},{"tool":"pairs","title":"Short answers","sub":"Agreeing with a yes, and with a no. Tap one to hear it.","cap":["Agreeing with a yes","Agreeing with a no"],"rows":[{"l":"J'aime le café. Moi aussi.","r":"Je n'aime pas le café. Moi non plus.","en":"me too / me neither"},{"l":"Il est content. Moi aussi.","r":"Il n'est pas content. Moi non plus."},{"l":"Nous partons. Nous aussi.","r":"Nous ne partons pas. Nous non plus."}]}],"practice":{"choose":[{"q":"C'est ___ ! (me)","en":"It's me!","opts":["moi","je","me","mon"],"a":"moi","why":"After c'est…","hint":"c'est <b>moi</b>."},{"q":"Je viens avec ___. (you, tu)","en":"I'm coming with you.","opts":["toi","tu","te","ton"],"a":"toi","why":"After avec…","hint":"avec <b>toi</b>."},{"q":"Elle habite chez ___. (him)","en":"She lives at his place.","opts":["lui","il","le","son"],"a":"lui","why":"After chez…","hint":"chez <b>lui</b>."},{"q":"Je travaille avec ___. (them, men)","en":"I work with them.","opts":["eux","ils","leur","les"],"a":"eux","why":"After avec, ils becomes…","hint":"avec <b>eux</b>."},{"q":"___, je préfère le thé.","en":"Me, I prefer tea.","opts":["Moi","Je","Me","Mon"],"a":"Moi","why":"Stress at the front…","hint":"<b>Moi</b>, je …"},{"q":"« J'aime ce film. » « ___ aussi. »","en":"« Me too. »","opts":["Moi","Je","Me","Mon"],"a":"Moi","why":"A short answer stands on its own.","hint":"<b>Moi</b> aussi."},{"q":"« Je n'ai pas faim. » « Moi ___. »","en":"« Me neither. »","opts":["non plus","aussi","pas","non"],"a":"non plus","why":"Agreeing with a no…","hint":"Moi <b>non plus</b>."}],"build":[{"en":"It's me.","tiles":["C'est","moi."],"trap":"je","why":"After c'est…","hint":"c'est <b>moi</b>."},{"en":"I'm coming with you.","tiles":["Je","viens","avec","toi."],"trap":"tu","why":"After avec…","hint":"avec <b>toi</b>."},{"en":"Paul is taller than him.","tiles":["Paul","est","plus","grand","que","lui."],"trap":"il","why":"After que…","hint":"que <b>lui</b>."},{"en":"Me too.","tiles":["Moi","aussi."],"trap":"Je","why":"A short answer…","hint":"<b>Moi</b> aussi."},{"en":"I'm going home.","tiles":["Je","rentre","chez","moi."],"trap":"je","why":"After chez…","hint":"chez <b>moi</b>."}],"spot":[{"words":["C'est","je."],"bad":1,"fix":"moi.","hint":"After c'est: <b>moi</b>.","look":"Look at the word after c'est."},{"words":["Je pars","avec","tu."],"bad":2,"fix":"toi.","hint":"After avec: <b>toi</b>.","look":"Look at the word after avec."},{"words":["Il dîne","chez","il."],"bad":2,"fix":"lui.","hint":"After chez: <b>lui</b>.","look":"Look at the word after chez."},{"words":["Je","aussi."],"bad":0,"fix":"Moi","hint":"A short answer: <b>Moi</b> aussi.","look":"Can je stand on its own?","say":"Moi aussi."},{"words":["Je travaille","avec","ils."],"bad":2,"fix":"eux.","hint":"After avec, ils becomes <b>eux</b>.","look":"Look at the word after avec."}]},"drill":[["It's me","C'est moi.","After c'est: <b>moi</b>."],["with you (tu)","avec toi","After avec: <b>toi</b>."],["taller than him","plus grand que lui","After que: <b>lui</b>."],["Me too","Moi aussi.","A short answer: <b>Moi</b> aussi."],["at their place (men)","chez eux","After chez, ils becomes <b>eux</b>."],["Me neither.","Moi non plus.","Agreeing with a no: moi <b>non plus</b>."]]},"v1":{"line":"<b>être</b> (to be): je suis, tu es, il est, nous sommes, vous êtes, ils sont. <b>avoir</b> (to have): j'ai, tu as, il a, nous avons, vous avez, ils ont. Learn them as whole words: they have no regular pattern. Listen: <b>ils ont</b> (a z sound) and <b>ils sont</b> (an s sound) are different verbs.","words":"","steps":[{"tool":"conj","title":"être and avoir","sub":"Pick the verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"être","en":"to be","forms":["suis","es","est","sommes","êtes","sont"],"tail":"à Paris"},{"inf":"avoir","en":"to have","forms":["ai","as","a","avons","avez","ont"],"tail":"un chat"}]},{"tool":"sort","title":"être or avoir?","sub":"Tap the verb each sentence needs.","boxes":[{"k":"etre","label":"être","sub":"who or what someone is"},{"k":"avoir","label":"avoir","sub":"having, age, hunger, fear…"}],"cards":[{"t":"Je … étudiant.","box":"etre","why":"Who you are: <b>je suis</b> étudiant.","say":"Je suis étudiant."},{"t":"J'… vingt ans.","box":"avoir","why":"Age: <b>j'ai</b> vingt ans.","say":"J'ai vingt ans."},{"t":"Elle … fatiguée.","box":"etre","why":"How she is: <b>elle est</b> fatiguée.","say":"Elle est fatiguée."},{"t":"Nous … faim.","box":"avoir","why":"Hunger: <b>nous avons</b> faim.","say":"Nous avons faim."},{"t":"Ils … de Lyon.","box":"etre","why":"Where from: <b>ils sont</b> de Lyon.","say":"Ils sont de Lyon."},{"t":"Tu … un chat ?","box":"avoir","why":"Having: <b>tu as</b> un chat ?","say":"Tu as un chat ?"},{"t":"Il … médecin.","box":"etre","why":"A job: <b>il est</b> médecin.","say":"Il est médecin."},{"t":"Vous … raison.","box":"avoir","why":"<b>vous avez</b> raison.","say":"Vous avez raison."}]},{"tool":"pairs","title":"ils ont or ils sont?","sub":"They sound close. Tap each one: avoir has a z sound, être an s sound.","cap":["avoir: ils ont (z)","être: ils sont (s)"],"rows":[{"l":"Ils ont faim.","r":"Ils sont fatigués.","en":"they are hungry / they are tired"},{"l":"Elles ont vingt ans.","r":"Elles sont contentes."},{"l":"Ils ont une maison.","r":"Ils sont à la maison."}]}],"practice":{"choose":[{"q":"Nous ___ fatigués.","en":"We are tired.","opts":["sommes","avons","êtes","sont"],"a":"sommes","why":"How we are: être, and nous.","hint":"être: nous <b>sommes</b>."},{"q":"Ils ___ une grande maison.","en":"They have a big house.","opts":["ont","sont","avons","a"],"a":"ont","why":"Having: avoir, and ils.","hint":"avoir: ils <b>ont</b>."},{"q":"Vous ___ en retard.","en":"You are late.","opts":["êtes","avez","es","sont"],"a":"êtes","why":"être, and vous.","hint":"être: vous <b>êtes</b>."},{"q":"J'___ deux frères.","en":"I have two brothers.","opts":["ai","suis","as","es"],"a":"ai","why":"Having: avoir, with j'.","hint":"avoir: <b>j'ai</b>."},{"q":"Tu ___ canadien ?","en":"Are you Canadian?","opts":["es","as","est","a"],"a":"es","why":"Where from: être, and tu.","hint":"être: tu <b>es</b>."},{"q":"Elle ___ trente ans.","en":"She is thirty.","opts":["a","est","as","ai"],"a":"a","why":"Age takes avoir.","hint":"avoir: elle <b>a</b>."},{"q":"Je ___ médecin.","en":"I am a doctor.","opts":["suis","ai","es","sommes"],"a":"suis","why":"A job: être.","hint":"être: je <b>suis</b>."}],"build":[{"en":"We are from Lyon.","tiles":["Nous","sommes","de","Lyon."],"trap":"avons","why":"Where from: être.","hint":"nous <b>sommes</b>."},{"en":"They have a big house.","tiles":["Ils","ont","une","grande","maison."],"trap":"sont","why":"Having: avoir.","hint":"ils <b>ont</b>."},{"en":"You (vous) are late.","tiles":["Vous","êtes","en retard."],"trap":"avez","why":"être late…","hint":"vous <b>êtes</b>."},{"en":"I have two brothers.","tiles":["J'ai","deux","frères."],"trap":"Je suis","why":"Having: avoir.","hint":"<b>j'ai</b>."},{"en":"She is a doctor.","tiles":["Elle","est","médecin."],"trap":"a","why":"A job: être.","hint":"elle <b>est</b>."}],"spot":[{"words":["Nous","avons","fatigués."],"bad":1,"fix":"sommes","hint":"How we are: <b>nous sommes</b>.","look":"Is fatigués something you have?"},{"words":["Ils","sont","une voiture."],"bad":1,"fix":"ont","hint":"Having: <b>ils ont</b>.","look":"Look at the verb."},{"words":["Je ai","faim."],"bad":0,"fix":"J'ai","hint":"<b>j'ai</b>: je becomes j' before a vowel.","look":"Look at the first word."},{"words":["Vous","êtes","raison."],"bad":1,"fix":"avez","hint":"avoir raison: <b>vous avez</b> raison.","look":"Right is something you have."},{"words":["Tu","est","content ?"],"bad":1,"fix":"es","hint":"être with tu: <b>tu es</b>.","look":"Look at the verb with tu."}]},"drill":[["we are (être)","nous sommes","être: nous <b>sommes</b>."],["they have (avoir)","ils ont","avoir: ils <b>ont</b> (a z sound)."],["you (vous) are","vous êtes","être: vous <b>êtes</b>."],["I have","j'ai","avoir: <b>j'ai</b>."],["she is (être)","elle est","être: il / elle <b>est</b>."],["you (tu) have","tu as","avoir: tu <b>as</b>."]]},"v2":{"line":"<b>aller</b> (to go): je vais, tu vas, il va, nous allons, vous allez, ils vont. <b>faire</b> (to do, to make): je fais, tu fais, il fait, nous faisons (said « fesons »), vous faites, ils font. aller + a verb = the near future (je vais manger). faire is in the weather (il fait beau) and in sports (je fais du vélo).","words":"The weather with faire: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:8\">Vocab 8 · La Météo & Les Saisons</a>.","steps":[{"tool":"conj","title":"aller and faire","sub":"Pick the verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"aller","en":"to go","forms":["vais","vas","va","allons","allez","vont"],"tail":"au marché"},{"inf":"faire","en":"to do, to make","forms":["fais","fais","fait","faisons","faites","font"],"tail":"du sport"}]},{"tool":"sort","title":"aller or faire?","sub":"Tap the verb each sentence needs.","boxes":[{"k":"aller","label":"aller","sub":"going somewhere, the near future"},{"k":"faire","label":"faire","sub":"doing, making, the weather, sport"}],"cards":[{"t":"Je … au cinéma.","box":"aller","why":"<b>je vais</b> au cinéma.","say":"Je vais au cinéma."},{"t":"Il … beau.","box":"faire","why":"The weather: <b>il fait</b> beau.","say":"Il fait beau."},{"t":"Nous … du vélo.","box":"faire","why":"Sport: <b>nous faisons</b> du vélo.","say":"Nous faisons du vélo."},{"t":"Ils … partir.","box":"aller","why":"The near future: <b>ils vont</b> partir.","say":"Ils vont partir."},{"t":"Tu … la cuisine ?","box":"faire","why":"<b>tu fais</b> la cuisine ?","say":"Tu fais la cuisine ?"},{"t":"Vous … à Paris ?","box":"aller","why":"<b>vous allez</b> à Paris ?","say":"Vous allez à Paris ?"},{"t":"Elle … ses devoirs.","box":"faire","why":"<b>elle fait</b> ses devoirs.","say":"Elle fait ses devoirs."}]},{"tool":"flip","title":"Expressions with faire","sub":"Tap a card: the expression in a sentence.","cards":[{"a":"faire beau","b":"Il fait beau.","tag":"the weather is nice"},{"a":"faire froid","b":"Il fait froid.","tag":"it is cold"},{"a":"faire du sport","b":"Je fais du sport.","tag":"I do sport"},{"a":"faire la cuisine","b":"Il fait la cuisine.","tag":"he cooks"},{"a":"faire les courses","b":"Nous faisons les courses.","tag":"we do the shopping"},{"a":"faire attention","b":"Fais attention !","tag":"be careful"}]}],"practice":{"choose":[{"q":"Je ___ au marché.","en":"I am going to the market.","opts":["vais","va","vas","allons"],"a":"vais","why":"aller with je.","hint":"je <b>vais</b>."},{"q":"Nous ___ du sport.","en":"We do sport.","opts":["faisons","faites","font","fais"],"a":"faisons","why":"faire with nous.","hint":"nous <b>faisons</b>."},{"q":"Vous ___ la cuisine ?","en":"Are you cooking?","opts":["faites","faisez","fait","font"],"a":"faites","why":"faire with vous: an irregular one.","hint":"vous <b>faites</b>."},{"q":"Ils ___ à Lyon.","en":"They are going to Lyon.","opts":["vont","allent","vas","font"],"a":"vont","why":"aller with ils.","hint":"ils <b>vont</b>."},{"q":"Il ___ beau aujourd'hui.","en":"The weather is nice today.","opts":["fait","est","va","a"],"a":"fait","why":"The weather takes…","hint":"il <b>fait</b> beau."},{"q":"Tu ___ où ?","en":"Where are you going?","opts":["vas","va","vais","allez"],"a":"vas","why":"aller with tu.","hint":"tu <b>vas</b>."},{"q":"Elles ___ les courses.","en":"They do the shopping.","opts":["font","faisent","vont","fait"],"a":"font","why":"faire with elles.","hint":"elles <b>font</b>."}],"build":[{"en":"We are going to the market.","tiles":["Nous","allons","au","marché."],"trap":"allez","why":"aller with nous.","hint":"nous <b>allons</b>."},{"en":"The weather is nice.","tiles":["Il","fait","beau."],"trap":"est","why":"The weather takes faire.","hint":"il <b>fait</b> beau."},{"en":"They do sport.","tiles":["Ils","font","du","sport."],"trap":"faisent","why":"faire with ils is irregular.","hint":"ils <b>font</b>."},{"en":"You (vous) do the shopping.","tiles":["Vous","faites","les","courses."],"trap":"faisez","why":"faire with vous is irregular.","hint":"vous <b>faites</b>."},{"en":"I'm going home.","tiles":["Je","vais","à","la","maison."],"trap":"va","why":"aller with je.","hint":"je <b>vais</b>."}],"spot":[{"words":["Vous","faisez","du vélo."],"bad":1,"fix":"faites","hint":"vous <b>faites</b>.","look":"Look at the verb with vous."},{"words":["Ils","allent","au cinéma."],"bad":1,"fix":"vont","hint":"ils <b>vont</b>.","look":"Look at the verb with ils."},{"words":["Il","est","froid."],"bad":1,"fix":"fait","hint":"The weather: il <b>fait</b> froid.","look":"It is about the weather."},{"words":["Je","va","à Paris."],"bad":1,"fix":"vais","hint":"je <b>vais</b>.","look":"Look at the verb with je."},{"words":["Ils","faisent","la cuisine."],"bad":1,"fix":"font","hint":"ils <b>font</b>.","look":"Look at the verb with ils."}]},"drill":[["I go","je vais","aller: je <b>vais</b>."],["we do (faire)","nous faisons","faire: nous <b>faisons</b> (said « fesons »)."],["you (vous) do","vous faites","faire: vous <b>faites</b> (not faisez)."],["they go","ils vont","aller: ils <b>vont</b>."],["it's cold (the weather)","il fait froid","The weather takes <b>faire</b>: il fait froid."],["she goes","elle va","aller: il / elle <b>va</b>."]]},"5":{"line":"Take off -er, -ir or -re, then add the endings. <b>-er</b> (parler): je parle, tu parles, il parle, nous parlons, vous parlez, ils parlent; -e, -es and -ent are not heard. <b>-ir</b> (finir): je finis, nous finissons, ils finissent. <b>-re</b> (vendre): je vends, il vend, nous vendons. Je parle = I speak, I am speaking and I do speak.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"conj","title":"The three families","sub":"Pick a verb, then tap a person: the ending lights up. Grey endings are written but not heard.","neg":true,"verbs":[{"inf":"parler","en":"to speak","stem":"parl","forms":["parle","parles","parle","parlons","parlez","parlent"],"silent":[true,true,true,false,false,true],"tail":"français"},{"inf":"aimer","en":"to like","stem":"aim","forms":["aime","aimes","aime","aimons","aimez","aiment"],"silent":[true,true,true,false,false,true],"tail":"le café"},{"inf":"finir","en":"to finish","stem":"fin","forms":["finis","finis","finit","finissons","finissez","finissent"],"tail":"à six heures"},{"inf":"vendre","en":"to sell","stem":"vend","forms":["vends","vends","vend","vendons","vendez","vendent"],"tail":"des livres"}]},{"tool":"sort","title":"Which family?","sub":"Tap the family for each verb.","boxes":[{"k":"er","label":"-er","sub":"like parler"},{"k":"ir","label":"-ir","sub":"like finir"},{"k":"re","label":"-re","sub":"like vendre"}],"cards":[{"t":"manger","box":"er","why":"to eat"},{"t":"choisir","box":"ir","why":"to choose: nous choisissons"},{"t":"attendre","box":"re","why":"to wait: j'attends"},{"t":"regarder","box":"er","why":"to watch"},{"t":"réussir","box":"ir","why":"to succeed: ils réussissent"},{"t":"répondre","box":"re","why":"to answer: il répond"},{"t":"habiter","box":"er","why":"to live"},{"t":"entendre","box":"re","why":"to hear"}]},{"tool":"flip","title":"Small spelling changes","sub":"Tap a card to see the right spelling.","cards":[{"a":"nous mangons","b":"nous mangeons","tag":"g + e before o"},{"a":"nous commencons","b":"nous commençons","tag":"c → ç before o"},{"a":"je aime","b":"j'aime","tag":"je → j' before a vowel"},{"a":"ils finent","b":"ils finissent","tag":"-ir: -issent"},{"a":"il vende","b":"il vend","tag":"-re: il vend"}]}],"practice":{"choose":[{"q":"Nous ___ (manger) à midi.","en":"We eat at noon.","opts":["mangeons","mangons","mangez","mangent"],"a":"mangeons","why":"g before o needs a little help.","hint":"nous <b>mangeons</b>."},{"q":"Tu ___ (finir) à cinq heures.","en":"You finish at five.","opts":["finis","finit","fini","finissez"],"a":"finis","why":"-ir with tu.","hint":"tu <b>finis</b>."},{"q":"Ils ___ (vendre) leur maison.","en":"They are selling their house.","opts":["vendent","vendont","vend","vendez"],"a":"vendent","why":"-re with ils.","hint":"ils <b>vendent</b>."},{"q":"Vous ___ (parler) anglais ?","en":"Do you speak English?","opts":["parlez","parlons","parles","parler"],"a":"parlez","why":"-er with vous.","hint":"vous <b>parlez</b>."},{"q":"Elle ___ (choisir) une robe.","en":"She chooses a dress.","opts":["choisit","choisis","choisi","choisissent"],"a":"choisit","why":"-ir with elle.","hint":"elle <b>choisit</b>."},{"q":"J'___ (aimer) le café.","en":"I like coffee.","opts":["aime","aimes","aiment","aimons"],"a":"aime","why":"-er with je.","hint":"j'<b>aime</b>."},{"q":"Ils ___ (finir) tard.","en":"They finish late.","opts":["finissent","finent","finissons","finis"],"a":"finissent","why":"-ir with ils.","hint":"ils <b>finissent</b>."}],"build":[{"en":"I speak French.","tiles":["Je","parle","français."],"trap":"parles","why":"-er with je.","hint":"je <b>parle</b>."},{"en":"We eat at noon.","tiles":["Nous","mangeons","à","midi."],"trap":"mangons","why":"g before o…","hint":"nous <b>mangeons</b>."},{"en":"They finish at six.","tiles":["Ils","finissent","à","six heures."],"trap":"finent","why":"-ir with ils.","hint":"ils <b>finissent</b>."},{"en":"You (tu) are waiting for the bus.","tiles":["Tu","attends","le","bus."],"trap":"attend","why":"-re with tu.","hint":"tu <b>attends</b>."},{"en":"She likes tea.","tiles":["Elle","aime","le","thé."],"trap":"aimes","why":"-er with elle.","hint":"elle <b>aime</b>."}],"spot":[{"words":["Nous","mangons","ensemble."],"bad":1,"fix":"mangeons","hint":"nous <b>mangeons</b>: keep the e.","look":"Look at the spelling with nous."},{"words":["Ils","finent","le travail."],"bad":1,"fix":"finissent","hint":"-ir with ils: <b>finissent</b>.","look":"Look at the verb with ils."},{"words":["Tu","parle","anglais ?"],"bad":1,"fix":"parles","hint":"-er with tu: <b>parles</b>.","look":"Look at the ending with tu."},{"words":["Il","vends","sa voiture."],"bad":1,"fix":"vend","hint":"-re with il: <b>vend</b>.","look":"Look at the ending with il."},{"words":["Je aime","le thé."],"bad":0,"fix":"J'aime","hint":"Before a vowel: <b>j'</b>aime.","look":"Look at the first word."}]},"drill":[["nous (manger)","nous mangeons","Keep the e before o: nous <b>mangeons</b>."],["tu (finir)","tu finis","-ir: tu <b>finis</b>."],["ils (vendre)","ils vendent","-re: ils <b>vendent</b>."],["I like coffee","J'aime le café.","j'<b>aime</b>, and likes take le."],["vous (parler)","vous parlez","-er: vous <b>-ez</b>."],["elle (choisir)","elle choisit","-ir: il / elle <b>-it</b>."]]},"v3":{"line":"<b>vouloir</b> (want), <b>pouvoir</b> (can), <b>devoir</b> (must), <b>savoir</b> (know how to) + a second verb that stays as it is: je <b>veux</b> partir, tu <b>peux</b> venir, il <b>doit</b> travailler, je <b>sais</b> nager. Only the first verb changes. To be polite: je <b>voudrais</b>.","words":"","steps":[{"tool":"conj","title":"The four modal verbs","sub":"Pick a verb, then tap a person. The second verb never changes.","neg":true,"verbs":[{"inf":"vouloir","en":"to want","forms":["veux","veux","veut","voulons","voulez","veulent"],"tail":"partir"},{"inf":"pouvoir","en":"can","forms":["peux","peux","peut","pouvons","pouvez","peuvent"],"tail":"venir"},{"inf":"devoir","en":"must","forms":["dois","dois","doit","devons","devez","doivent"],"tail":"travailler"},{"inf":"savoir","en":"to know how to","forms":["sais","sais","sait","savons","savez","savent"],"tail":"nager"}]},{"tool":"swap","title":"The second verb stays as it is","sub":"Pick a sentence and tap « Add the modal »: the first verb changes, the second goes back to its -er, -ir or -re form.","button":["Add the modal","Take it away"],"legend":[["x","the modal (it changes)"],["v","stays as it is"],["n","ne … pas"]],"items":[{"label":"Je pars.","en":["I am leaving.","I want to leave."],"a":[["s","Je",""],["v","pars.","v"]],"b":[["s","Je",""],["m","veux","x"],["v","partir.","v"]],"note":"Only <b>veux</b> changes; partir stays as it is."},{"label":"Tu viens ?","en":["Are you coming?","Can you come?"],"a":[["s","Tu",""],["v","viens ?","v"]],"b":[["s","Tu",""],["m","peux","x"],["v","venir ?","v"]],"note":"<b>peux</b> + venir."},{"label":"Il travaille.","en":["He works.","He must work."],"a":[["s","Il",""],["v","travaille.","v"]],"b":[["s","Il",""],["m","doit","x"],["v","travailler.","v"]],"note":"<b>doit</b> + travailler."},{"label":"Je nage.","en":["I swim.","I know how to swim."],"a":[["s","Je",""],["v","nage.","v"]],"b":[["s","Je",""],["m","sais","x"],["v","nager.","v"]],"note":"<b>sais</b> + nager."},{"label":"Nous ne partons pas.","en":["We are not leaving.","We don't want to leave."],"a":[["s","Nous",""],["ne","ne","n"],["v","partons","v"],["pas","pas.","n"]],"b":[["s","Nous",""],["ne","ne","n"],["m","voulons","x"],["pas","pas","n"],["v","partir.","v"]],"note":"The no goes round the <b>first</b> verb: ne voulons pas partir."}]},{"tool":"flip","title":"Polite: je voudrais","sub":"Tap a card: the softer, more polite way to ask.","cards":[{"a":"Je veux un café.","b":"Je voudrais un café.","tag":"more polite"},{"a":"Tu peux m'aider ?","b":"Tu pourrais m'aider ?","tag":"softer"},{"a":"Vous pouvez répéter ?","b":"Vous pourriez répéter ?","tag":"softer"},{"a":"Je veux réserver une table.","b":"Je voudrais réserver une table.","tag":"more polite"}]}],"practice":{"choose":[{"q":"Je ___ partir. (want)","en":"I want to leave.","opts":["veux","voulez","veut","voulons"],"a":"veux","why":"vouloir with je.","hint":"je <b>veux</b>."},{"q":"Nous ___ venir demain. (can)","en":"We can come tomorrow.","opts":["pouvons","peuvons","pouvez","peux"],"a":"pouvons","why":"pouvoir with nous.","hint":"nous <b>pouvons</b>."},{"q":"Tu ___ travailler. (must)","en":"You must work.","opts":["dois","doit","devoir","devez"],"a":"dois","why":"devoir with tu.","hint":"tu <b>dois</b>."},{"q":"Ils ___ nager. (know how to)","en":"They know how to swim.","opts":["savent","savons","sait","peuvent"],"a":"savent","why":"savoir with ils.","hint":"ils <b>savent</b>."},{"q":"Je veux ___.","en":"I want to leave.","opts":["partir","pars","part","partons"],"a":"partir","why":"The second verb…","hint":"It stays as it is: <b>partir</b>."},{"q":"Elle ne ___ pas venir. (can)","en":"She can't come.","opts":["peut","peux","pouvoir","peuvent"],"a":"peut","why":"pouvoir with elle.","hint":"elle <b>peut</b>."},{"q":"Je ___ un café, s'il vous plaît. (would like)","en":"I'd like a coffee, please.","opts":["voudrais","veux","voulez","voudrait"],"a":"voudrais","why":"The polite form with je.","hint":"je <b>voudrais</b>."}],"build":[{"en":"I want to leave.","tiles":["Je","veux","partir."],"trap":"pars","why":"The second verb stays as it is.","hint":"veux <b>partir</b>."},{"en":"Can you help me?","tiles":["Tu","peux","m'aider ?"],"trap":"aides","why":"The second verb stays as it is.","hint":"peux <b>m'aider</b>."},{"en":"We must work.","tiles":["Nous","devons","travailler."],"trap":"travaillons","why":"The second verb stays as it is.","hint":"devons <b>travailler</b>."},{"en":"She can't come.","tiles":["Elle","ne","peut","pas","venir."],"trap":"vient","why":"The no goes round the first verb.","hint":"ne <b>peut</b> pas venir."},{"en":"I'd like a coffee.","tiles":["Je","voudrais","un","café."],"trap":"veux","why":"The polite form…","hint":"je <b>voudrais</b>."}],"spot":[{"words":["Je","veux","pars."],"bad":2,"fix":"partir.","hint":"The second verb stays as it is: <b>partir</b>.","look":"Look at the second verb."},{"words":["Ils","peuvent","venons."],"bad":2,"fix":"venir.","hint":"The second verb stays as it is: <b>venir</b>.","look":"Look at the second verb."},{"words":["Tu","doit","partir."],"bad":1,"fix":"dois","hint":"devoir with tu: <b>dois</b>.","look":"Look at the first verb with tu."},{"words":["Elle","ne veut","partir pas."],"bad":2,"fix":"pas partir.","hint":"pas goes after the first verb: ne veut <b>pas</b> partir.","look":"Where does pas go?"},{"words":["Ils","savons","nager."],"bad":1,"fix":"savent","hint":"savoir with ils: <b>savent</b>.","look":"Look at the first verb with ils."}]},"drill":[["I want (vouloir)","je veux","vouloir: je <b>veux</b>."],["we can (pouvoir)","nous pouvons","pouvoir: nous <b>pouvons</b>."],["you (tu) must (devoir)","tu dois","devoir: tu <b>dois</b>."],["they know (savoir)","ils savent","savoir: ils <b>savent</b>."],["I want to leave.","Je veux partir.","The second verb stays as it is: <b>partir</b>."],["I'd like a coffee.","Je voudrais un café.","Polite: <b>je voudrais</b>."]]},"v6":{"line":"Learn one model and you know its family. <b>prendre</b>: je prends, nous prenons, ils prennent (→ comprendre, apprendre). <b>venir</b>: je viens, nous venons, ils viennent (→ devenir, revenir). <b>partir</b>: je pars, nous partons (→ sortir, dormir). <b>boire</b>: je bois, nous buvons, ils boivent.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"conj","title":"Four models","sub":"Pick a verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"prendre","en":"to take","forms":["prends","prends","prend","prenons","prenez","prennent"],"tail":"le train"},{"inf":"venir","en":"to come","forms":["viens","viens","vient","venons","venez","viennent"],"tail":"demain"},{"inf":"partir","en":"to leave","forms":["pars","pars","part","partons","partez","partent"],"tail":"à huit heures"},{"inf":"boire","en":"to drink","forms":["bois","bois","boit","buvons","buvez","boivent"],"tail":"de l'eau"}]},{"tool":"sort","title":"Which model?","sub":"Tap the model each verb follows.","boxes":[{"k":"prendre","label":"like prendre"},{"k":"venir","label":"like venir"},{"k":"partir","label":"like partir"}],"cards":[{"t":"comprendre","box":"prendre","why":"to understand: je comprends, ils comprennent"},{"t":"apprendre","box":"prendre","why":"to learn: j'apprends"},{"t":"devenir","box":"venir","why":"to become: il devient"},{"t":"revenir","box":"venir","why":"to come back: ils reviennent"},{"t":"sortir","box":"partir","why":"to go out: je sors, nous sortons"},{"t":"dormir","box":"partir","why":"to sleep: je dors, nous dormons"},{"t":"tenir","box":"venir","why":"to hold: je tiens, ils tiennent"},{"t":"surprendre","box":"prendre","why":"to surprise: il surprend"}]},{"tool":"flip","title":"Same family, same endings","sub":"Tap a card: the model turns into a verb of its family.","cards":[{"a":"je prends","b":"je comprends","tag":"prendre → comprendre"},{"a":"ils viennent","b":"ils deviennent","tag":"venir → devenir"},{"a":"nous partons","b":"nous sortons","tag":"partir → sortir"},{"a":"tu prends","b":"tu apprends","tag":"prendre → apprendre"},{"a":"il vient","b":"il revient","tag":"venir → revenir"},{"a":"je pars","b":"je dors","tag":"partir → dormir"}]}],"practice":{"choose":[{"q":"Je ___ le bus. (prendre)","en":"I take the bus.","opts":["prends","prend","prenons","prennent"],"a":"prends","why":"prendre with je.","hint":"je <b>prends</b>."},{"q":"Nous ___ du thé. (boire)","en":"We drink tea.","opts":["buvons","boivons","boisons","buvez"],"a":"buvons","why":"boire with nous has its own stem.","hint":"nous <b>buvons</b>."},{"q":"Ils ___ demain. (venir)","en":"They are coming tomorrow.","opts":["viennent","venent","vient","venons"],"a":"viennent","why":"venir with ils: double n.","hint":"ils <b>viennent</b>."},{"q":"Tu ___ à quelle heure ? (partir)","en":"What time are you leaving?","opts":["pars","part","partes","partez"],"a":"pars","why":"partir with tu.","hint":"tu <b>pars</b>."},{"q":"Vous ___ le français ? (comprendre)","en":"Do you understand French?","opts":["comprenez","comprendez","comprennent","comprends"],"a":"comprenez","why":"Like prendre with vous.","hint":"vous <b>comprenez</b>."},{"q":"Elles ___ le train. (prendre)","en":"They take the train.","opts":["prennent","prenent","prendent","prend"],"a":"prennent","why":"prendre with elles: double n.","hint":"elles <b>prennent</b>."},{"q":"Il ___ beaucoup. (dormir)","en":"He sleeps a lot.","opts":["dort","dors","dorme","dormit"],"a":"dort","why":"Like partir with il.","hint":"il <b>dort</b>."}],"build":[{"en":"I take the train.","tiles":["Je","prends","le","train."],"trap":"prend","why":"prendre with je.","hint":"je <b>prends</b>."},{"en":"They are coming tomorrow.","tiles":["Ils","viennent","demain."],"trap":"venent","why":"venir with ils.","hint":"ils <b>viennent</b>."},{"en":"We drink water.","tiles":["Nous","buvons","de l'","eau."],"trap":"boivons","why":"boire with nous.","hint":"nous <b>buvons</b>."},{"en":"You (tu) leave at eight.","tiles":["Tu","pars","à","huit heures."],"trap":"part","why":"partir with tu.","hint":"tu <b>pars</b>."},{"en":"Do you understand French?","tiles":["Vous","comprenez","le","français ?"],"trap":"comprendez","why":"Like prendre with vous.","hint":"vous <b>comprenez</b>."}],"spot":[{"words":["Ils","prendent","le bus."],"bad":1,"fix":"prennent","hint":"prendre with ils: <b>prennent</b>.","look":"Look at the verb with ils."},{"words":["Nous","boivons","du café."],"bad":1,"fix":"buvons","hint":"boire with nous: <b>buvons</b>.","look":"Look at the verb with nous."},{"words":["Elles","venent","ce soir."],"bad":1,"fix":"viennent","hint":"venir with elles: <b>viennent</b>.","look":"Look at the verb with elles."},{"words":["Je","part","demain."],"bad":1,"fix":"pars","hint":"partir with je: <b>pars</b>.","look":"Look at the ending with je."},{"words":["Vous","comprendez ?"],"bad":1,"fix":"comprenez ?","hint":"Like prendre: vous <b>comprenez</b>.","look":"Look at the verb with vous."}]},"drill":[["I take (prendre)","je prends","prendre: je <b>prends</b>."],["we drink (boire)","nous buvons","boire: nous <b>buvons</b>."],["they come (venir)","ils viennent","venir: ils <b>viennent</b>."],["you (tu) leave (partir)","tu pars","partir: tu <b>pars</b>."],["you (vous) understand (comprendre)","vous comprenez","Like prendre: vous prenez → vous <b>comprenez</b>."],["they drink (boire)","ils boivent","boire: ils <b>boivent</b>."]]},"7":{"line":"Three ways to ask the same yes/no question: <b>Tu viens ?</b> (your voice goes up: everyday), <b>Est-ce que tu viens ?</b> (everyday, very clear), <b>Viens-tu ?</b> (verb first with a hyphen: formal). With il or elle and a vowel, add <b>-t-</b>: A-t-il faim ? Question words go first or, in casual French, last: Où tu habites ? Tu habites où ?","words":"Où, quand, comment…: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:2\">Vocab 2 · Question Words</a>.","steps":[{"tool":"swap","title":"Make it a question","sub":"Pick a sentence and tap « Make it a question ».","button":["Make it a question","Back to the sentence"],"legend":[["x","added"],["v","the verb"]],"items":[{"label":"Tu viens. (voice up)","en":["You are coming.","Are you coming?"],"a":[["s","Tu",""],["v","viens.","v"]],"b":[["s","Tu",""],["v","viens ?","v"]],"note":"Same words: only your voice goes up. Everyday French."},{"label":"Vous habitez à Paris. (est-ce que)","en":["You live in Paris.","Do you live in Paris?"],"a":[["s","Vous",""],["v","habitez","v"],["o","à Paris.",""]],"b":[["q","Est-ce que","x"],["s","vous",""],["v","habitez","v"],["o","à Paris ?",""]],"note":"<b>Est-ce que</b> at the front: clear, and everyday."},{"label":"Tu as faim. (verb first)","en":["You are hungry.","Are you hungry?"],"a":[["s","Tu",""],["v","as","v"],["o","faim.",""]],"b":[["v","As-","v"],["s","tu",""],["o","faim ?",""]],"note":"The verb jumps first, with a hyphen: <b>As-tu</b> faim ? Formal."},{"label":"Il parle anglais. (-t-)","en":["He speaks English.","Does he speak English?"],"a":[["s","Il",""],["v","parle","v"],["o","anglais.",""]],"b":[["v","Parle-","v"],["t","t-","x"],["s","il",""],["o","anglais ?",""]],"note":"Two vowels meet (parle / il): add <b>-t-</b>."},{"label":"Tu habites à Lyon. (où)","en":["You live in Lyon.","Where do you live?"],"a":[["s","Tu",""],["v","habites","v"],["o","à Lyon.",""]],"b":[["s","Tu",""],["v","habites","v"],["w","où ?","x"]],"note":"Casual: the question word goes at the end. Also: <b>Où est-ce que</b> tu habites ?"}]},{"tool":"sort","title":"Casual, everyday or formal?","sub":"Tap the box for each question.","boxes":[{"k":"c","label":"Casual","sub":"only the voice goes up"},{"k":"e","label":"Everyday","sub":"est-ce que"},{"k":"f","label":"Formal","sub":"the verb first"}],"cards":[{"t":"Tu viens ce soir ?","box":"c"},{"t":"Est-ce que tu viens ?","box":"e"},{"t":"Viens-tu ce soir ?","box":"f"},{"t":"Vous parlez anglais ?","box":"c"},{"t":"Parlez-vous anglais ?","box":"f"},{"t":"Est-ce qu'il a faim ?","box":"e","why":"Before a vowel: est-ce <b>qu'</b>il."},{"t":"A-t-il faim ?","box":"f","why":"-t- between two vowels."},{"t":"Tu habites où ?","box":"c"}]}],"practice":{"choose":[{"q":"___ tu viens ?","en":"Are you coming?","opts":["Est-ce que","Est-ce","Que","Qu'est-ce"],"a":"Est-ce que","why":"The everyday question starter…","hint":"<b>Est-ce que</b> tu viens ?"},{"q":"___-tu faim ?","en":"Are you hungry?","opts":["As","A","Es","Ai"],"a":"As","why":"avoir with tu, verb first.","hint":"<b>As</b>-tu faim ?"},{"q":"Parle-___-il anglais ?","en":"Does he speak English?","opts":["t","s","l","il"],"a":"t","why":"Two vowels meet.","hint":"Parle-<b>t</b>-il ?"},{"q":"___ qu'elle est là ?","en":"Is she here?","opts":["Est-ce","Est-ce que","Est","Que"],"a":"Est-ce","why":"qu' is already there.","hint":"<b>Est-ce</b> qu'elle est là ?"},{"q":"Tu habites ___ ? (where)","en":"Where do you live?","opts":["où","ou","quand","qui"],"a":"où","why":"where, with its accent…","hint":"<b>où</b> (with an accent) = where; ou = or."},{"q":"___-vous français ?","en":"Are you French?","opts":["Êtes","Es","Est","Sont"],"a":"Êtes","why":"être with vous, verb first.","hint":"<b>Êtes</b>-vous français ?"},{"q":"Où ___ vous habitez ?","en":"Where do you live?","opts":["est-ce que","est-ce","que","qu'"],"a":"est-ce que","why":"After a question word…","hint":"Où <b>est-ce que</b> vous habitez ?"}],"build":[{"en":"Do you live in Paris? (est-ce que)","tiles":["Est-ce que","vous","habitez","à","Paris ?"],"trap":"Est-ce","why":"The whole starter…","hint":"<b>Est-ce que</b> vous …"},{"en":"Does he speak English? (verb first)","tiles":["Parle-t-il","anglais ?"],"trap":"Parle-il","why":"Two vowels meet.","hint":"<b>Parle-t-il</b> …"},{"en":"Where do you live? (casual)","tiles":["Tu","habites","où ?"],"trap":"ou","why":"where, with its accent.","hint":"… <b>où</b> ?"},{"en":"Is she here? (est-ce que)","tiles":["Est-ce","qu'elle","est","là ?"],"trap":"que elle","why":"Before a vowel…","hint":"Est-ce <b>qu'elle</b> …"},{"en":"Are you French? (verb first, vous)","tiles":["Êtes-vous","français ?"],"trap":"Es-vous","why":"être with vous.","hint":"<b>Êtes-vous</b> …"}],"spot":[{"words":["Parle-il","anglais ?"],"bad":0,"fix":"Parle-t-il","hint":"Two vowels meet: <b>-t-</b>.","look":"Look between the verb and il."},{"words":["Est-ce que","elle","vient ?"],"bad":0,"fix":"Est-ce qu'","hint":"Before a vowel: est-ce <b>qu'</b>elle.","look":"What happens to que before a vowel?","say":"Est-ce qu'elle vient ?"},{"words":["Tu","habites","ou ?"],"bad":2,"fix":"où ?","hint":"<b>où</b> = where (ou = or).","look":"Look at the question word."},{"words":["A-il","faim ?"],"bad":0,"fix":"A-t-il","hint":"Two vowels meet: <b>A-t-il</b>.","look":"Look between a and il."},{"words":["Est-ce","tu","viens ?"],"bad":0,"fix":"Est-ce que","hint":"The whole starter: <b>Est-ce que</b>.","look":"Something is missing at the start."}]},"drill":[["Est-ce que form: Vous habitez à Paris.","Est-ce que vous habitez à Paris ?","<b>Est-ce que</b> at the front."],["Invert: Tu as faim.","As-tu faim ?","Verb first, with a hyphen: <b>As-tu</b> …?"],["Invert: Il parle anglais.","Parle-t-il anglais ?","Two vowels meet: add <b>-t-</b>."],["Where do you live? (casual)","Tu habites où ?","Casual: the question word at the end."],["Est-ce que form: Elle est là.","Est-ce qu'elle est là ?","Before a vowel: est-ce <b>qu'</b>elle."],["Invert: Vous êtes français.","Êtes-vous français ?","Verb first: <b>Êtes-vous</b> …?"]]},"8":{"line":"An adjective matches its noun: <b>+e</b> for feminine, <b>+s</b> for plural (petit, petite, petits, petites). Most go <b>after</b> the noun: une voiture rouge. A few short ones go <b>before</b>: beauty, age, good, size (BAGS): une belle maison, un jeune homme, un bon ami, une petite ville. Watch: blanc → blanche, beau → bel before a vowel.","words":"Describing people: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:12\">Vocab 12 · Personality & Physical Description</a> · colours: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:14\">Vocab 14 · Les Couleurs</a>.","steps":[{"tool":"agree","title":"Switch the noun","sub":"Tap masculine, feminine or plural: what changes lights up.","cols":["masculine","feminine","masc. plural","fem. plural"],"rows":[{"forms":["un chat noir","une chatte noire","des chats noirs","des chattes noires"],"en":"a black cat"},{"forms":["un petit garçon","une petite fille","des petits garçons","des petites filles"],"en":"a little boy / girl"},{"forms":["un ami content","une amie contente","des amis contents","des amies contentes"],"en":"a happy friend"},{"forms":["un homme heureux","une femme heureuse","des hommes heureux","des femmes heureuses"],"en":"-eux → -euse"},{"forms":["un pull blanc","une robe blanche","des pulls blancs","des robes blanches"],"en":"blanc → blanche"},{"forms":["un livre rouge","une voiture rouge","des livres rouges","des voitures rouges"],"en":"-e already: no new e"}]},{"tool":"sort","title":"Before or after the noun?","sub":"Tap the box for each adjective.","boxes":[{"k":"b","label":"before","sub":"BAGS: beauty, age, good, size"},{"k":"a","label":"after","sub":"most: colour, nationality, shape, feelings"}],"cards":[{"t":"petit","box":"b","why":"Size: une <b>petite</b> ville."},{"t":"rouge","box":"a","why":"Colour: une voiture <b>rouge</b>."},{"t":"jeune","box":"b","why":"Age: un <b>jeune</b> homme."},{"t":"français","box":"a","why":"Nationality: un film <b>français</b>."},{"t":"bon","box":"b","why":"Good: un <b>bon</b> ami."},{"t":"intéressant","box":"a","why":"un livre <b>intéressant</b>."},{"t":"beau","box":"b","why":"Beauty: un <b>beau</b> jardin."},{"t":"rond","box":"a","why":"Shape: une table <b>ronde</b>."},{"t":"vieux","box":"b","why":"Age: un <b>vieux</b> livre."}]},{"tool":"flip","title":"Special forms","sub":"Tap a card.","cards":[{"a":"beau + homme","b":"un bel homme","tag":"beau → bel before a vowel"},{"a":"vieux + ami","b":"un vieil ami","tag":"vieux → vieil before a vowel"},{"a":"nouveau + hôtel","b":"un nouvel hôtel","tag":"nouveau → nouvel"},{"a":"blanc (feminine)","b":"blanche","tag":"-c → -che"},{"a":"long (feminine)","b":"longue","tag":"-g → -gue"},{"a":"beau (feminine)","b":"belle","tag":"beau → belle"}]}],"practice":{"choose":[{"q":"une voiture ___ (blanc)","en":"a white car","opts":["blanche","blance","blanc","blanches"],"a":"blanche","why":"blanc has a special feminine.","hint":"<b>blanche</b>."},{"q":"des chats ___ (noir)","en":"black cats","opts":["noirs","noir","noires","noire"],"a":"noirs","why":"Masculine, more than one.","hint":"<b>noirs</b>."},{"q":"un ___ homme (beau)","en":"a handsome man","opts":["bel","beau","belle","beaux"],"a":"bel","why":"homme starts with a silent h.","hint":"<b>bel</b> before a vowel."},{"q":"une ___ maison (petit)","en":"a small house","opts":["petite","petit","petites","petits"],"a":"petite","why":"One, feminine.","hint":"<b>petite</b>."},{"q":"une robe ___ (long)","en":"a long dress","opts":["longue","longe","long","longues"],"a":"longue","why":"long has a special feminine.","hint":"<b>longue</b>."},{"q":"des filles ___ (heureux)","en":"happy girls","opts":["heureuses","heureux","heureuse","heureuxes"],"a":"heureuses","why":"Feminine and more than one.","hint":"<b>heureuses</b>."},{"q":"un ___ ami (vieux)","en":"an old friend","opts":["vieil","vieux","vieille","vieilles"],"a":"vieil","why":"ami starts with a vowel.","hint":"<b>vieil</b> before a vowel."}],"build":[{"en":"I live in a small town.","tiles":["J'habite","dans","une","petite","ville."],"trap":"petit","why":"ville is feminine; petit goes before.","hint":"une <b>petite</b> ville."},{"en":"She has a red car.","tiles":["Elle","a","une","voiture","rouge."],"trap":"rouges","why":"One car; colours go after.","hint":"une voiture <b>rouge</b>."},{"en":"He is a young man.","tiles":["C'est","un","jeune","homme."],"trap":"jeunes","why":"Age goes before.","hint":"un <b>jeune</b> homme."},{"en":"Two happy girls.","tiles":["Deux","filles","heureuses."],"trap":"heureux","why":"Feminine and more than one.","hint":"filles <b>heureuses</b>."},{"en":"It's a beautiful house.","tiles":["C'est","une","belle","maison."],"trap":"beau","why":"maison is feminine.","hint":"une <b>belle</b> maison."}],"spot":[{"words":["une","voiture","blanc."],"bad":2,"fix":"blanche.","hint":"Feminine: <b>blanche</b>.","look":"Does the adjective match voiture?"},{"words":["un","beau","homme."],"bad":1,"fix":"bel","hint":"Before a vowel: <b>bel</b>.","look":"homme starts with a silent h."},{"words":["une","maison petite."],"bad":1,"fix":"petite maison.","hint":"Size goes before: une <b>petite maison</b>.","look":"Where does petit go?"},{"words":["des","chats","noir."],"bad":2,"fix":"noirs.","hint":"More than one: <b>noirs</b>.","look":"How many cats?"},{"words":["une","rouge voiture."],"bad":1,"fix":"voiture rouge.","hint":"Colours go after: une <b>voiture rouge</b>.","look":"Where do colours go?"}]},"drill":[["une voiture (blanc)","une voiture blanche","blanc → <b>blanche</b>."],["des chats (noir)","des chats noirs","Plural: <b>+s</b>."],["un (beau) homme","un bel homme","Before a vowel: <b>bel</b>."],["une maison (petit)","une petite maison","Size goes before, + e: une <b>petite</b> maison."],["une robe (long)","une robe longue","long → <b>longue</b>."],["des filles (heureux)","des filles heureuses","-eux → <b>-euse</b>, plural <b>-euses</b>."]]},"9":{"line":"my: <b>mon / ma / mes</b> · your: ton / ta / tes · his or her: <b>son / sa / ses</b> · our: notre / nos · your: votre / vos · their: leur / leurs. They agree with the <b>thing owned</b>: sa voiture = his car or her car. Before a vowel: <b>mon</b> amie. this: <b>ce / cet</b> (before a vowel) <b>/ cette / ces</b>.","words":"The family: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:9\">Vocab 9 · La Famille</a>.","steps":[{"tool":"agree","title":"Switch the thing owned","sub":"Tap masculine, feminine or plural: the little word follows the thing, not the owner.","cols":["masculine","feminine","plural"],"rows":[{"forms":["mon frère","ma sœur","mes frères"],"en":["my brother","my sister","my brothers"]},{"forms":["ton père","ta mère","tes parents"],"en":["your father","your mother","your parents"]},{"forms":["son livre","sa voiture","ses clés"],"en":["his / her book","his / her car","his / her keys"]},{"forms":["notre ami","notre amie","nos amis"],"en":["our friend","our friend","our friends"]},{"forms":["leur chat","leur maison","leurs enfants"],"en":["their cat","their house","their children"]},{"forms":["ce livre","cette table","ces livres"],"en":["this book","this table","these books"]}]},{"tool":"sort","title":"son, sa or ses?","sub":"Look at the thing, not at who owns it. Tap the box.","boxes":[{"k":"son","label":"son","sub":"masculine, or before a vowel"},{"k":"sa","label":"sa","sub":"feminine"},{"k":"ses","label":"ses","sub":"more than one"}],"cards":[{"t":"Paul: … voiture","box":"sa","why":"voiture is feminine: <b>sa</b> voiture, even for Paul.","say":"sa voiture"},{"t":"Marie: … vélo","box":"son","why":"vélo is masculine: <b>son</b> vélo, even for Marie.","say":"son vélo"},{"t":"Paul: … sœurs","box":"ses","why":"More than one: <b>ses</b> sœurs.","say":"ses sœurs"},{"t":"Marie: … père","box":"son","why":"<b>son</b> père.","say":"son père"},{"t":"Marie: … amie","box":"son","why":"amie starts with a vowel: <b>son</b> amie.","say":"son amie"},{"t":"Paul: … maison","box":"sa","why":"<b>sa</b> maison.","say":"sa maison"},{"t":"Marie: … livres","box":"ses","why":"<b>ses</b> livres.","say":"ses livres"}]},{"tool":"flip","title":"Before a vowel","sub":"Tap a card: ma, ta, sa and ce change before a vowel.","cards":[{"a":"ma + amie","b":"mon amie","tag":"ma → mon"},{"a":"ta + école","b":"ton école","tag":"ta → ton"},{"a":"sa + histoire","b":"son histoire","tag":"sa → son (silent h)"},{"a":"ce + hôtel","b":"cet hôtel","tag":"ce → cet"},{"a":"ce + arbre","b":"cet arbre","tag":"ce → cet"},{"a":"ce + garçon","b":"ce garçon","tag":"no vowel: no change"}]}],"practice":{"choose":[{"q":"___ sœur (my)","en":"my sister","opts":["ma","mon","mes","me"],"a":"ma","why":"sœur is feminine.","hint":"<b>ma</b> sœur."},{"q":"___ amie (my)","en":"my friend (a woman)","opts":["mon","ma","m'","mes"],"a":"mon","why":"amie starts with a vowel.","hint":"Before a vowel: <b>mon</b> amie."},{"q":"___ hôtel (this)","en":"this hotel","opts":["cet","ce","cette","ces"],"a":"cet","why":"hôtel starts with a silent h.","hint":"<b>cet</b> hôtel."},{"q":"___ maison (this)","en":"this house","opts":["cette","cet","ce","ces"],"a":"cette","why":"maison is feminine.","hint":"<b>cette</b> maison."},{"q":"Paul aime ___ voiture.","en":"Paul loves his car.","opts":["sa","son","ses","leur"],"a":"sa","why":"Look at voiture, not at Paul.","hint":"voiture is feminine: <b>sa</b>."},{"q":"Ils aiment ___ enfants.","en":"They love their children.","opts":["leurs","leur","ses","son"],"a":"leurs","why":"Their, and more than one child.","hint":"<b>leurs</b> enfants."},{"q":"___ livres (these)","en":"these books","opts":["ces","ses","cettes","cet"],"a":"ces","why":"these, not his…","hint":"<b>ces</b> livres (ses = his / her)."}],"build":[{"en":"This is my friend Julie.","tiles":["C'est","mon","amie","Julie."],"trap":"ma","why":"amie starts with a vowel.","hint":"<b>mon</b> amie."},{"en":"Paul washes his car.","tiles":["Paul","lave","sa","voiture."],"trap":"son","why":"voiture is feminine.","hint":"<b>sa</b> voiture."},{"en":"This hotel is big.","tiles":["Cet","hôtel","est","grand."],"trap":"Ce","why":"hôtel starts with a silent h.","hint":"<b>cet</b> hôtel."},{"en":"Their children are here.","tiles":["Leurs","enfants","sont","là."],"trap":"Ses","why":"Their, more than one.","hint":"<b>leurs</b> enfants."},{"en":"I like these shoes.","tiles":["J'aime","ces","chaussures."],"trap":"ses","why":"these…","hint":"<b>ces</b> chaussures."}],"spot":[{"words":["C'est","ma","amie."],"bad":1,"fix":"mon","hint":"Before a vowel: <b>mon</b> amie.","look":"amie starts with a vowel."},{"words":["Ce","hôtel","est loin."],"bad":0,"fix":"Cet","hint":"Before a vowel: <b>cet</b>.","look":"hôtel starts with a silent h."},{"words":["Marie aime","son","voiture."],"bad":1,"fix":"sa","hint":"voiture is feminine: <b>sa</b>.","look":"Look at the thing, not the owner."},{"words":["Ils voient","leur","enfants."],"bad":1,"fix":"leurs","hint":"More than one: <b>leurs</b>.","look":"How many children?"},{"words":["J'aime","cette","livre."],"bad":1,"fix":"ce","hint":"livre is masculine: <b>ce</b>.","look":"Is livre masculine or feminine?"}]},"drill":[["___ sœur (my)","ma sœur","Feminine: <b>ma</b>."],["___ amie (my)","mon amie","Before a vowel: <b>mon</b>, even feminine."],["___ hôtel (this)","cet hôtel","Before a vowel: <b>cet</b>."],["___ maison (this)","cette maison","Feminine: <b>cette</b>."],["___ voiture (his)","sa voiture","voiture is feminine: <b>sa</b>, whoever owns it."],["___ enfants (their)","leurs enfants","More than one: <b>leurs</b>."]]},"11":{"line":"<b>C'est</b> + a name, or + un / le / mon … + a noun: c'est Paul, c'est un médecin, c'est mon frère. <b>Il / elle est</b> + an adjective, or a job with <b>no article</b>: il est grand, elle est infirmière. About a thing or an idea: c'est beau, c'est facile.","words":"The jobs: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:11\">Vocab 11 · Professions & Occupations</a>.","steps":[{"tool":"sort","title":"c'est or il / elle est?","sub":"Tap the box for each ending.","boxes":[{"k":"c","label":"C'est","sub":"+ a name, or un / le / mon + a noun"},{"k":"i","label":"Il / elle est","sub":"+ an adjective, or a job alone"}],"cards":[{"t":"… Paul.","box":"c","why":"A name: <b>c'est</b> Paul.","say":"C'est Paul."},{"t":"… médecin.","box":"i","why":"A job alone: <b>il est</b> médecin.","say":"Il est médecin."},{"t":"… un bon médecin.","box":"c","why":"un + a noun: <b>c'est</b> un bon médecin.","say":"C'est un bon médecin."},{"t":"… très grand. (Paul)","box":"i","why":"An adjective: <b>il est</b> très grand.","say":"Il est très grand."},{"t":"… mon frère.","box":"c","why":"mon + a noun: <b>c'est</b> mon frère.","say":"C'est mon frère."},{"t":"… infirmière. (Marie)","box":"i","why":"A job alone: <b>elle est</b> infirmière.","say":"Elle est infirmière."},{"t":"… une amie.","box":"c","why":"une + a noun: <b>c'est</b> une amie.","say":"C'est une amie."},{"t":"… fatiguée. (Léa)","box":"i","why":"An adjective: <b>elle est</b> fatiguée.","say":"Elle est fatiguée."}]},{"tool":"swap","title":"Add un or une, change the start","sub":"Pick a sentence and tap « Add un / une »: il est becomes c'est.","button":["Add un / une","Take it away"],"legend":[["x","the start"],["p","un / une (+ adjective)"]],"items":[{"label":"Il est médecin.","en":["He is a doctor.","He is a good doctor."],"a":[["s","Il est","x"],["o","médecin.",""]],"b":[["s2","C'est","x"],["a","un","p"],["ad","bon","p"],["o","médecin.",""]],"note":"With un / une, <b>il est</b> becomes <b>c'est</b>."},{"label":"Elle est professeure.","en":["She is a teacher.","She is a nice teacher."],"a":[["s","Elle est","x"],["o","professeure.",""]],"b":[["s2","C'est","x"],["a","une","p"],["o","professeure",""],["ad","sympa.","p"]],"note":"<b>c'est une</b> professeure sympa."},{"label":"Il est français.","en":["He is French.","He is a French friend."],"a":[["s","Il est","x"],["o","français.",""]],"b":[["s2","C'est","x"],["a","un","p"],["n","ami","p"],["o","français.",""]],"note":"An adjective alone: il est. un + a noun: <b>c'est</b>."}]}],"practice":{"choose":[{"q":"___ un livre intéressant.","en":"It's an interesting book.","opts":["C'est","Il est","Elle est","Ce"],"a":"C'est","why":"un + a noun follows.","hint":"un + noun: <b>c'est</b>."},{"q":"Marie ? ___ infirmière.","en":"Marie? She is a nurse.","opts":["Elle est","C'est","Elle est une","C'est une"],"a":"Elle est","why":"A job with no article…","hint":"A job alone: <b>elle est</b> infirmière."},{"q":"___ mon frère.","en":"This is my brother.","opts":["C'est","Il est","Il","Ce sont"],"a":"C'est","why":"mon + a noun follows.","hint":"<b>c'est</b> mon frère."},{"q":"Paul ? ___ très grand.","en":"Paul? He is very tall.","opts":["Il est","C'est","Il a","Ce"],"a":"Il est","why":"An adjective follows, about a person.","hint":"<b>il est</b> très grand."},{"q":"Il est ___.","en":"He is a doctor.","opts":["médecin","un médecin","le médecin","une médecin"],"a":"médecin","why":"After il est, a job…","hint":"No article: il est <b>médecin</b>."},{"q":"C'est ___ bon médecin.","en":"He is a good doctor.","opts":["un","le","de","des"],"a":"un","why":"After c'est, a noun takes…","hint":"<b>c'est un</b> bon médecin."},{"q":"Le film ? ___ génial !","en":"The film? It is great!","opts":["C'est","Il est","Elle est","Ce sont"],"a":"C'est","why":"An opinion about a thing…","hint":"Your opinion of a thing: <b>c'est</b> génial."}],"build":[{"en":"She is a nurse.","tiles":["Elle","est","infirmière."],"trap":"une","why":"A job alone: no article.","hint":"elle est <b>infirmière</b>."},{"en":"This is my brother.","tiles":["C'est","mon","frère."],"trap":"Il est","why":"mon + a noun…","hint":"<b>c'est</b> mon frère."},{"en":"He is very tall.","tiles":["Il","est","très","grand."],"trap":"C'est","why":"An adjective about a person…","hint":"<b>il est</b> très grand."},{"en":"It's an interesting book.","tiles":["C'est","un","livre","intéressant."],"trap":"Il est","why":"un + a noun…","hint":"<b>c'est</b> un livre."},{"en":"He is a good doctor.","tiles":["C'est","un","bon","médecin."],"trap":"Il est","why":"un + a noun…","hint":"<b>c'est</b> un bon médecin."}],"spot":[{"words":["Il est","un bon","médecin."],"bad":0,"fix":"C'est","hint":"un + a noun: <b>c'est</b>.","look":"Look at the start."},{"words":["Paul ?","C'est","très grand."],"bad":1,"fix":"Il est","hint":"An adjective about a person: <b>il est</b>.","look":"Is it an adjective or a noun after it?"},{"words":["Il est","mon","frère."],"bad":0,"fix":"C'est","hint":"mon + a noun: <b>c'est</b>.","look":"Look at the start."},{"words":["Marie ?","Elle est","une infirmière."],"bad":2,"fix":"infirmière.","hint":"A job after elle est: no article.","look":"Look after elle est."},{"words":["Il est","Paul."],"bad":0,"fix":"C'est","hint":"A name: <b>c'est</b> Paul.","look":"Look at the start."}]},"drill":[["___ un livre intéressant","C'est un livre intéressant.","un + a noun: <b>c'est</b>."],["She is a nurse","Elle est infirmière.","A job alone: <b>elle est</b> infirmière, no article."],["This is my brother","C'est mon frère. / Voici mon frère.","mon + a noun: <b>c'est</b> mon frère."],["He is very tall","Il est très grand.","An adjective: <b>il est</b> grand."],["He is French.","Il est français.","An adjective: <b>il est</b> français."],["He is a French friend.","C'est un ami français.","un + a noun: <b>c'est</b> un ami."]]},"13":{"line":"What is going to happen: <b>aller</b> in the present + the verb as it is: je <b>vais</b> manger, tu vas partir, il va pleuvoir, nous allons voir. The no goes round aller: je <b>ne vais pas</b> partir. It is the usual way to talk about plans.","words":"","steps":[{"tool":"line","title":"On the time line","sub":"Tap a point: before now, now, or what is going to happen.","now":"","marks":[{"at":-0.8,"label":"hier","fr":"Hier, j'ai mangé chez moi.","en":"Yesterday I ate at home.","note":"Before now: the passé composé (in A2)."},{"at":0.0,"label":"maintenant","fr":"Je mange.","en":"I am eating.","note":"Now: the present."},{"at":0.3,"label":"ce soir","fr":"Ce soir, je vais manger au restaurant.","html":"Ce soir, je <span class=\"gt-end\">vais manger</span> au restaurant.","en":"Tonight I'm going to eat at the restaurant."},{"at":0.6,"label":"demain","fr":"Demain, il va pleuvoir.","html":"Demain, il <span class=\"gt-end\">va pleuvoir</span>.","en":"Tomorrow it's going to rain."},{"at":0.92,"label":"l'été prochain","fr":"L'été prochain, nous allons voyager.","html":"L'été prochain, nous <span class=\"gt-end\">allons voyager</span>.","en":"Next summer we're going to travel."}]},{"tool":"swap","title":"Now → soon","sub":"Pick a sentence and tap « Make it the future »: aller comes in, the verb goes back to its -er, -ir or -re form.","button":["Make it the future","Back to now"],"legend":[["x","aller"],["v","the verb"],["n","ne … pas"]],"items":[{"label":"Je mange.","en":["I am eating.","I am going to eat."],"a":[["s","Je",""],["v","mange.","v"]],"b":[["s","Je",""],["a","vais","x"],["v","manger.","v"]]},{"label":"Nous partons.","en":["We are leaving.","We are going to leave."],"a":[["s","Nous",""],["v","partons.","v"]],"b":[["s","Nous",""],["a","allons","x"],["v","partir.","v"]]},{"label":"Il pleut.","en":["It's raining.","It's going to rain."],"a":[["s","Il",""],["v","pleut.","v"]],"b":[["s","Il",""],["a","va","x"],["v","pleuvoir.","v"]]},{"label":"Elle ne part pas.","en":["She isn't leaving.","She isn't going to leave."],"a":[["s","Elle",""],["ne","ne","n"],["v","part","v"],["pas","pas.","n"]],"b":[["s","Elle",""],["ne","ne","n"],["a","va","x"],["pas","pas","n"],["v","partir.","v"]],"note":"The no goes round <b>va</b>: elle ne va pas partir."}]},{"tool":"conj","title":"aller + the verb","sub":"Tap a person: only aller changes.","neg":true,"verbs":[{"inf":"manger","en":"going to eat","forms":["vais","vas","va","allons","allez","vont"],"tail":"manger"},{"inf":"partir","en":"going to leave","forms":["vais","vas","va","allons","allez","vont"],"tail":"partir"}]}],"practice":{"choose":[{"q":"Nous ___ manger.","en":"We are going to eat.","opts":["allons","allez","vont","vais"],"a":"allons","why":"aller with nous.","hint":"nous <b>allons</b> manger."},{"q":"Je vais ___ demain.","en":"I'm going to leave tomorrow.","opts":["partir","pars","part","parti"],"a":"partir","why":"After vais, the verb…","hint":"It stays as it is: <b>partir</b>."},{"q":"Il ___ pleuvoir.","en":"It's going to rain.","opts":["va","vas","vais","est"],"a":"va","why":"aller with il.","hint":"il <b>va</b> pleuvoir."},{"q":"Elle ne ___ pas venir.","en":"She isn't going to come.","opts":["va","vas","vais","vont"],"a":"va","why":"aller with elle.","hint":"elle ne <b>va</b> pas venir."},{"q":"Ils ___ voyager.","en":"They are going to travel.","opts":["vont","allent","va","allons"],"a":"vont","why":"aller with ils.","hint":"ils <b>vont</b> voyager."},{"q":"Tu ___ voir.","en":"You're going to see.","opts":["vas","va","vais","allez"],"a":"vas","why":"aller with tu.","hint":"tu <b>vas</b> voir."},{"q":"Je ___ t'appeler.","en":"I'm going to call you.","opts":["vais","va","vas","suis"],"a":"vais","why":"aller with je.","hint":"je <b>vais</b> t'appeler."}],"build":[{"en":"We are going to eat.","tiles":["Nous","allons","manger."],"trap":"mangeons","why":"The second verb stays as it is.","hint":"allons <b>manger</b>."},{"en":"She isn't going to leave.","tiles":["Elle","ne","va","pas","partir."],"trap":"part","why":"The no goes round va.","hint":"ne <b>va</b> pas partir."},{"en":"It's going to rain.","tiles":["Il","va","pleuvoir."],"trap":"pleut","why":"The second verb stays as it is.","hint":"va <b>pleuvoir</b>."},{"en":"I'm going to call you.","tiles":["Je","vais","t'appeler."],"trap":"appelle","why":"The second verb stays as it is.","hint":"vais <b>t'appeler</b>."},{"en":"They are going to travel.","tiles":["Ils","vont","voyager."],"trap":"voyagent","why":"The second verb stays as it is.","hint":"vont <b>voyager</b>."}],"spot":[{"words":["Je","vais","mange."],"bad":2,"fix":"manger.","hint":"The second verb stays as it is: <b>manger</b>.","look":"Look at the second verb."},{"words":["Nous","allez","partir."],"bad":1,"fix":"allons","hint":"aller with nous: <b>allons</b>.","look":"Look at aller with nous."},{"words":["Elle","va pas","venir."],"bad":1,"fix":"ne va pas","hint":"The full no: <b>ne va pas</b>.","look":"Something is missing in the no."},{"words":["Il","va","pleut."],"bad":2,"fix":"pleuvoir.","hint":"The second verb stays as it is: <b>pleuvoir</b>.","look":"Look at the second verb."},{"words":["Ils","allent","voyager."],"bad":1,"fix":"vont","hint":"aller with ils: <b>vont</b>.","look":"Look at aller with ils."}]},"drill":[["We are going to eat","Nous allons manger. / On va manger.","aller + the verb as it is: nous <b>allons</b> manger."],["She isn't going to leave","Elle ne va pas partir.","The no goes round aller: elle <b>ne va pas</b> partir."],["I'm going to call you","Je vais t'appeler. / Je vais vous appeler. / Je vais te téléphoner.","je <b>vais</b> + the verb."],["It's going to rain","Il va pleuvoir.","il <b>va</b> pleuvoir."],["They are going to travel.","Ils vont voyager.","ils <b>vont</b> + the verb as it is."],["I'm going to eat.","Je vais manger.","je <b>vais</b> manger."]]},"14":{"line":"To tell someone to do something, take the <b>tu, nous</b> or <b>vous</b> form and drop the subject: Parle ! Parlons ! Parlez ! For -er verbs (and aller), the tu form loses its -s: tu manges → <b>Mange !</b> The no goes round the verb: <b>Ne</b> parle <b>pas</b> ! A few are special: sois, soyez (être), aie (avoir).","words":"","steps":[{"tool":"swap","title":"Drop the subject","sub":"Pick a sentence and tap « Make it an order ».","button":["Make it an order","Back to the sentence"],"legend":[["v","the verb"],["n","ne … pas"]],"items":[{"label":"Tu parles.","en":["You speak.","Speak!"],"a":[["s","Tu",""],["v","parles.","v"]],"b":[["v","Parle !","v"]],"note":"-er verbs: tu parles → <b>Parle !</b> (no -s)."},{"label":"Vous entrez.","en":["You come in.","Come in!"],"a":[["s","Vous",""],["v","entrez.","v"]],"b":[["v","Entrez !","v"]],"note":"Polite, or to several people: <b>Entrez !</b>"},{"label":"Nous partons.","en":["We are leaving.","Let's go!"],"a":[["s","Nous",""],["v","partons.","v"]],"b":[["v","Partons !","v"]],"note":"The nous form = « let's »: <b>Partons !</b>"},{"label":"Tu attends.","en":["You wait.","Wait!"],"a":[["s","Tu",""],["v","attends.","v"]],"b":[["v","Attends !","v"]],"note":"Not an -er verb: the -s stays: <b>Attends !</b>"},{"label":"Tu ne parles pas.","en":["You don't speak.","Don't speak!"],"a":[["s","Tu",""],["ne","ne","n"],["v","parles","v"],["pas","pas.","n"]],"b":[["ne","Ne","n"],["v","parle","v"],["pas","pas !","n"]],"note":"The no goes round the verb: <b>Ne parle pas !</b>"},{"label":"Tu vas au lit.","en":["You go to bed.","Go to bed!"],"a":[["s","Tu",""],["v","vas","v"],["o","au lit.",""]],"b":[["v","Va","v"],["o","au lit !",""]],"note":"aller loses its -s too: <b>Va !</b>"}]},{"tool":"sort","title":"tu, nous or vous?","sub":"Who is it for? Tap the box.","boxes":[{"k":"tu","label":"tu","sub":"one person you know well"},{"k":"nous","label":"nous","sub":"let's (you and me)"},{"k":"vous","label":"vous","sub":"polite, or several"}],"cards":[{"t":"Viens !","box":"tu"},{"t":"Venez !","box":"vous"},{"t":"Allons-y !","box":"nous","why":"<b>Allons-y</b> = let's go."},{"t":"Mange !","box":"tu"},{"t":"Écoutez !","box":"vous"},{"t":"Partons !","box":"nous"},{"t":"Attends !","box":"tu"}]},{"tool":"flip","title":"The special ones","sub":"Tap a card.","cards":[{"a":"être (tu)","b":"Sois sage !","tag":"être → sois","en":"be good"},{"a":"être (vous)","b":"Soyez à l'heure !","tag":"être → soyez","en":"be on time"},{"a":"avoir (tu)","b":"N'aie pas peur !","tag":"avoir → aie","en":"don't be afraid"},{"a":"aller (tu)","b":"Va !","tag":"tu vas → va","en":"go"},{"a":"faire (tu)","b":"Fais attention !","tag":"faire → fais","en":"be careful"}]}],"practice":{"choose":[{"q":"Tell a friend: ___ ! (wait)","en":"Wait!","opts":["Attends","Attend","Attendez","Tu attends"],"a":"Attends","why":"A friend: the tu form, no subject.","hint":"<b>Attends !</b>"},{"q":"Tell your boss: ___ ! (come in)","en":"Come in!","opts":["Entrez","Entre","Entrons","Vous entrez"],"a":"Entrez","why":"Polite: the vous form, no subject.","hint":"<b>Entrez !</b>"},{"q":"___ ! (Let's go)","en":"Let's go!","opts":["Allons-y","Allez-y","Va","Vont"],"a":"Allons-y","why":"Let's = the nous form.","hint":"<b>Allons-y !</b>"},{"q":"___ ! (eat, tu)","en":"Eat!","opts":["Mange","Manges","Mangez","Tu manges"],"a":"Mange","why":"-er verbs with tu lose something.","hint":"<b>Mange !</b> (no -s)."},{"q":"Ne ___ pas en retard ! (tu, être)","en":"Don't be late!","opts":["sois","es","être","soit"],"a":"sois","why":"être has a special form.","hint":"Ne <b>sois</b> pas en retard !"},{"q":"___ attention ! (tu, faire)","en":"Be careful!","opts":["Fais","Fait","Faire","Faites"],"a":"Fais","why":"faire with tu.","hint":"<b>Fais</b> attention !"},{"q":"Ne ___ pas ! (tu, parler)","en":"Don't speak!","opts":["parle","parles","parlez","parler"],"a":"parle","why":"-er verbs with tu…","hint":"Ne <b>parle</b> pas !"}],"build":[{"en":"Come in, please! (vous)","tiles":["Entrez,","s'il","vous","plaît !"],"trap":"Vous entrez","why":"No subject in an order.","hint":"<b>Entrez</b>, …"},{"en":"Don't be late! (tu)","tiles":["Ne","sois","pas","en retard !"],"trap":"es","why":"être has a special form.","hint":"Ne <b>sois</b> pas …"},{"en":"Let's go to the park!","tiles":["Allons","au","parc !"],"trap":"Nous","why":"No subject in an order.","hint":"<b>Allons</b> au parc !"},{"en":"Eat your soup! (tu)","tiles":["Mange","ta","soupe !"],"trap":"Manges","why":"-er verbs with tu lose the -s.","hint":"<b>Mange</b> ta soupe !"},{"en":"Don't talk! (vous)","tiles":["Ne","parlez","pas !"],"trap":"Vous","why":"No subject in an order.","hint":"Ne <b>parlez</b> pas !"}],"spot":[{"words":["Manges","ta soupe !"],"bad":0,"fix":"Mange","hint":"-er verbs lose the -s: <b>Mange !</b>","look":"Look at the end of the verb."},{"words":["Tu attends !"],"bad":0,"fix":"Attends !","hint":"No subject in an order: <b>Attends !</b>","look":"Is the subject needed?"},{"words":["Ne","es","pas en retard !"],"bad":1,"fix":"sois","hint":"être: <b>sois</b>.","look":"être has a special form."},{"words":["Parle","pas !"],"bad":0,"fix":"Ne parle","hint":"The full no: <b>Ne parle pas !</b>","look":"Something is missing in the no."},{"words":["Vas","au lit !"],"bad":0,"fix":"Va","hint":"aller loses its -s: <b>Va !</b>","look":"Look at the end of the verb."}]},"drill":[["Tell a friend: wait!","Attends !","The tu form, no subject: <b>Attends !</b>"],["Tell your boss: come in!","Entrez !","Polite: the vous form, <b>Entrez !</b>"],["Let's go!","Allons-y ! / On y va !","Let's = the nous form: <b>Allons-y !</b>"],["Don't be late (tu)","Ne sois pas en retard !","être → <b>sois</b>; the no goes round it."],["Tell a friend: eat!","Mange !","-er verbs drop the -s: <b>Mange !</b>"],["Tell two friends: listen!","Écoutez !","More than one person: the vous form, <b>Écoutez !</b>"]]},"24":{"line":"Three phrases with a verb that stays as it is: <b>venir de</b> = has just (elle <b>vient d'</b>arriver), <b>être en train de</b> = is busy doing right now (il <b>est en train de</b> cuisiner), <b>aller</b> = is going to (je <b>vais</b> partir). Only the first verb changes.","words":"","steps":[{"tool":"line","title":"Just now, right now, soon","sub":"Tap a point on the line.","now":"","marks":[{"at":-0.55,"label":"just now","fr":"Elle vient d'arriver.","html":"Elle <span class=\"gt-end\">vient d'</span>arriver.","en":"She has just arrived.","note":"<b>venir de</b> + the verb: it has just happened."},{"at":0.0,"label":"right now","fr":"Il est en train de cuisiner.","html":"Il <span class=\"gt-end\">est en train de</span> cuisiner.","en":"He is busy cooking.","note":"<b>être en train de</b> + the verb: it is happening right now."},{"at":0.55,"label":"soon","fr":"Nous allons partir.","html":"Nous <span class=\"gt-end\">allons</span> partir.","en":"We are going to leave.","note":"<b>aller</b> + the verb: it is going to happen."}]},{"tool":"swap","title":"Add the phrase","sub":"Pick a sentence and tap « Add it »: the phrase comes in, the verb goes back to its -er, -ir or -re form.","button":["Add it","Take it away"],"legend":[["x","the phrase (it changes)"],["v","stays as it is"]],"items":[{"label":"Elle arrive. (venir de)","en":["She arrives.","She has just arrived."],"a":[["s","Elle",""],["v","arrive.","v"]],"b":[["s","Elle",""],["m","vient d'","x"],["v","arriver.","v"]],"note":"de before a vowel: vient <b>d'</b>arriver."},{"label":"Je mange. (venir de)","en":["I eat.","I have just eaten."],"a":[["s","Je",""],["v","mange.","v"]],"b":[["s","Je",""],["m","viens de","x"],["v","manger.","v"]]},{"label":"Il cuisine. (en train de)","en":["He cooks.","He is busy cooking."],"a":[["s","Il",""],["v","cuisine.","v"]],"b":[["s","Il",""],["m","est en train de","x"],["v","cuisiner.","v"]]},{"label":"Nous travaillons. (en train de)","en":["We work.","We are busy working."],"a":[["s","Nous",""],["v","travaillons.","v"]],"b":[["s","Nous",""],["m","sommes en train de","x"],["v","travailler.","v"]]},{"label":"Tu peux. (pouvoir + verb)","en":["You can.","Can you help me?"],"a":[["s","Tu",""],["m","peux.","x"]],"b":[["s","Tu",""],["m","peux","x"],["v","m'aider ?","v"]],"note":"A modal works the same way: <b>peux</b> + aider."}]},{"tool":"conj","title":"venir de, person by person","sub":"Tap a person: only venir changes.","neg":false,"verbs":[{"inf":"venir de","en":"has just","forms":["viens de","viens de","vient de","venons de","venez de","viennent de"],"tail":"manger"},{"inf":"être en train de","en":"is busy","forms":["suis en train de","es en train de","est en train de","sommes en train de","êtes en train de","sont en train de"],"tail":"lire"}]}],"practice":{"choose":[{"q":"Elle ___ d'arriver.","en":"She has just arrived.","opts":["vient","va","est","a"],"a":"vient","why":"has just = venir de.","hint":"elle <b>vient d'</b>arriver."},{"q":"Il est ___ de cuisiner.","en":"He is busy cooking.","opts":["en train","en cours","train","entrain"],"a":"en train","why":"busy doing = être en train de.","hint":"il est <b>en train de</b> cuisiner."},{"q":"Nous venons de ___.","en":"We have just eaten.","opts":["manger","mangé","mangeons","mange"],"a":"manger","why":"After venir de, the verb…","hint":"It stays as it is: <b>manger</b>."},{"q":"Ils ___ de partir.","en":"They have just left.","opts":["viennent","venent","vont","sont"],"a":"viennent","why":"venir with ils.","hint":"ils <b>viennent</b> de partir."},{"q":"Je suis en train ___ lire.","en":"I am busy reading.","opts":["de","à","du","pour"],"a":"de","why":"en train …","hint":"en train <b>de</b> lire."},{"q":"___-vous m'aider ?","en":"Can you help me?","opts":["Pouvez","Pouvons","Peux","Peut"],"a":"Pouvez","why":"pouvoir with vous, verb first.","hint":"<b>Pouvez</b>-vous …?"}],"build":[{"en":"She has just arrived.","tiles":["Elle","vient d'","arriver."],"trap":"arrivée","why":"The verb stays as it is.","hint":"vient d'<b>arriver</b>."},{"en":"He is busy cooking.","tiles":["Il","est","en train de","cuisiner."],"trap":"cuisine","why":"The verb stays as it is.","hint":"en train de <b>cuisiner</b>."},{"en":"We have just finished.","tiles":["Nous","venons de","finir."],"trap":"fini","why":"The verb stays as it is.","hint":"venons de <b>finir</b>."},{"en":"They are busy working.","tiles":["Ils","sont","en train de","travailler."],"trap":"ont","why":"être en train de…","hint":"ils <b>sont</b> en train de …"},{"en":"I want to leave.","tiles":["Je","veux","partir."],"trap":"pars","why":"The verb stays as it is.","hint":"veux <b>partir</b>."}],"spot":[{"words":["Elle","vient de","arrivée."],"bad":2,"fix":"arriver.","hint":"The verb stays as it is: <b>arriver</b>.","look":"Look at the second verb.","say":"Elle vient d'arriver."},{"words":["Il","a","en train de","manger."],"bad":1,"fix":"est","hint":"<b>être</b> en train de.","look":"Which verb goes with en train de?"},{"words":["Nous","venons","manger."],"bad":1,"fix":"venons de","hint":"<b>venir de</b> = has just.","look":"Something is missing after venons.","say":"Nous venons de manger."},{"words":["Ils","venent de","partir."],"bad":1,"fix":"viennent de","hint":"venir with ils: <b>viennent</b>.","look":"Look at venir with ils."},{"words":["Je","suis en train","lire."],"bad":1,"fix":"suis en train de","hint":"en train <b>de</b>.","look":"Something is missing after en train."}]},"drill":[["I want to leave","Je veux partir.","The second verb stays as it is: veux <b>partir</b>."],["Can you help me? (vous)","Pouvez-vous m'aider ?","Verb first: <b>Pouvez-vous</b> …?"],["She has just arrived","Elle vient d'arriver.","has just = <b>venir de</b>: elle vient d'arriver."],["He is busy cooking","Il est en train de cuisiner. / Il est en train de faire la cuisine.","busy doing = <b>être en train de</b>."],["We have just eaten.","Nous venons de manger.","nous <b>venons de</b> + manger."],["They are busy working.","Ils sont en train de travailler.","ils <b>sont en train de</b> + travailler."]]},"21":{"line":"Compare with <b>plus</b> (more), <b>moins</b> (less) or <b>aussi</b> (as) + the adjective + <b>que</b>: Paul est plus grand que Marie. The most: <b>le / la / les plus</b>: la plus grande ville. Special: bon → <b>meilleur</b> (better, an adjective), bien → <b>mieux</b> (better, an adverb).","words":"Opposites to compare with: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:16\">Vocab 16 · High-Frequency Opposites</a>.","steps":[{"tool":"swap","title":"Compare","sub":"Pick a sentence and tap « Compare ».","button":["Compare","Back"],"legend":[["x","plus / moins / aussi … que"],["p","the most"]],"items":[{"label":"Paul est grand.","en":["Paul is tall.","Paul is taller than Marie."],"a":[["s","Paul est",""],["a","grand.",""]],"b":[["s","Paul est",""],["p","plus","x"],["a","grand",""],["q","que","x"],["o","Marie.",""]]},{"label":"Ce film est intéressant.","en":["This film is interesting.","This film is less interesting than the book."],"a":[["s","Ce film est",""],["a","intéressant.",""]],"b":[["s","Ce film est",""],["p","moins","x"],["a","intéressant",""],["q","que","x"],["o","le livre.",""]]},{"label":"Elle est sympa.","en":["She is nice.","She is as nice as her sister."],"a":[["s","Elle est",""],["a","sympa.",""]],"b":[["s","Elle est",""],["p","aussi","x"],["a","sympa",""],["q","que","x"],["o","sa sœur.",""]]},{"label":"C'est une grande ville.","en":["It's a big city.","It's the biggest city in France."],"a":[["s","C'est une",""],["a","grande",""],["o","ville.",""]],"b":[["s","C'est",""],["l","la plus","p"],["a","grande",""],["o","ville",""],["d","de France.","p"]],"note":"The most: <b>la plus</b> grande ville <b>de</b> France (in = de)."},{"label":"Il court vite.","en":["He runs fast.","He runs faster than me."],"a":[["s","Il court",""],["a","vite.",""]],"b":[["s","Il court",""],["p","plus","x"],["a","vite",""],["q","que","x"],["o","moi.",""]],"note":"After que: <b>moi</b>, toi, lui (stressed pronouns)."}]},{"tool":"sort","title":"meilleur or mieux?","sub":"better + a noun or after être: meilleur. better + a verb: mieux. Tap the box.","boxes":[{"k":"m","label":"meilleur(e)(s)","sub":"an adjective: with a noun"},{"k":"x","label":"mieux","sub":"an adverb: with a verb"}],"cards":[{"t":"Ce gâteau est … que l'autre.","box":"m","why":"About the cake (a noun): <b>meilleur</b>.","say":"Ce gâteau est meilleur que l'autre."},{"t":"Elle chante … que moi.","box":"x","why":"About how she sings (a verb): <b>mieux</b>.","say":"Elle chante mieux que moi."},{"t":"C'est la … pizza de Rome.","box":"m","why":"With pizza: <b>meilleure</b>.","say":"C'est la meilleure pizza de Rome."},{"t":"Tu parles … français maintenant.","box":"x","why":"How you speak: <b>mieux</b>.","say":"Tu parles mieux français maintenant."},{"t":"Ses notes sont …","box":"m","why":"About the marks (a noun): <b>meilleures</b>.","say":"Ses notes sont meilleures."},{"t":"Je dors … ici.","box":"x","why":"How I sleep: <b>mieux</b>.","say":"Je dors mieux ici."}]},{"tool":"flip","title":"The special ones","sub":"Tap a card.","cards":[{"a":"plus bon","b":"meilleur","tag":"bon → meilleur"},{"a":"plus bien","b":"mieux","tag":"bien → mieux"},{"a":"le plus bon","b":"le meilleur","tag":"the best (adjective)"},{"a":"le plus bien","b":"le mieux","tag":"the best (adverb)"}]}],"practice":{"choose":[{"q":"Paul est ___ grand que Marie.","en":"Paul is taller than Marie.","opts":["plus","plus de","le plus","très"],"a":"plus","why":"more + an adjective…","hint":"<b>plus</b> grand <b>que</b>."},{"q":"Elle est aussi sympa ___ sa sœur.","en":"She is as nice as her sister.","opts":["que","comme","de","than"],"a":"que","why":"The second part starts with…","hint":"aussi … <b>que</b>."},{"q":"C'est la ville la plus belle ___ France.","en":"It's the most beautiful city in France.","opts":["de","en","dans","à"],"a":"de","why":"the most … in a place…","hint":"la plus belle <b>de</b> France."},{"q":"Ce vin est ___ que l'autre.","en":"This wine is better than the other.","opts":["meilleur","mieux","plus bon","bien"],"a":"meilleur","why":"About the wine (a noun).","hint":"<b>meilleur</b>."},{"q":"Elle chante ___ que moi.","en":"She sings better than me.","opts":["mieux","meilleur","plus bien","meilleure"],"a":"mieux","why":"About how she sings (a verb).","hint":"<b>mieux</b>."},{"q":"Il est plus grand que ___.","en":"He is taller than me.","opts":["moi","je","me","mon"],"a":"moi","why":"After que…","hint":"que <b>moi</b>."}],"build":[{"en":"Paul is taller than Marie.","tiles":["Paul","est","plus","grand","que","Marie."],"trap":"de","why":"than = que.","hint":"plus grand <b>que</b> Marie."},{"en":"She sings better than me.","tiles":["Elle","chante","mieux","que","moi."],"trap":"meilleur","why":"How she sings: an adverb.","hint":"chante <b>mieux</b>."},{"en":"the biggest city in France","tiles":["la","plus","grande","ville","de","France"],"trap":"en","why":"in = de after a superlative.","hint":"… <b>de</b> France."},{"en":"This film is less interesting.","tiles":["Ce","film","est","moins","intéressant."],"trap":"plus","why":"less = moins.","hint":"<b>moins</b> intéressant."},{"en":"It's the best cake.","tiles":["C'est","le","meilleur","gâteau."],"trap":"mieux","why":"With a noun…","hint":"le <b>meilleur</b> gâteau."}],"spot":[{"words":["Ce gâteau","est","plus bon."],"bad":2,"fix":"meilleur.","hint":"bon → <b>meilleur</b>.","look":"Look at plus bon."},{"words":["Elle chante","meilleur","que moi."],"bad":1,"fix":"mieux","hint":"How she sings: <b>mieux</b>.","look":"Is it about a noun or a verb?"},{"words":["Paul est","plus grand","de Marie."],"bad":2,"fix":"que Marie.","hint":"than = <b>que</b>.","look":"Look at « than »."},{"words":["C'est","la plus belle ville","en France."],"bad":2,"fix":"de France.","hint":"After a superlative: <b>de</b> France.","look":"How do you say « in » after the most?"},{"words":["Il est","plus grand que","je."],"bad":2,"fix":"moi.","hint":"After que: <b>moi</b>.","look":"Look at the last word."}]},"drill":[["Paul is taller than Marie","Paul est plus grand que Marie.","<b>plus</b> + adjective + <b>que</b>."],["This is better","C'est meilleur. / C'est mieux.","bon → <b>meilleur</b>, bien → <b>mieux</b>."],["She sings better than me","Elle chante mieux que moi.","How she sings: <b>mieux</b>; after que: moi."],["the biggest city in France","la plus grande ville de France","The most: <b>la plus</b> …, in = <b>de</b>."],["She is as nice as her sister.","Elle est aussi sympa que sa sœur.","as … as = <b>aussi … que</b>."],["It's the best cake.","C'est le meilleur gâteau.","the best + a noun: <b>le meilleur</b>."]]},"19":{"line":"A pronoun replaces a noun so you don't repeat it, and it goes <b>before the verb</b>. The thing or person itself (who? what?): <b>le, la, l', les</b>: je vois Paul → je <b>le</b> vois. After <b>à</b> + a person (to whom?): <b>lui, leur</b>: je parle à Marie → je <b>lui</b> parle. me, te, nous, vous work for both.","words":"","steps":[{"tool":"swap","title":"Replace the noun","sub":"Pick a sentence and tap « Use a pronoun »: the noun goes, the pronoun jumps before the verb.","button":["Use a pronoun","Back to the noun"],"legend":[["p","the pronoun"],["v","the verb"],["n","ne … pas"]],"items":[{"label":"Je vois Paul.","en":["I see Paul.","I see him."],"a":[["s","Je",""],["v","vois","v"],["o","Paul.","x"]],"b":[["s","Je",""],["p","le","p"],["v","vois.","v"]],"note":"Paul (who?) → <b>le</b>, before the verb."},{"label":"Je regarde les photos.","en":["I look at the photos.","I look at them."],"a":[["s","Je",""],["v","regarde","v"],["o","les photos.","x"]],"b":[["s","Je",""],["p","les","p"],["v","regarde.","v"]]},{"label":"Je parle à Marie.","en":["I speak to Marie.","I speak to her."],"a":[["s","Je",""],["v","parle","v"],["o","à Marie.","x"]],"b":[["s","Je",""],["p","lui","p"],["v","parle.","v"]],"note":"à + a person → <b>lui</b> (him or her)."},{"label":"Il téléphone à ses parents.","en":["He phones his parents.","He phones them."],"a":[["s","Il",""],["v","téléphone","v"],["o","à ses parents.","x"]],"b":[["s","Il",""],["p","leur","p"],["v","téléphone.","v"]],"note":"à + people → <b>leur</b>."},{"label":"Je ne connais pas Paul.","en":["I don't know Paul.","I don't know him."],"a":[["s","Je",""],["ne","ne","n"],["v","connais","v"],["pas","pas","n"],["o","Paul.","x"]],"b":[["s","Je",""],["ne","ne","n"],["p","le","p"],["v","connais","v"],["pas","pas.","n"]],"note":"ne goes before the pronoun: je <b>ne le</b> connais pas."},{"label":"Je veux voir le film.","en":["I want to see the film.","I want to see it."],"a":[["s","Je",""],["m","veux",""],["v","voir","v"],["o","le film.","x"]],"b":[["s","Je",""],["m","veux",""],["p","le","p"],["v","voir.","v"]],"note":"Two verbs: the pronoun goes before the one it belongs to: veux <b>le voir</b>."}]},{"tool":"sort","title":"le / la / les or lui / leur?","sub":"Is there an à before the person? Tap the box.","boxes":[{"k":"d","label":"le / la / les","sub":"who? what? (no à)"},{"k":"i","label":"lui / leur","sub":"à + a person"}],"cards":[{"t":"Je vois Marie.","box":"d","why":"voir quelqu'un (no à): je <b>la</b> vois."},{"t":"Je parle à Marie.","box":"i","why":"parler à: je <b>lui</b> parle."},{"t":"J'aide mes amis.","box":"d","why":"aider quelqu'un (no à): je <b>les</b> aide."},{"t":"J'écris à mes amis.","box":"i","why":"écrire à: je <b>leur</b> écris."},{"t":"J'écoute le professeur.","box":"d","why":"écouter quelqu'un (no à): je <b>l'</b>écoute."},{"t":"Je téléphone à Paul.","box":"i","why":"téléphoner à: je <b>lui</b> téléphone."},{"t":"Je donne le livre (à Paul).","box":"d","why":"the book: je <b>le</b> donne."},{"t":"Je donne un livre à Paul.","box":"i","why":"to Paul: je <b>lui</b> donne un livre."}]}],"practice":{"choose":[{"q":"Paul ? Je ___ vois demain.","en":"Paul? I see him tomorrow.","opts":["le","lui","la","les"],"a":"le","why":"voir quelqu'un: no à.","hint":"Paul → <b>le</b>."},{"q":"Marie ? Je ___ parle souvent.","en":"Marie? I often speak to her.","opts":["lui","la","le","leur"],"a":"lui","why":"parler à quelqu'un.","hint":"à Marie → <b>lui</b>."},{"q":"Mes parents ? Je ___ téléphone le dimanche.","en":"My parents? I phone them on Sundays.","opts":["leur","les","lui","leurs"],"a":"leur","why":"téléphoner à + several people.","hint":"à mes parents → <b>leur</b>."},{"q":"Les clés ? Je ne ___ trouve pas.","en":"The keys? I can't find them.","opts":["les","leur","la","le"],"a":"les","why":"trouver quelque chose: no à.","hint":"les clés → <b>les</b>."},{"q":"Le film ? Je veux ___ voir.","en":"The film? I want to see it.","opts":["le","lui","la","les"],"a":"le","why":"Two verbs: before which one?","hint":"veux <b>le</b> voir."},{"q":"L'histoire ? Je ___ aime.","en":"The story? I like it.","opts":["l'","la","le","lui"],"a":"l'","why":"aime starts with a vowel.","hint":"Before a vowel, le / la → <b>l'</b>: je l'aime."}],"build":[{"en":"I see him.","tiles":["Je","le","vois."],"trap":"lui","why":"voir quelqu'un: no à.","hint":"je <b>le</b> vois."},{"en":"I speak to her.","tiles":["Je","lui","parle."],"trap":"la","why":"parler à…","hint":"je <b>lui</b> parle."},{"en":"I don't know them.","tiles":["Je","ne","les","connais","pas."],"trap":"leur","why":"connaître quelqu'un: no à.","hint":"je ne <b>les</b> connais pas."},{"en":"I want to see it.","tiles":["Je","veux","le","voir."],"trap":"lui","why":"Before the verb it belongs to.","hint":"veux <b>le voir</b>."},{"en":"He phones them.","tiles":["Il","leur","téléphone."],"trap":"les","why":"téléphoner à…","hint":"il <b>leur</b> téléphone."}],"spot":[{"words":["Je","vois","le."],"bad":1,"fix":"le vois.","hint":"The pronoun goes before the verb: je <b>le vois</b>.","look":"Where does the pronoun go?","say":"Je le vois."},{"words":["Marie ?","Je","la","parle."],"bad":2,"fix":"lui","hint":"parler à: <b>lui</b>.","look":"Is there an à after parler?"},{"words":["Mes amis ?","Je","leur","aide."],"bad":2,"fix":"les","hint":"aider quelqu'un (no à): <b>les</b>.","look":"Is there an à after aider?"},{"words":["Je","ne","connais le","pas."],"bad":2,"fix":"le connais","hint":"ne + pronoun + verb + pas: je ne <b>le connais</b> pas.","look":"Where does the pronoun go in a no?","say":"Je ne le connais pas."},{"words":["Je","le veux","voir."],"bad":1,"fix":"veux le","hint":"Before the verb it belongs to: veux <b>le voir</b>.","look":"Which verb does the pronoun belong to?","say":"Je veux le voir."}]},"drill":[["I see him","Je le vois.","Who? <b>le</b>, before the verb."],["I speak to her","Je lui parle.","à + a person: <b>lui</b>."],["I don't know them","Je ne les connais pas.","ne goes before the pronoun: je <b>ne les</b> connais pas."],["Look at me! (tu)","Regarde-moi !","In an order, the pronoun goes after: <b>Regarde-moi !</b>"],["I want to see it. (le film)","Je veux le voir.","Before the verb it belongs to: veux <b>le voir</b>."],["He phones them. (his parents)","Il leur téléphone.","à + people: <b>leur</b>."]]},"20":{"line":"<b>y</b> replaces a place (à Paris, dans la cuisine, chez moi) or à + a thing: je vais à Paris → j'<b>y</b> vais. <b>en</b> replaces de + a thing, and « some » or an amount: je veux du café → j'<b>en</b> veux; j'ai deux sœurs → j'<b>en</b> ai deux. Both go before the verb.","words":"","steps":[{"tool":"swap","title":"Replace it with y or en","sub":"Pick a sentence and tap « Use y / en ».","button":["Use y / en","Back"],"legend":[["p","y / en"],["x","what it replaces"]],"items":[{"label":"Je vais à Paris.","en":["I'm going to Paris.","I'm going there."],"a":[["s","Je",""],["v","vais",""],["o","à Paris.","x"]],"b":[["s","J'",""],["p","y","p"],["v","vais.",""]],"note":"A place → <b>y</b> (there)."},{"label":"Je pense à mon examen.","en":["I'm thinking about my exam.","I'm thinking about it."],"a":[["s","Je",""],["v","pense",""],["o","à mon examen.","x"]],"b":[["s","J'",""],["p","y","p"],["v","pense.",""]],"note":"à + a thing → <b>y</b>."},{"label":"Je veux du café.","en":["I want some coffee.","I want some."],"a":[["s","Je",""],["v","veux",""],["o","du café.","x"]],"b":[["s","J'",""],["p","en","p"],["v","veux.",""]],"note":"du / de la / des + a thing → <b>en</b> (some)."},{"label":"J'ai deux sœurs.","en":["I have two sisters.","I have two (of them)."],"a":[["s","J'",""],["v","ai",""],["n","deux",""],["o","sœurs.","x"]],"b":[["s","J'",""],["p","en","p"],["v","ai",""],["n","deux.",""]],"note":"An amount: <b>en</b>, and the number stays at the end."},{"label":"Je ne bois pas de lait.","en":["I don't drink milk.","I don't drink any."],"a":[["s","Je",""],["ne","ne",""],["v","bois",""],["pas","pas",""],["o","de lait.","x"]],"b":[["s","Je",""],["ne","n'",""],["p","en","p"],["v","bois",""],["pas","pas.",""]],"note":"ne becomes n' before en: je <b>n'en</b> bois pas."}]},{"tool":"sort","title":"y or en?","sub":"Tap the box for what each one replaces.","boxes":[{"k":"y","label":"y","sub":"a place, or à + a thing"},{"k":"en","label":"en","sub":"de + a thing, some, an amount"}],"cards":[{"t":"à la plage","box":"y","why":"A place: <b>y</b>."},{"t":"du pain","box":"en","why":"Some: <b>en</b>."},{"t":"chez Paul","box":"y","why":"A place: <b>y</b>."},{"t":"trois enfants","box":"en","why":"An amount: <b>en</b> … trois."},{"t":"à ton problème (penser à)","box":"y","why":"à + a thing: <b>y</b>."},{"t":"de la musique (parler de)","box":"en","why":"de + a thing: <b>en</b>."},{"t":"dans la cuisine","box":"y","why":"A place: <b>y</b>."},{"t":"beaucoup d'amis","box":"en","why":"An amount: <b>en</b> … beaucoup."}]}],"practice":{"choose":[{"q":"Tu vas à Paris ? Oui, j'___ vais.","en":"Are you going to Paris? Yes, I'm going there.","opts":["y","en","le","la"],"a":"y","why":"A place…","hint":"<b>y</b> = there."},{"q":"Tu veux de l'eau ? Oui, j'___ veux.","en":"Do you want some water? Yes, I want some.","opts":["en","y","la","l'"],"a":"en","why":"some…","hint":"<b>en</b> = some."},{"q":"Tu as des frères ? J'___ ai deux.","en":"Do you have brothers? I have two.","opts":["en","y","les","leur"],"a":"en","why":"An amount…","hint":"<b>en</b> … deux."},{"q":"Tu penses à tes vacances ? Oui, j'___ pense.","en":"Are you thinking about your holidays? Yes.","opts":["y","en","les","lui"],"a":"y","why":"penser à + a thing.","hint":"à + a thing: <b>y</b>."},{"q":"Il ne ___ boit pas.","en":"He doesn't drink any.","opts":["n'en","ne en","n'y","en"],"a":"n'en","why":"ne before a vowel…","hint":"<b>n'en</b>."},{"q":"On ___ va ! ","en":"Let's go! (there)","opts":["y","en","le","là"],"a":"y","why":"aller somewhere…","hint":"<b>On y va !</b>"}],"build":[{"en":"Yes, I'm going there.","tiles":["Oui,","j'","y","vais."],"trap":"en","why":"A place…","hint":"j'<b>y</b> vais."},{"en":"I want some.","tiles":["J'","en","veux."],"trap":"y","why":"some…","hint":"j'<b>en</b> veux."},{"en":"I have two (of them).","tiles":["J'","en","ai","deux."],"trap":"les","why":"An amount…","hint":"j'<b>en</b> ai deux."},{"en":"I don't have any.","tiles":["Je","n'","en","ai","pas."],"trap":"ne","why":"ne before a vowel.","hint":"je <b>n'en</b> ai pas."},{"en":"I'm thinking about it.","tiles":["J'","y","pense."],"trap":"en","why":"penser à…","hint":"j'<b>y</b> pense."}],"spot":[{"words":["Paris ?","J'en","vais demain."],"bad":1,"fix":"J'y","hint":"A place: <b>y</b>.","look":"Is it a place or an amount?"},{"words":["Du café ?","J'y","veux bien."],"bad":1,"fix":"J'en","hint":"Some: <b>en</b>.","look":"Is it a place or « some »?"},{"words":["Des sœurs ?","J'ai","deux."],"bad":1,"fix":"J'en ai","hint":"Keep the amount with <b>en</b>: j'en ai deux.","look":"Something is missing before ai.","say":"J'en ai deux."},{"words":["Je","ne en","bois pas."],"bad":1,"fix":"n'en","hint":"<b>n'en</b>.","look":"ne before a vowel…","say":"Je n'en bois pas."},{"words":["Je","vais y."],"bad":1,"fix":"y vais.","hint":"y goes before the verb: <b>j'y vais</b>.","look":"Where does y go?","say":"J'y vais."}]},"drill":[["Are you going to Paris? Yes, I'm going there.","Oui, j'y vais. / J'y vais.","A place: <b>y</b>."],["Do you want some water? Yes, I want some.","Oui, j'en veux. / J'en veux.","some: <b>en</b>."],["I have two sisters (use en)","J'en ai deux.","An amount: <b>en</b> … deux."],["I don't have any","Je n'en ai pas.","ne before a vowel: <b>n'en</b>."],["I'm thinking about it. (penser à)","J'y pense.","à + a thing: <b>y</b>."],["Let's go! (there)","On y va ! / Allons-y !","<b>y</b> = there."]]},"30":{"line":"After a word of quantity, just <b>de</b> (d' before a vowel) + the noun, with no article: <b>beaucoup de</b> pain, <b>un peu d'</b>eau, <b>trop de</b> sucre, <b>assez de</b> temps, <b>combien de</b> frères ?, un kilo <b>de</b> tomates. It is the same de as after a no. With en: j'<b>en</b> ai beaucoup.","words":"Food and amounts: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:18\">Vocab 18 · Café, Food & Ordering</a> · <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:4\">Vocab 4 · Numbers & Scale Units</a>.","steps":[{"tool":"flip","title":"Add a quantity","sub":"Tap a card: du, de la, des become de after the quantity.","cards":[{"a":"des pommes","b":"beaucoup de pommes","tag":"des → beaucoup de"},{"a":"de l'eau","b":"un peu d'eau","tag":"de l' → un peu d'"},{"a":"du sucre","b":"trop de sucre","tag":"du → trop de"},{"a":"du temps","b":"assez de temps","tag":"du → assez de"},{"a":"des tomates","b":"un kilo de tomates","tag":"des → un kilo de"},{"a":"du lait","b":"une bouteille de lait","tag":"du → une bouteille de"},{"a":"des frères ?","b":"Combien de frères ?","tag":"des → combien de"}]},{"tool":"swap","title":"Replace it with en","sub":"Pick a sentence and tap « Use en »: the quantity stays at the end.","button":["Use en","Back"],"legend":[["p","en"],["x","what it replaces"]],"items":[{"label":"J'ai beaucoup de livres.","en":["I have a lot of books.","I have a lot (of them)."],"a":[["s","J'",""],["v","ai",""],["q","beaucoup",""],["o","de livres.","x"]],"b":[["s","J'",""],["p","en","p"],["v","ai",""],["q","beaucoup.",""]]},{"label":"Il boit un peu de lait.","en":["He drinks a little milk.","He drinks a little (of it)."],"a":[["s","Il",""],["v","boit",""],["q","un peu",""],["o","de lait.","x"]],"b":[["s","Il",""],["p","en","p"],["v","boit",""],["q","un peu.",""]]},{"label":"Tu as assez d'argent ?","en":["Do you have enough money?","Do you have enough (of it)?"],"a":[["s","Tu",""],["v","as",""],["q","assez",""],["o","d'argent ?","x"]],"b":[["s","Tu",""],["p","en","p"],["v","as",""],["q","assez ?",""]]}]}],"practice":{"choose":[{"q":"beaucoup ___ pain","en":"a lot of bread","opts":["de","du","des","le"],"a":"de","why":"After a quantity…","hint":"<b>beaucoup de</b>."},{"q":"un peu ___ eau","en":"a little water","opts":["d'","de","de l'","du"],"a":"d'","why":"eau starts with a vowel.","hint":"un peu <b>d'</b>eau."},{"q":"___ de frères as-tu ?","en":"How many brothers do you have?","opts":["Combien","Comment","Quel","Beaucoup"],"a":"Combien","why":"How many…","hint":"<b>Combien de</b>."},{"q":"Il y a trop ___ monde.","en":"There are too many people.","opts":["de","du","des","les"],"a":"de","why":"After trop…","hint":"<b>trop de</b>."},{"q":"un kilo ___ tomates","en":"a kilo of tomatoes","opts":["de","des","du","les"],"a":"de","why":"After un kilo…","hint":"un kilo <b>de</b>."},{"q":"Des livres ? J'___ ai beaucoup.","en":"Books? I have a lot.","opts":["en","y","les","leur"],"a":"en","why":"Replace « de livres ».","hint":"<b>en</b> … beaucoup."}],"build":[{"en":"a lot of bread","tiles":["beaucoup","de","pain"],"trap":"du","why":"After a quantity: just de.","hint":"beaucoup <b>de</b> pain."},{"en":"a little water","tiles":["un peu","d'","eau"],"trap":"de l'","why":"After a quantity: just de.","hint":"un peu <b>d'</b>eau."},{"en":"How many brothers do you have?","tiles":["Combien","de","frères","as-tu ?"],"trap":"des","why":"After combien: just de.","hint":"combien <b>de</b> frères."},{"en":"I have a lot (of them).","tiles":["J'","en","ai","beaucoup."],"trap":"les","why":"Replace « de livres » with en.","hint":"j'<b>en</b> ai beaucoup."},{"en":"We have enough time.","tiles":["Nous","avons","assez","de","temps."],"trap":"du","why":"After assez: just de.","hint":"assez <b>de</b> temps."}],"spot":[{"words":["beaucoup","des","amis"],"bad":1,"fix":"d'","hint":"After a quantity: <b>d'</b>amis.","look":"Look after beaucoup.","say":"beaucoup d'amis"},{"words":["un peu","du","sucre"],"bad":1,"fix":"de","hint":"After a quantity: <b>de</b>.","look":"Look after un peu."},{"words":["Combien","des","enfants ?"],"bad":1,"fix":"d'","hint":"After combien: <b>d'</b>enfants.","look":"Look after combien.","say":"Combien d'enfants ?"},{"words":["un litre","de le","lait"],"bad":1,"fix":"de","hint":"After a quantity: just <b>de</b>.","look":"Look after un litre."},{"words":["Des livres ?","J'ai","beaucoup."],"bad":1,"fix":"J'en ai","hint":"Keep the amount with <b>en</b>.","look":"Something is missing before ai.","say":"J'en ai beaucoup."}]},"drill":[["a lot of bread","beaucoup de pain","After a quantity: <b>de</b>, no article."],["a little water","un peu d'eau","Before a vowel: <b>d'</b>eau."],["How many brothers do you have?","Combien de frères as-tu ? / Tu as combien de frères ? / Combien de frères est-ce que tu as ? / Combien de frères avez-vous ?","<b>combien de</b> + the noun."],["I have a lot of books (use en)","J'en ai beaucoup.","<b>en</b> replaces « de livres »; beaucoup stays at the end."],["too much sugar","trop de sucre","<b>trop de</b>."],["a kilo of tomatoes","un kilo de tomates","un kilo <b>de</b>."]]},"31":{"line":"In an order, the pronoun goes <b>after</b> the verb with a hyphen: Regarde-<b>le</b> ! Donne-<b>moi</b> ça ! (me → <b>moi</b>, te → <b>toi</b>: Dépêche-toi !). In a no, it goes back <b>before</b> the verb: <b>Ne le</b> regarde <b>pas</b> !","words":"","steps":[{"tool":"swap","title":"Make it an order","sub":"Pick a sentence and tap « Make it an order »: the pronoun jumps after the verb.","button":["Make it an order","Back"],"legend":[["p","the pronoun"],["v","the verb"],["n","ne … pas"]],"items":[{"label":"Tu le regardes.","en":["You look at it.","Look at it!"],"a":[["s","Tu",""],["p","le","p"],["v","regardes.","v"]],"b":[["v","Regarde-","v"],["p","le !","p"]],"note":"After the verb, with a hyphen: <b>Regarde-le !</b>"},{"label":"Tu me donnes ça.","en":["You give me that.","Give me that!"],"a":[["s","Tu",""],["p","me","p"],["v","donnes","v"],["o","ça.",""]],"b":[["v","Donne-","v"],["p","moi","p"],["o","ça !",""]],"note":"me becomes <b>moi</b> after the verb."},{"label":"Tu te dépêches.","en":["You hurry up.","Hurry up!"],"a":[["s","Tu",""],["p","te","p"],["v","dépêches.","v"]],"b":[["v","Dépêche-","v"],["p","toi !","p"]],"note":"te becomes <b>toi</b>: Dépêche-toi !"},{"label":"Vous vous asseyez.","en":["You sit down.","Sit down!"],"a":[["s","Vous",""],["p","vous","p"],["v","asseyez.","v"]],"b":[["v","Asseyez-","v"],["p","vous !","p"]]},{"label":"Tu ne le regardes pas.","en":["You don't look at it.","Don't look at it!"],"a":[["s","Tu",""],["ne","ne","n"],["p","le","p"],["v","regardes","v"],["pas","pas.","n"]],"b":[["ne","Ne","n"],["p","le","p"],["v","regarde","v"],["pas","pas !","n"]],"note":"In a no, the pronoun stays <b>before</b> the verb."},{"label":"Tu lui parles.","en":["You speak to him.","Speak to him!"],"a":[["s","Tu",""],["p","lui","p"],["v","parles.","v"]],"b":[["v","Parle-","v"],["p","lui !","p"]]}]},{"tool":"flip","title":"me → moi, te → toi","sub":"Tap a card: after the verb, me and te change.","cards":[{"a":"Tu me regardes.","b":"Regarde-moi !","tag":"me → moi"},{"a":"Tu me le donnes.","b":"Donne-le-moi !","tag":"le before moi"},{"a":"Tu te lèves.","b":"Lève-toi !","tag":"te → toi"},{"a":"Tu ne te lèves pas.","b":"Ne te lève pas !","tag":"a no: te stays before"},{"a":"Tu y vas.","b":"Vas-y !","tag":"vas + y: the -s comes back"}]}],"practice":{"choose":[{"q":"Regarde-___ ! (it)","en":"Look at it!","opts":["le","lui","la","moi"],"a":"le","why":"it, after the verb…","hint":"Regarde-<b>le</b> !"},{"q":"Donne-___ ça ! (me)","en":"Give me that!","opts":["moi","me","je","toi"],"a":"moi","why":"me after the verb…","hint":"Donne-<b>moi</b> ça !"},{"q":"Dépêche-___ !","en":"Hurry up!","opts":["toi","te","tu","vous"],"a":"toi","why":"te after the verb…","hint":"Dépêche-<b>toi</b> !"},{"q":"Ne ___ regarde pas !","en":"Don't look at it!","opts":["le","moi","lui","toi"],"a":"le","why":"In a no, the pronoun goes…","hint":"<b>Ne le</b> regarde pas !"},{"q":"Asseyez-___ !","en":"Sit down! (vous)","opts":["vous","toi","nous","se"],"a":"vous","why":"vous after the verb…","hint":"Asseyez-<b>vous</b> !"},{"q":"Ne te ___ pas !","en":"Don't get up!","opts":["lève","lèves","lever","levez"],"a":"lève","why":"tu form of an -er verb in an order.","hint":"Ne te <b>lève</b> pas !"}],"build":[{"en":"Look at it! (tu)","tiles":["Regarde-le","!"],"trap":"Le regarde","why":"In an order, the pronoun goes after.","hint":"<b>Regarde-le !</b>"},{"en":"Don't look at it!","tiles":["Ne","le","regarde","pas !"],"trap":"Regarde-le","why":"In a no, the pronoun goes before.","hint":"<b>Ne le regarde pas !</b>"},{"en":"Hurry up! (vous)","tiles":["Dépêchez-vous","!"],"trap":"Vous dépêchez","why":"In an order, the pronoun goes after.","hint":"<b>Dépêchez-vous !</b>"},{"en":"Give it to me!","tiles":["Donne-le-moi","!"],"trap":"Donne-moi-le","why":"le before moi.","hint":"<b>Donne-le-moi !</b>"},{"en":"Get up! (tu)","tiles":["Lève-toi","!"],"trap":"Lève-te","why":"te after the verb…","hint":"<b>Lève-toi !</b>"}],"spot":[{"words":["Regarde-","me !"],"bad":1,"fix":"moi !","hint":"After the verb: <b>moi</b>.","look":"What does me become after the verb?","say":"Regarde-moi !"},{"words":["Ne","regarde-le","pas !"],"bad":1,"fix":"le regarde","hint":"In a no, before: <b>Ne le regarde pas !</b>","look":"Where does le go in a no?"},{"words":["Dépêche-","te !"],"bad":1,"fix":"toi !","hint":"After the verb: <b>toi</b>.","look":"What does te become after the verb?","say":"Dépêche-toi !"},{"words":["Le","regarde !"],"bad":0,"fix":"Regarde-le !","hint":"In an order, after the verb: <b>Regarde-le !</b>","look":"Where does le go in an order?","say":"Regarde-le !"},{"words":["Donne-moi-le !"],"bad":0,"fix":"Donne-le-moi !","hint":"le goes before moi: <b>Donne-le-moi !</b>","look":"Which pronoun comes first?"}]},"drill":[["Look at it! (tu)","Regarde-le !","After the verb, with a hyphen: <b>Regarde-le !</b>"],["Don't look at it!","Ne le regarde pas !","In a no, before the verb: <b>Ne le</b> regarde pas."],["Hurry up! (vous)","Dépêchez-vous !","<b>Dépêchez-vous !</b>"],["Give it to me!","Donne-le-moi !","le before moi: <b>Donne-le-moi !</b>"],["Look at me! (tu)","Regarde-moi !","me → <b>moi</b> after the verb."],["Get up! (tu)","Lève-toi !","te → <b>toi</b>: Lève-toi !"]]},"v10":{"line":"Every compound tense is a helper verb + the <b>past participle</b>, so learn the participle first. <b>-er → -é</b> (parler → parlé), <b>-ir → -i</b> (finir → fini), <b>-re → -u</b> (vendre → vendu). Many common verbs are irregular: pris, mis, fait, dit, écrit, ouvert, été, eu, vu, bu, pu, dû, su, venu, né, mort.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"sort","title":"How does it end?","sub":"Tap the ending of each past participle.","boxes":[{"k":"e","label":"-é","sub":"-er verbs"},{"k":"i","label":"-i / -is / -it","sub":"finir, prendre, dire…"},{"k":"u","label":"-u","sub":"-re and many others"},{"k":"x","label":"other","sub":"learn them"}],"cards":[{"t":"parler","box":"e","why":"<b>parlé</b>"},{"t":"finir","box":"i","why":"<b>fini</b>"},{"t":"vendre","box":"u","why":"<b>vendu</b>"},{"t":"prendre","box":"i","why":"<b>pris</b>"},{"t":"voir","box":"u","why":"<b>vu</b>"},{"t":"faire","box":"x","why":"<b>fait</b>"},{"t":"dire","box":"i","why":"<b>dit</b>"},{"t":"ouvrir","box":"x","why":"<b>ouvert</b>"},{"t":"avoir","box":"u","why":"<b>eu</b>"},{"t":"être","box":"x","why":"<b>été</b>"},{"t":"aller","box":"e","why":"<b>allé</b>"},{"t":"mettre","box":"i","why":"<b>mis</b>"}]},{"tool":"flip","title":"The irregular ones to know","sub":"Tap a card: the infinitive turns into its past participle.","cards":[{"a":"prendre","b":"pris","tag":"comprendre → compris"},{"a":"mettre","b":"mis","tag":"promettre → promis"},{"a":"écrire","b":"écrit","tag":"décrire → décrit"},{"a":"ouvrir","b":"ouvert","tag":"offrir → offert"},{"a":"devoir","b":"dû","tag":"with an accent"},{"a":"pouvoir","b":"pu"},{"a":"savoir","b":"su"},{"a":"vouloir","b":"voulu"},{"a":"boire","b":"bu"},{"a":"connaître","b":"connu"},{"a":"naître","b":"né"},{"a":"mourir","b":"mort"}]}],"practice":{"choose":[{"q":"prendre → ___","en":"taken","opts":["pris","prendu","prit","prené"],"a":"pris","why":"An irregular one.","hint":"<b>pris</b>."},{"q":"ouvrir → ___","en":"opened","opts":["ouvert","ouvri","ouvru","ouvré"],"a":"ouvert","why":"An irregular one.","hint":"<b>ouvert</b>."},{"q":"devoir → ___","en":"had to","opts":["dû","du","devu","doit"],"a":"dû","why":"With an accent.","hint":"<b>dû</b>."},{"q":"finir → ___","en":"finished","opts":["fini","finé","finu","finis"],"a":"fini","why":"Regular -ir.","hint":"<b>fini</b>."},{"q":"vendre → ___","en":"sold","opts":["vendu","vendi","vendé","vendit"],"a":"vendu","why":"Regular -re.","hint":"<b>vendu</b>."},{"q":"faire → ___","en":"done","opts":["fait","faisé","fairu","fai"],"a":"fait","why":"An irregular one.","hint":"<b>fait</b>."}],"build":[{"en":"I have taken the bus.","tiles":["J'ai","pris","le","bus."],"trap":"prendu","why":"prendre → ?","hint":"j'ai <b>pris</b>."},{"en":"She has opened the window.","tiles":["Elle","a","ouvert","la","fenêtre."],"trap":"ouvri","why":"ouvrir → ?","hint":"elle a <b>ouvert</b>."},{"en":"We have seen the film.","tiles":["Nous","avons","vu","le","film."],"trap":"voiré","why":"voir → ?","hint":"nous avons <b>vu</b>."},{"en":"They have done their homework.","tiles":["Ils","ont","fait","leurs","devoirs."],"trap":"faisé","why":"faire → ?","hint":"ils ont <b>fait</b>."},{"en":"I had to leave.","tiles":["J'ai","dû","partir."],"trap":"devu","why":"devoir → ?","hint":"j'ai <b>dû</b> partir."}],"spot":[{"words":["J'ai","prendu","le train."],"bad":1,"fix":"pris","hint":"prendre → <b>pris</b>.","look":"Look at the participle."},{"words":["Elle a","ouvri","la porte."],"bad":1,"fix":"ouvert","hint":"ouvrir → <b>ouvert</b>.","look":"Look at the participle."},{"words":["Nous avons","mettu","la table."],"bad":1,"fix":"mis","hint":"mettre → <b>mis</b>.","look":"Look at the participle."},{"words":["Il a","écrivé","une lettre."],"bad":1,"fix":"écrit","hint":"écrire → <b>écrit</b>.","look":"Look at the participle."},{"words":["Tu as","buvé","du café ?"],"bad":1,"fix":"bu","hint":"boire → <b>bu</b>.","look":"Look at the participle."}]},"drill":[["past participle of prendre","pris","prendre → <b>pris</b> (comprendre → compris)."],["past participle of ouvrir","ouvert","ouvrir → <b>ouvert</b> (offrir → offert)."],["past participle of devoir","dû","devoir → <b>dû</b>, with an accent."],["past participle of connaître","connu","connaître → <b>connu</b>."],["past participle of faire","fait","faire → <b>fait</b>."],["past participle of mettre","mis","mettre → <b>mis</b>."]]},"15":{"line":"The <b>passé composé</b> tells what happened: <b>avoir</b> or <b>être</b> in the present + the past participle: j'<b>ai</b> mangé, elle <b>est</b> allée. Most verbs take avoir. About 16 verbs of movement or change (aller, venir, partir, arriver, naître, mourir, rester, tomber…) and all the « se » verbs take être, and then the participle agrees: elle est allé<b>e</b>, ils sont parti<b>s</b>.","words":"","steps":[{"tool":"conj","title":"avoir + participle, être + participle","sub":"Pick a verb, then tap a person. With être, the participle agrees.","neg":true,"verbs":[{"inf":"manger","en":"ate","pasAt":1,"forms":["ai mangé","as mangé","a mangé","avons mangé","avez mangé","ont mangé"],"tail":"une pizza"},{"inf":"finir","en":"finished","pasAt":1,"forms":["ai fini","as fini","a fini","avons fini","avez fini","ont fini"],"tail":"le travail"},{"inf":"aller","en":"went","pasAt":1,"forms":["suis allé(e)","es allé(e)","est allé(e)","sommes allé(e)s","êtes allé(e)(s)","sont allé(e)s"],"tail":"à Paris"}]},{"tool":"sort","title":"avoir or être?","sub":"Tap the helper each verb takes in the passé composé.","boxes":[{"k":"a","label":"avoir","sub":"most verbs"},{"k":"e","label":"être","sub":"movement, change, and « se » verbs"}],"cards":[{"t":"manger","box":"a","why":"j'<b>ai</b> mangé"},{"t":"aller","box":"e","why":"je <b>suis</b> allé(e)"},{"t":"partir","box":"e","why":"je <b>suis</b> parti(e)"},{"t":"faire","box":"a","why":"j'<b>ai</b> fait"},{"t":"arriver","box":"e","why":"je <b>suis</b> arrivé(e)"},{"t":"voir","box":"a","why":"j'<b>ai</b> vu"},{"t":"rester","box":"e","why":"je <b>suis</b> resté(e)"},{"t":"naître","box":"e","why":"je <b>suis</b> né(e)"},{"t":"prendre","box":"a","why":"j'<b>ai</b> pris"},{"t":"se lever","box":"e","why":"je <b>me suis</b> levé(e)"},{"t":"tomber","box":"e","why":"je <b>suis</b> tombé(e)"},{"t":"dormir","box":"a","why":"j'<b>ai</b> dormi"}]},{"tool":"agree","title":"With être, the participle agrees","sub":"Switch the person: the end of the participle follows him, her, them.","cols":["il","elle","ils","elles"],"pre":["il","elle","ils","elles"],"rows":[{"forms":["est allé","est allée","sont allés","sont allées"],"en":["he went","she went","they went","they went (women)"]},{"forms":["est parti","est partie","sont partis","sont parties"],"en":["he left","she left","they left","they left (women)"]},{"forms":["est resté","est restée","sont restés","sont restées"],"en":["he stayed","she stayed","they stayed","they stayed (women)"]},{"forms":["a mangé","a mangé","ont mangé","ont mangé"],"en":["he ate · with avoir, no change","she ate · no change","they ate · no change","they ate · no change"]}]}],"practice":{"choose":[{"q":"J'___ mangé une pizza.","en":"I ate a pizza.","opts":["ai","suis","as","est"],"a":"ai","why":"manger takes…","hint":"<b>avoir</b>: j'ai mangé."},{"q":"Elle est ___ à Paris.","en":"She went to Paris.","opts":["allée","allé","allés","aller"],"a":"allée","why":"With être, it agrees with elle.","hint":"elle est <b>allée</b>."},{"q":"Nous ___ partis tôt.","en":"We left early.","opts":["sommes","avons","êtes","sont"],"a":"sommes","why":"partir takes…","hint":"<b>être</b>: nous sommes partis."},{"q":"Ils ont ___ le film.","en":"They saw the film.","opts":["vu","vus","voir","voyé"],"a":"vu","why":"With avoir, nothing agrees.","hint":"ils ont <b>vu</b>."},{"q":"Nous n'___ pas fini.","en":"We didn't finish.","opts":["avons","sommes","avez","ont"],"a":"avons","why":"finir takes avoir; the no goes round it.","hint":"nous <b>n'avons pas</b> fini."},{"q":"Je suis ___ en 1990.","en":"I was born in 1990.","opts":["né(e)","naît","naissé","eu né"],"a":"né(e)","why":"naître → ?","hint":"je suis <b>né(e)</b>."}],"build":[{"en":"I ate.","tiles":["J'ai","mangé."],"trap":"suis","why":"manger takes avoir.","hint":"<b>j'ai</b> mangé."},{"en":"She went.","tiles":["Elle","est","allée."],"trap":"a","why":"aller takes être.","hint":"elle <b>est allée</b>."},{"en":"We didn't finish.","tiles":["Nous","n'avons","pas","fini."],"trap":"sommes","why":"finir takes avoir; the no goes round it.","hint":"nous <b>n'avons pas</b> fini."},{"en":"They (m) left.","tiles":["Ils","sont","partis."],"trap":"ont","why":"partir takes être.","hint":"ils <b>sont partis</b>."},{"en":"She stayed at home.","tiles":["Elle","est","restée","à la maison."],"trap":"a","why":"rester takes être.","hint":"elle <b>est restée</b>."}],"spot":[{"words":["Elle","a","allée."],"bad":1,"fix":"est","hint":"aller takes <b>être</b>.","look":"Which helper does aller take?"},{"words":["Elle","est","parti."],"bad":2,"fix":"partie.","hint":"With être it agrees: <b>partie</b>.","look":"Does the participle match elle?"},{"words":["Nous","sommes","mangé."],"bad":1,"fix":"avons","hint":"manger takes <b>avoir</b>.","look":"Which helper does manger take?"},{"words":["Ils","ont","vus","le film."],"bad":2,"fix":"vu","hint":"With avoir, no agreement: <b>vu</b>.","look":"Does the participle agree with avoir?"},{"words":["Je n'ai","fini","pas."],"bad":1,"fix":"pas fini.","hint":"pas goes before the participle: je n'ai <b>pas fini</b>.","look":"Where does pas go?","say":"Je n'ai pas fini."}]},"drill":[["I ate (manger)","J'ai mangé.","manger takes <b>avoir</b>."],["She went (aller)","Elle est allée.","aller takes <b>être</b>; it agrees: allé<b>e</b>."],["We didn't finish","Nous n'avons pas fini.","The no goes round avoir: <b>n'avons pas</b> fini."],["They (m) left (partir)","Ils sont partis.","partir takes <b>être</b>; it agrees: parti<b>s</b>."],["She stayed (rester)","Elle est restée.","rester takes <b>être</b>: resté<b>e</b>."],["We saw the film.","Nous avons vu le film.","voir takes <b>avoir</b>: avons vu."]]},"18":{"line":"A « se » verb has an extra pronoun that matches the subject: je <b>me</b> lave, tu <b>te</b> laves, il <b>se</b> lave, nous <b>nous</b> lavons, vous <b>vous</b> lavez, ils <b>se</b> lavent. It is often a daily routine (se lever, se coucher) or « each other » (nous nous parlons). In the passé composé it takes <b>être</b>: je me suis levé(e). In an order: Lève-<b>toi</b> !","words":"","steps":[{"tool":"conj","title":"The pronoun follows the subject","sub":"Pick a verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"se lever","en":"to get up","forms":["me lève","te lèves","se lève","nous levons","vous levez","se lèvent"],"tail":"à sept heures"},{"inf":"s'appeler","en":"to be called","forms":["m'appelle","t'appelles","s'appelle","nous appelons","vous appelez","s'appellent"],"tail":"Léa"},{"inf":"se coucher","en":"to go to bed","forms":["me couche","te couches","se couche","nous couchons","vous couchez","se couchent"],"tail":"tard"}]},{"tool":"swap","title":"In the past, with aller, in an order","sub":"Pick a sentence and tap « Change it ».","button":["Change it","Back"],"legend":[["p","the pronoun"],["x","what comes in"]],"items":[{"label":"Je me lave. → past","en":["I wash.","I washed."],"a":[["s","Je",""],["p","me","p"],["v","lave.",""]],"b":[["s","Je",""],["p","me","p"],["x","suis","x"],["v","lavé(e).",""]],"note":"Always <b>être</b> in the past, and the participle agrees."},{"label":"Elle se lève. → past","en":["She gets up.","She got up."],"a":[["s","Elle",""],["p","se","p"],["v","lève.",""]],"b":[["s","Elle",""],["p","s'","p"],["x","est","x"],["v","levée.",""]],"note":"se before a vowel: elle <b>s'est</b> levée."},{"label":"Nous nous couchons. → aller","en":["We go to bed.","We are going to go to bed."],"a":[["s","Nous",""],["p","nous","p"],["v","couchons.",""]],"b":[["s","Nous",""],["x","allons","x"],["p2","nous","p"],["v","coucher.",""]],"note":"With two verbs, the pronoun stays with the second: allons <b>nous coucher</b>."},{"label":"Tu te dépêches. → order","en":["You hurry.","Hurry up!"],"a":[["s","Tu",""],["p","te","p"],["v","dépêches.",""]],"b":[["v","Dépêche-",""],["p","toi !","p"]],"note":"In an order: <b>Dépêche-toi !</b>"}]}],"practice":{"choose":[{"q":"Je ___ lève à sept heures.","en":"I get up at seven.","opts":["me","se","te","m'"],"a":"me","why":"The pronoun matches je.","hint":"je <b>me</b> lève."},{"q":"Elle ___ appelle Anna.","en":"She is called Anna.","opts":["s'","se","m'","elle"],"a":"s'","why":"se before a vowel…","hint":"elle <b>s'</b>appelle."},{"q":"Nous ___ couchons tard.","en":"We go to bed late.","opts":["nous","se","vous","on"],"a":"nous","why":"The pronoun matches nous.","hint":"nous <b>nous</b> couchons."},{"q":"Je me ___ levé(e) tôt.","en":"I got up early.","opts":["suis","ai","es","est"],"a":"suis","why":"In the past, « se » verbs take…","hint":"<b>être</b>: je me suis levé(e)."},{"q":"Dépêche-___ !","en":"Hurry up!","opts":["toi","te","tu","se"],"a":"toi","why":"In an order…","hint":"Dépêche-<b>toi</b> !"},{"q":"Nous allons ___ coucher.","en":"We are going to go to bed.","opts":["nous","se","vous","on"],"a":"nous","why":"The pronoun still matches nous.","hint":"allons <b>nous</b> coucher."}],"build":[{"en":"I get up at seven.","tiles":["Je","me","lève","à sept heures."],"trap":"se","why":"The pronoun matches je.","hint":"je <b>me</b> lève."},{"en":"She is called Anna.","tiles":["Elle","s'appelle","Anna."],"trap":"se appelle","why":"se before a vowel.","hint":"elle <b>s'appelle</b>."},{"en":"We are going to go to bed.","tiles":["Nous","allons","nous","coucher."],"trap":"se","why":"The pronoun matches nous.","hint":"allons <b>nous</b> coucher."},{"en":"She got up early.","tiles":["Elle","s'est","levée","tôt."],"trap":"a","why":"« se » verbs take être.","hint":"elle <b>s'est levée</b>."},{"en":"Don't get up! (tu)","tiles":["Ne","te","lève","pas !"],"trap":"toi","why":"In a no, the pronoun stays before.","hint":"Ne <b>te</b> lève pas !"}],"spot":[{"words":["Je","se","lève tôt."],"bad":1,"fix":"me","hint":"With je: <b>me</b>.","look":"Does the pronoun match je?"},{"words":["Elle","s'a","levée."],"bad":1,"fix":"s'est","hint":"« se » verbs take <b>être</b>.","look":"Which helper?"},{"words":["Nous","se","couchons."],"bad":1,"fix":"nous","hint":"With nous: <b>nous</b>.","look":"Does the pronoun match nous?"},{"words":["Dépêche-","te !"],"bad":1,"fix":"toi !","hint":"In an order: <b>toi</b>.","look":"What does te become in an order?","say":"Dépêche-toi !"},{"words":["Il","se appelle","Paul."],"bad":1,"fix":"s'appelle","hint":"se before a vowel: <b>s'appelle</b>.","look":"appelle starts with a vowel."}]},"drill":[["I get up at 7","Je me lève à sept heures. / Je me lève à 7 heures. / Je me lève à 7 h.","je <b>me</b> lève."],["She is called Anna","Elle s'appelle Anna.","se before a vowel: <b>s'</b>appelle."],["We are going to go to bed","Nous allons nous coucher.","The pronoun stays with the second verb: allons <b>nous coucher</b>."],["Hurry up! (tu)","Dépêche-toi !","In an order: <b>Dépêche-toi !</b>"],["I got up early.","Je me suis levé tôt. / Je me suis levée tôt.","« se » verbs take <b>être</b>: je me suis levé(e)."],["They go to bed late.","Ils se couchent tard.","ils <b>se</b> couchent."]]},"25":{"line":"Like ne … pas, these wrap round the verb: <b>ne … jamais</b> (never), <b>ne … rien</b> (nothing), <b>ne … personne</b> (nobody), <b>ne … plus</b> (no longer). In the passé composé, jamais, rien and plus go before the participle (je n'ai <b>rien</b> mangé), but personne goes after it (je n'ai vu <b>personne</b>).","words":"Time words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:7\">Vocab 7 · Frequency & Time Adverbs</a>.","steps":[{"tool":"swap","title":"Swap pas for another word","sub":"Pick a sentence and tap « Make it a no ».","button":["Make it a no","Back"],"legend":[["n","the two parts of the no"],["x","what goes"]],"items":[{"label":"Je mange de la viande. (never)","en":["I eat meat.","I never eat meat."],"a":[["s","Je",""],["v","mange",""],["o","de la viande.","x"]],"b":[["s","Je",""],["ne","ne","n"],["v","mange",""],["j","jamais","n"],["o","de viande.",""]]},{"label":"Je vois quelqu'un. (nobody)","en":["I see someone.","I don't see anyone."],"a":[["s","Je",""],["v","vois",""],["o","quelqu'un.","x"]],"b":[["s","Je",""],["ne","ne","n"],["v","vois",""],["j","personne.","n"]]},{"label":"Il y a quelque chose ici. (nothing)","en":["There is something here.","There is nothing here."],"a":[["s","Il y a",""],["o","quelque chose","x"],["h","ici.",""]],"b":[["s0","Il",""],["ne","n'","n"],["s1","y a",""],["j","rien","n"],["h","ici.",""]]},{"label":"Elle travaille encore ici. (no longer)","en":["She still works here.","She no longer works here."],"a":[["s","Elle",""],["v","travaille",""],["o","encore","x"],["h","ici.",""]],"b":[["s","Elle",""],["ne","ne","n"],["v","travaille",""],["j","plus","n"],["h","ici.",""]]},{"label":"J'ai mangé quelque chose. (past)","en":["I ate something.","I didn't eat anything."],"a":[["s","J'ai",""],["v","mangé",""],["o","quelque chose.","x"]],"b":[["s0","Je",""],["ne","n'","n"],["a","ai",""],["j","rien","n"],["v","mangé.",""]],"note":"In the past: <b>rien</b> before the participle."},{"label":"J'ai vu quelqu'un. (past)","en":["I saw someone.","I didn't see anyone."],"a":[["s","J'ai",""],["v","vu",""],["o","quelqu'un.","x"]],"b":[["s0","Je",""],["ne","n'","n"],["a","ai",""],["v","vu",""],["j","personne.","n"]],"note":"But <b>personne</b> goes after the participle."}]},{"tool":"flip","title":"Opposites","sub":"Tap a card: the yes word turns into its no.","cards":[{"a":"toujours","b":"ne … jamais","tag":"always → never"},{"a":"quelque chose","b":"ne … rien","tag":"something → nothing"},{"a":"quelqu'un","b":"ne … personne","tag":"someone → nobody"},{"a":"encore","b":"ne … plus","tag":"still → no longer"},{"a":"déjà","b":"ne … pas encore","tag":"already → not yet"}]}],"practice":{"choose":[{"q":"Je ne mange ___ de viande.","en":"I never eat meat.","opts":["jamais","rien","personne","plus"],"a":"jamais","why":"never…","hint":"ne … <b>jamais</b>."},{"q":"Je ne vois ___.","en":"I don't see anyone.","opts":["personne","rien","jamais","plus"],"a":"personne","why":"nobody…","hint":"ne … <b>personne</b>."},{"q":"Il n'y a ___ ici.","en":"There is nothing here.","opts":["rien","personne","jamais","pas"],"a":"rien","why":"nothing…","hint":"ne … <b>rien</b>."},{"q":"Elle ne travaille ___ ici.","en":"She no longer works here.","opts":["plus","jamais","rien","encore"],"a":"plus","why":"no longer…","hint":"ne … <b>plus</b>."},{"q":"Je n'ai ___ mangé.","en":"I didn't eat anything.","opts":["rien","personne","mangé rien","pas rien"],"a":"rien","why":"nothing, in the past…","hint":"je n'ai <b>rien</b> mangé."},{"q":"Je n'ai vu ___.","en":"I didn't see anyone.","opts":["personne","rien","jamais","plus"],"a":"personne","why":"nobody, after the participle.","hint":"je n'ai vu <b>personne</b>."}],"build":[{"en":"I never eat meat.","tiles":["Je","ne","mange","jamais","de","viande."],"trap":"pas","why":"never…","hint":"ne mange <b>jamais</b>."},{"en":"I don't see anyone.","tiles":["Je","ne","vois","personne."],"trap":"pas","why":"nobody…","hint":"ne vois <b>personne</b>."},{"en":"There is nothing here.","tiles":["Il","n'y a","rien","ici."],"trap":"pas","why":"nothing…","hint":"n'y a <b>rien</b>."},{"en":"She no longer works here.","tiles":["Elle","ne","travaille","plus","ici."],"trap":"encore","why":"no longer…","hint":"ne travaille <b>plus</b>."},{"en":"I didn't see anyone.","tiles":["Je","n'ai","vu","personne."],"trap":"pas","why":"personne goes after the participle.","hint":"n'ai vu <b>personne</b>."}],"spot":[{"words":["Je","ne","mange","pas jamais","de viande."],"bad":3,"fix":"jamais","hint":"jamais takes the place of pas.","look":"Two no words?"},{"words":["Je","vois","personne."],"bad":1,"fix":"ne vois","hint":"Written French needs <b>ne</b>.","look":"Something is missing before the verb.","say":"Je ne vois personne."},{"words":["Je n'ai","personne","vu."],"bad":1,"fix":"vu personne","hint":"personne goes <b>after</b> the participle.","look":"Where does personne go in the past?","say":"Je n'ai vu personne."},{"words":["Je n'ai","mangé","rien."],"bad":1,"fix":"rien mangé.","hint":"rien goes <b>before</b> the participle.","look":"Where does rien go in the past?","say":"Je n'ai rien mangé."},{"words":["Elle","ne travaille","encore","ici."],"bad":2,"fix":"plus","hint":"no longer = <b>ne … plus</b>.","look":"Which word means « no longer »?"}]},"drill":[["I never eat meat","Je ne mange jamais de viande.","<b>ne … jamais</b>, and de after it."],["I don't see anyone","Je ne vois personne.","<b>ne … personne</b>."],["There is nothing here","Il n'y a rien ici.","<b>ne … rien</b>."],["She no longer works here","Elle ne travaille plus ici.","<b>ne … plus</b>."],["I didn't eat anything.","Je n'ai rien mangé.","In the past: <b>rien</b> before the participle."],["I didn't see anyone.","Je n'ai vu personne.","<b>personne</b> after the participle."]]},"22":{"line":"Many adverbs are the <b>feminine</b> adjective + <b>-ment</b>: lent → lente → <b>lentement</b>, heureux → heureuse → <b>heureusement</b>. After a vowel, just -ment: vrai → vraiment. -ant / -ent → <b>-amment / -emment</b>. Special: bon → <b>bien</b>, mauvais → <b>mal</b>. The adverb goes after the verb (il parle bien); in the passé composé, short ones go between avoir and the participle (j'ai <b>déjà</b> mangé).","words":"Frequency and time: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:7\">Vocab 7 · Frequency & Time Adverbs</a>.","steps":[{"tool":"flip","title":"Adjective → adverb","sub":"Tap a card: the adjective turns into its adverb.","cards":[{"a":"lent (lente)","b":"lentement","tag":"feminine + -ment"},{"a":"heureux (heureuse)","b":"heureusement","tag":"feminine + -ment"},{"a":"rapide","b":"rapidement","tag":"-e: + ment"},{"a":"vrai","b":"vraiment","tag":"after a vowel: + ment"},{"a":"constant","b":"constamment","tag":"-ant → -amment"},{"a":"évident","b":"évidemment","tag":"-ent → -emment"},{"a":"bon","b":"bien","tag":"special"},{"a":"mauvais","b":"mal","tag":"special"}]},{"tool":"swap","title":"Where it goes","sub":"Pick a sentence and tap « Add the adverb ».","button":["Add the adverb","Back"],"legend":[["x","the adverb"]],"items":[{"label":"Elle parle français.","en":["She speaks French.","She speaks French well."],"a":[["s","Elle",""],["v","parle",""],["o","français.",""]],"b":[["s","Elle",""],["v","parle",""],["a","bien","x"],["o","français.",""]],"note":"Right after the verb: parle <b>bien</b>."},{"label":"J'ai mangé.","en":["I have eaten.","I have already eaten."],"a":[["s","J'ai",""],["v","mangé.",""]],"b":[["s","J'ai",""],["a","déjà","x"],["v","mangé.",""]],"note":"Short adverbs go between avoir and the participle: ai <b>déjà</b> mangé."},{"label":"Il travaille.","en":["He works.","He works a lot."],"a":[["s","Il",""],["v","travaille.",""]],"b":[["s","Il",""],["v","travaille",""],["a","beaucoup.","x"]]},{"label":"Nous avons bien dormi. → long adverb","en":["We slept well.","We slept peacefully."],"a":[["s","Nous avons",""],["a","bien","x"],["v","dormi.",""]],"b":[["s","Nous avons",""],["v","dormi",""],["a2","tranquillement.","x"]],"note":"Long -ment adverbs usually go after the participle."}]}],"practice":{"choose":[{"q":"lent → ___","en":"slowly","opts":["lentement","lentment","lenement","lentemant"],"a":"lentement","why":"The feminine is lente.","hint":"lente + ment = <b>lentement</b>."},{"q":"heureux → ___","en":"fortunately","opts":["heureusement","heureuxment","heureument","heureusemant"],"a":"heureusement","why":"The feminine is heureuse.","hint":"<b>heureusement</b>."},{"q":"vrai → ___","en":"really","opts":["vraiment","vraiement","vraiemment","vraimant"],"a":"vraiment","why":"After a vowel, just -ment.","hint":"<b>vraiment</b>."},{"q":"évident → ___","en":"obviously","opts":["évidemment","évidentment","évidamment","évidement"],"a":"évidemment","why":"-ent has its own form.","hint":"-ent → <b>-emment</b>."},{"q":"Elle parle ___ français.","en":"She speaks French well.","opts":["bien","bon","bonne","mieux"],"a":"bien","why":"How she speaks: an adverb.","hint":"bon → <b>bien</b>."},{"q":"J'ai ___ mangé.","en":"I have already eaten.","opts":["déjà","déjà déjà","avant","encore"],"a":"déjà","why":"already…","hint":"j'ai <b>déjà</b> mangé."}],"build":[{"en":"She speaks French well.","tiles":["Elle","parle","bien","français."],"trap":"bon","why":"How she speaks: an adverb.","hint":"parle <b>bien</b>."},{"en":"I've already eaten.","tiles":["J'ai","déjà","mangé."],"trap":"encore","why":"Between avoir and the participle.","hint":"ai <b>déjà</b> mangé."},{"en":"He drives slowly.","tiles":["Il","conduit","lentement."],"trap":"lent","why":"How he drives: an adverb.","hint":"conduit <b>lentement</b>."},{"en":"Fortunately, it is sunny.","tiles":["Heureusement,","il","fait","beau."],"trap":"Heureux,","why":"An adverb at the front.","hint":"<b>Heureusement</b>, …"},{"en":"We work a lot.","tiles":["Nous","travaillons","beaucoup."],"trap":"très","why":"a lot = beaucoup.","hint":"travaillons <b>beaucoup</b>."}],"spot":[{"words":["Elle","parle","bon","français."],"bad":2,"fix":"bien","hint":"How she speaks: <b>bien</b>.","look":"Is it about the French or how she speaks?"},{"words":["Il","conduit","lentment."],"bad":2,"fix":"lentement.","hint":"lente + ment: <b>lentement</b>.","look":"Start from the feminine."},{"words":["J'ai","mangé","déjà."],"bad":1,"fix":"déjà mangé.","hint":"Between avoir and the participle: ai <b>déjà mangé</b>.","look":"Where does déjà go in the past?","say":"J'ai déjà mangé."},{"words":["Il chante","mauvais."],"bad":1,"fix":"mal.","hint":"mauvais → <b>mal</b>.","look":"How he sings: an adverb."},{"words":["Évidentment,","c'est vrai."],"bad":0,"fix":"Évidemment,","hint":"-ent → <b>-emment</b>.","look":"Look at the spelling of the -ent adverb."}]},"drill":[["slowly (lent)","lentement","feminine lente + <b>-ment</b>."],["fortunately (heureux)","heureusement","feminine heureuse + <b>-ment</b>."],["She speaks French well","Elle parle bien français. / Elle parle bien le français.","bon → <b>bien</b>, after the verb."],["I've already eaten","J'ai déjà mangé.","Short adverbs between avoir and the participle."],["really (vrai)","vraiment","After a vowel, just <b>-ment</b>."],["obviously (évident)","évidemment","-ent → <b>-emment</b>."]]},"26":{"line":"A relative pronoun glues two sentences into one. <b>qui</b> = the one who does it (the subject): un ami <b>qui</b> habite à Paris. <b>que</b> (qu') = the one it is done to (the object): le film <b>que</b> j'ai vu. <b>où</b> = where, or when: la ville <b>où</b> j'habite, le jour <b>où</b> tu es arrivé.","words":"","steps":[{"tool":"swap","title":"Glue two sentences","sub":"Pick a pair and tap « Glue them »: the repeated word turns into qui, que or où.","button":["Glue them","Two sentences again"],"legend":[["p","the glue word"],["x","what it replaces"]],"items":[{"label":"J'ai un ami. Il habite à Paris.","en":["I have a friend. He lives in Paris.","I have a friend who lives in Paris."],"a":[["a","J'ai un ami.",""],["x","Il","x"],["b","habite à Paris.",""]],"b":[["a","J'ai un ami",""],["p","qui","p"],["b","habite à Paris.",""]],"note":"Il does the action (the subject) → <b>qui</b>."},{"label":"Le film est génial. J'ai vu ce film.","en":["The film is great. I saw the film.","The film that I saw is great."],"a":[["a","Le film est génial.",""],["b","J'ai vu",""],["x","ce film.","x"]],"b":[["a0","Le film",""],["p","que","p"],["b","j'ai vu",""],["a1","est génial.",""]],"note":"ce film is what I saw (the object) → <b>que</b>."},{"label":"C'est la ville. J'habite dans cette ville.","en":["It's the town. I live in that town.","It's the town where I live."],"a":[["a","C'est la ville.",""],["b","J'habite",""],["x","dans cette ville.","x"]],"b":[["a","C'est la ville",""],["p","où","p"],["b","j'habite.",""]],"note":"A place → <b>où</b>."},{"label":"Je me souviens du jour. Tu es arrivé ce jour-là.","en":["I remember the day. You arrived that day.","I remember the day when you arrived."],"a":[["a","Je me souviens du jour.",""],["b","Tu es arrivé",""],["x","ce jour-là.","x"]],"b":[["a","Je me souviens du jour",""],["p","où","p"],["b","tu es arrivé.",""]],"note":"A time, too → <b>où</b> (not quand)."},{"label":"C'est un livre. Marie aime ce livre.","en":["It's a book. Marie loves this book.","It's a book that Marie loves."],"a":[["a","C'est un livre.",""],["b","Marie aime",""],["x","ce livre.","x"]],"b":[["a","C'est un livre",""],["p","qu'","p"],["b","Marie aime.",""]],"note":"que before a vowel: <b>qu'</b>Marie."}]},{"tool":"sort","title":"qui, que or où?","sub":"Look at what follows the gap. Tap the box.","boxes":[{"k":"qui","label":"qui","sub":"+ a verb (it is the subject)"},{"k":"que","label":"que","sub":"+ a subject and a verb"},{"k":"ou","label":"où","sub":"a place or a time"}],"cards":[{"t":"le livre … est sur la table","box":"qui","why":"Followed by a verb (est): <b>qui</b>."},{"t":"le livre … je lis","box":"que","why":"Followed by je lis: <b>que</b>."},{"t":"la maison … j'habite","box":"ou","why":"A place: <b>où</b>."},{"t":"la fille … chante","box":"qui","why":"<b>qui</b> chante."},{"t":"la fille … tu connais","box":"que","why":"<b>que</b> tu connais."},{"t":"le jour … il est né","box":"ou","why":"A time: <b>où</b>."},{"t":"les amis … viennent ce soir","box":"qui","why":"<b>qui</b> viennent."},{"t":"le café … nous aimons","box":"que","why":"<b>que</b> nous aimons."}]}],"practice":{"choose":[{"q":"J'ai un ami ___ habite à Paris.","en":"I have a friend who lives in Paris.","opts":["qui","que","où","quoi"],"a":"qui","why":"A verb follows the gap.","hint":"<b>qui</b> + verb."},{"q":"le film ___ j'ai vu","en":"the film that I saw","opts":["que","qui","où","dont"],"a":"que","why":"A subject (j') follows the gap.","hint":"<b>que</b> + subject + verb."},{"q":"la ville ___ j'habite","en":"the town where I live","opts":["où","que","qui","quand"],"a":"où","why":"A place…","hint":"<b>où</b>."},{"q":"Le livre ___ est sur la table.","en":"The book that is on the table.","opts":["qui","que","qu'","où"],"a":"qui","why":"A verb follows the gap.","hint":"<b>qui</b> est sur la table."},{"q":"le jour ___ il est né","en":"the day he was born","opts":["où","quand","que","qui"],"a":"où","why":"A time, in French…","hint":"A time: <b>où</b>, not quand."},{"q":"la robe ___ elle porte","en":"the dress she is wearing","opts":["qu'","que","qui","où"],"a":"qu'","why":"que before a vowel…","hint":"<b>qu'</b>elle porte."}],"build":[{"en":"I have a friend who lives in Paris.","tiles":["J'ai","un","ami","qui","habite","à Paris."],"trap":"que","why":"A verb follows.","hint":"<b>qui</b> habite."},{"en":"the film that I saw","tiles":["le","film","que","j'ai","vu"],"trap":"qui","why":"A subject follows.","hint":"<b>que</b> j'ai vu."},{"en":"the town where I live","tiles":["la","ville","où","j'habite"],"trap":"que","why":"A place.","hint":"<b>où</b> j'habite."},{"en":"the girl you know","tiles":["la","fille","que","tu","connais"],"trap":"qui","why":"A subject follows.","hint":"<b>que</b> tu connais."},{"en":"the day when you arrived","tiles":["le","jour","où","tu","es arrivé"],"trap":"quand","why":"A time.","hint":"<b>où</b> tu es arrivé."}],"spot":[{"words":["J'ai un ami","que","habite ici."],"bad":1,"fix":"qui","hint":"A verb follows: <b>qui</b>.","look":"What follows the glue word?"},{"words":["le film","qui","j'ai vu"],"bad":1,"fix":"que","hint":"A subject follows: <b>que</b>.","look":"What follows the glue word?"},{"words":["la ville","que","j'habite"],"bad":1,"fix":"où","hint":"A place: <b>où</b>.","look":"Is it a place?"},{"words":["le jour","quand","il est né"],"bad":1,"fix":"où","hint":"A time after a noun: <b>où</b>.","look":"Which word for a time after le jour?"},{"words":["le livre","que","elle lit"],"bad":1,"fix":"qu'","hint":"que before a vowel: <b>qu'</b>elle.","look":"Look before elle.","say":"le livre qu'elle lit"}]},"drill":[["I have a friend who lives in Paris","J'ai un ami qui habite à Paris. / J'ai une amie qui habite à Paris. / J'ai un ami qui vit à Paris.","A verb follows: <b>qui</b>."],["the film that I saw","le film que j'ai vu","A subject follows: <b>que</b>."],["the town where I live","la ville où j'habite / la ville où je vis","A place: <b>où</b>."],["Qui or que? Le livre ___ est sur la table","qui","A verb follows, so it is the subject: <b>qui</b>."],["the day when he was born","le jour où il est né","A time: <b>où</b>."],["the girl you know (tu)","la fille que tu connais","<b>que</b> + tu connais."]]},"16":{"line":"The <b>imparfait</b> says how things were or used to be: descriptions, background, habits. Take the nous form of the present, drop -ons, add <b>-ais, -ais, -ait, -ions, -iez, -aient</b>: nous parl<i>ons</i> → je parl<b>ais</b>. Only être is different: j'<b>étais</b>. Quand j'étais petit, nous habitions à Lyon.","words":"","steps":[{"tool":"conj","title":"One set of endings for every verb","sub":"Pick a verb, then tap a person: the ending lights up.","neg":true,"verbs":[{"inf":"parler","en":"was speaking / used to speak","stem":"parl","forms":["parlais","parlais","parlait","parlions","parliez","parlaient"],"tail":"souvent"},{"inf":"finir","en":"was finishing","stem":"finiss","forms":["finissais","finissais","finissait","finissions","finissiez","finissaient"],"tail":"tard"},{"inf":"faire","en":"was doing","stem":"fais","forms":["faisais","faisais","faisait","faisions","faisiez","faisaient"],"tail":"du sport"},{"inf":"être","en":"was","stem":"ét","forms":["étais","étais","était","étions","étiez","étaient"],"tail":"content"}]},{"tool":"flip","title":"From the nous form","sub":"Tap a card: nous … -ons gives the imparfait.","cards":[{"a":"nous parlons","b":"je parlais","tag":"parl-"},{"a":"nous finissons","b":"je finissais","tag":"finiss-"},{"a":"nous faisons","b":"je faisais","tag":"fais-"},{"a":"nous prenons","b":"je prenais","tag":"pren-"},{"a":"nous avons","b":"j'avais","tag":"av-"},{"a":"nous mangeons","b":"je mangeais","tag":"mange- (keeps the e)"},{"a":"nous sommes","b":"j'étais","tag":"the only exception"}]},{"tool":"sort","title":"What is it for?","sub":"Tap what each sentence does.","boxes":[{"k":"d","label":"a description","sub":"how it was"},{"k":"h","label":"a habit","sub":"what used to happen"},{"k":"b","label":"the background","sub":"what was going on"}],"cards":[{"t":"La maison était grande.","box":"d"},{"t":"Le dimanche, nous allions chez mamie.","box":"h"},{"t":"Il pleuvait.","box":"b"},{"t":"Elle avait les yeux bleus.","box":"d"},{"t":"Je jouais au foot tous les jours.","box":"h"},{"t":"Tout le monde dormait.","box":"b"}]}],"practice":{"choose":[{"q":"J'___ petit.","en":"I was little.","opts":["étais","étai","était","été"],"a":"étais","why":"être with je.","hint":"<b>j'étais</b>."},{"q":"Nous ___ (manger) à midi.","en":"We used to eat at noon.","opts":["mangions","mangeions","mangeons","mangiez"],"a":"mangions","why":"nous + -ions.","hint":"nous <b>mangions</b>."},{"q":"Elle ___ (habiter) à Paris.","en":"She used to live in Paris.","opts":["habitait","habitais","habitaient","a habité"],"a":"habitait","why":"elle + -ait.","hint":"elle <b>habitait</b>."},{"q":"Il y ___ un café ici.","en":"There was a café here.","opts":["avait","était","a eu","avais"],"a":"avait","why":"il y a in the imparfait…","hint":"il y <b>avait</b>."},{"q":"Ils ___ (faire) du sport.","en":"They used to do sport.","opts":["faisaient","faisait","faisions","fasaient"],"a":"faisaient","why":"ils + -aient.","hint":"ils <b>faisaient</b>."},{"q":"Vous ___ (être) fatigués.","en":"You were tired.","opts":["étiez","étaient","êtiez","étions"],"a":"étiez","why":"vous + -iez.","hint":"vous <b>étiez</b>."}],"build":[{"en":"I was little.","tiles":["J'","étais","petit."],"trap":"ai été","why":"A description: imparfait.","hint":"<b>j'étais</b>."},{"en":"We used to eat at noon.","tiles":["Nous","mangions","à","midi."],"trap":"mangeons","why":"A habit: imparfait.","hint":"nous <b>mangions</b>."},{"en":"She used to live in Paris.","tiles":["Elle","habitait","à","Paris."],"trap":"habite","why":"A habit: imparfait.","hint":"elle <b>habitait</b>."},{"en":"There was a café.","tiles":["Il","y","avait","un","café."],"trap":"était","why":"il y a → ?","hint":"il y <b>avait</b>."},{"en":"It was raining.","tiles":["Il","pleuvait."],"trap":"a plu","why":"The background: imparfait.","hint":"il <b>pleuvait</b>."}],"spot":[{"words":["Nous","mangeions","tard."],"bad":1,"fix":"mangions","hint":"nous: <b>mangions</b> (no extra e before i).","look":"Look at the spelling with nous."},{"words":["J'","étai","content."],"bad":1,"fix":"étais","hint":"je: <b>étais</b>.","look":"Look at the ending with je.","say":"J'étais content."},{"words":["Ils","faisait","du sport."],"bad":1,"fix":"faisaient","hint":"ils: <b>-aient</b>.","look":"Look at the ending with ils."},{"words":["Il y","était","un café."],"bad":1,"fix":"avait","hint":"il y a → il y <b>avait</b>.","look":"Which verb is in il y a?"},{"words":["Tu","parlait","vite."],"bad":1,"fix":"parlais","hint":"tu: <b>-ais</b>.","look":"Look at the ending with tu."}]},"drill":[["I was (être)","J'étais","être: <b>j'étais</b>."],["we ate (manger)","nous mangions","nous <b>-ions</b>: mangions."],["She used to live in Paris","Elle habitait à Paris. / Elle vivait à Paris. / Elle habitait Paris.","A habit: elle <b>habitait</b>."],["There was a café","Il y avait un café.","il y a → il y <b>avait</b>."],["they did (faire, imparfait)","ils faisaient","ils <b>-aient</b>: faisaient."],["It was raining.","Il pleuvait.","The background: <b>il pleuvait</b>."]]},"17":{"line":"Two pasts, two jobs. The <b>passé composé</b> moves the story on: what happened, once, at a moment (le téléphone <b>a sonné</b>). The <b>imparfait</b> sets the scene: what was going on, how it was, what used to happen (il <b>pleuvait</b>, j'<b>étais</b> fatigué). Often together: Je <b>dormais</b> quand il <b>a appelé</b>.","words":"","steps":[{"tool":"line","title":"The scene and the event","sub":"Tap a point: the long stretch is the imparfait, the dots are the passé composé.","now":"","marks":[{"at":-0.85,"label":"il pleuvait…","fr":"Il pleuvait.","html":"Il <span class=\"gt-end\">pleuvait</span>.","en":"It was raining (all along).","note":"The background, no start or end: <b>imparfait</b>."},{"at":-0.4,"label":"je dormais…","fr":"Je dormais.","html":"Je <span class=\"gt-end\">dormais</span>.","en":"I was sleeping (all along).","note":"What was going on: <b>imparfait</b>."},{"at":0.0,"label":"• il a appelé","fr":"Il a appelé.","html":"Il <span class=\"gt-end\">a appelé</span>.","en":"He called (once).","note":"An event at one moment: <b>passé composé</b>."},{"at":0.45,"label":"• je me suis levé","fr":"Je me suis levé.","html":"Je <span class=\"gt-end\">me suis levé</span>.","en":"I got up.","note":"The next event: <b>passé composé</b>."},{"at":0.9,"label":"both","fr":"Je dormais quand il a appelé.","html":"Je <span class=\"gt-end\">dormais</span> quand il <span class=\"gt-end\">a appelé</span>.","en":"I was sleeping when he called.","note":"The scene (imparfait) is cut by an event (passé composé)."}]},{"tool":"sort","title":"Passé composé or imparfait?","sub":"Tap the box for each verb.","boxes":[{"k":"pc","label":"passé composé","sub":"what happened, once"},{"k":"imp","label":"imparfait","sub":"the scene, how it was, habits"}],"cards":[{"t":"Hier, j'… (manger) une pizza.","box":"pc","why":"Once, yesterday: <b>j'ai mangé</b>.","say":"Hier, j'ai mangé une pizza."},{"t":"Quand j'… (être) petit…","box":"imp","why":"How it was: <b>j'étais</b>.","say":"Quand j'étais petit…"},{"t":"Il … (faire) beau.","box":"imp","why":"The weather, the scene: <b>il faisait</b> beau.","say":"Il faisait beau."},{"t":"Soudain, la porte … (s'ouvrir).","box":"pc","why":"Suddenly: an event, <b>s'est ouverte</b>.","say":"Soudain, la porte s'est ouverte."},{"t":"Tous les étés, nous … (aller) à la mer.","box":"imp","why":"A habit: <b>nous allions</b>.","say":"Tous les étés, nous allions à la mer."},{"t":"En 2010, elle … (arriver) en France.","box":"pc","why":"One moment: <b>elle est arrivée</b>.","say":"En 2010, elle est arrivée en France."},{"t":"Elle … (avoir) les cheveux longs.","box":"imp","why":"A description: <b>elle avait</b>.","say":"Elle avait les cheveux longs."},{"t":"Il … (téléphoner) trois fois.","box":"pc","why":"Counted events: <b>il a téléphoné</b>.","say":"Il a téléphoné trois fois."}]}],"practice":{"choose":[{"q":"Hier, j'___ une pizza.","en":"Yesterday I ate a pizza.","opts":["ai mangé","mangeais","mange","mangé"],"a":"ai mangé","why":"Once, yesterday…","hint":"<b>passé composé</b>."},{"q":"Quand j'___ petit, j'habitais à Lyon.","en":"When I was little, I lived in Lyon.","opts":["étais","ai été","suis","été"],"a":"étais","why":"How it was…","hint":"<b>imparfait</b>: j'étais."},{"q":"Il ___ quand je suis parti.","en":"It was raining when I left.","opts":["pleuvait","a plu","pleut","pleuvra"],"a":"pleuvait","why":"The scene…","hint":"<b>imparfait</b>: il pleuvait."},{"q":"Je dormais quand il ___.","en":"I was sleeping when he called.","opts":["a appelé","appelait","appelle","appelé"],"a":"a appelé","why":"The event that cuts in…","hint":"<b>passé composé</b>: il a appelé."},{"q":"Tous les étés, nous ___ à la mer.","en":"Every summer we went to the sea.","opts":["allions","sommes allés","allons","irons"],"a":"allions","why":"A habit…","hint":"<b>imparfait</b>: nous allions."},{"q":"Soudain, la porte ___.","en":"Suddenly the door opened.","opts":["s'est ouverte","s'ouvrait","s'ouvre","ouvert"],"a":"s'est ouverte","why":"Suddenly: one event.","hint":"<b>passé composé</b>."}],"build":[{"en":"It was raining when I left.","tiles":["Il","pleuvait","quand","je","suis","parti."],"trap":"a plu","why":"The scene, then the event.","hint":"il <b>pleuvait</b> quand je <b>suis parti</b>."},{"en":"I was sleeping when he called.","tiles":["Je","dormais","quand","il","a","appelé."],"trap":"ai dormi","why":"The scene, then the event.","hint":"je <b>dormais</b> quand il <b>a appelé</b>."},{"en":"Yesterday I saw a film.","tiles":["Hier,","j'ai","vu","un","film."],"trap":"voyais","why":"Once, yesterday.","hint":"<b>j'ai vu</b>."},{"en":"When I was little, we lived in Lyon.","tiles":["Quand j'étais","petit,","nous","habitions","à Lyon."],"trap":"avons habité","why":"How it was, for a long time.","hint":"nous <b>habitions</b>."},{"en":"The weather was nice.","tiles":["Il","faisait","beau."],"trap":"a fait","why":"A description.","hint":"il <b>faisait</b> beau."}],"spot":[{"words":["Quand j'","ai été","petit…"],"bad":1,"fix":"étais","hint":"How it was: <b>imparfait</b>.","look":"Is it an event or how it was?","say":"Quand j'étais petit…"},{"words":["Hier,","je mangeais","une pizza."],"bad":1,"fix":"j'ai mangé","hint":"Once, yesterday: <b>passé composé</b>.","look":"Is it an event or the scene?"},{"words":["Il","a plu","quand je suis sorti."],"bad":1,"fix":"pleuvait","hint":"The scene: <b>imparfait</b>.","look":"Was it going on, or did it happen once?"},{"words":["Je dormais","quand il","appelait."],"bad":2,"fix":"a appelé.","hint":"The event that cuts in: <b>passé composé</b>.","look":"What cut the sleep?"},{"words":["Tous les jours,","nous sommes allés","au parc."],"bad":1,"fix":"nous allions","hint":"A habit: <b>imparfait</b>.","look":"Every day: an event or a habit?"}]},"drill":[["It was raining when I left","Il pleuvait quand je suis parti(e). / Il pleuvait quand je suis sorti(e).","The scene (imparfait), then the event (passé composé)."],["Hier, j'___ (manger) une pizza.","j'ai mangé","Once, yesterday: <b>passé composé</b>."],["Quand j'___ (être) petit...","j'étais","How it was: <b>imparfait</b>."],["I was sleeping when he called","Je dormais quand il a téléphoné. / Je dormais quand il a appelé.","je <b>dormais</b> (scene) quand il <b>a appelé</b> (event)."],["Every summer we went to the sea.","Tous les étés, nous allions à la mer.","A habit: <b>imparfait</b>."],["Suddenly the door opened.","Soudain, la porte s'est ouverte.","Suddenly: <b>passé composé</b>."]]},"28":{"line":"Four time words: <b>depuis</b> = since / for, still going on (present tense: j'habite ici <b>depuis</b> trois ans). <b>pendant</b> = for, finished (elle a dormi <b>pendant</b> dix heures). <b>il y a</b> = ago (je suis arrivé <b>il y a</b> une heure). <b>dans</b> = in, from now (je pars <b>dans</b> deux jours).","words":"Time words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:5\">Vocab 5 · The Calendar & Timeline</a> · <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:7\">Vocab 7 · Frequency & Time Adverbs</a>.","steps":[{"tool":"line","title":"Which one?","sub":"Tap each word on the line.","now":"","marks":[{"at":-0.8,"label":"il y a","fr":"Je suis arrivé il y a une heure.","html":"Je suis arrivé <span class=\"gt-end\">il y a</span> une heure.","en":"I arrived an hour ago.","note":"A point in the past, counted back from now. Passé composé."},{"at":-0.35,"label":"pendant","fr":"Elle a dormi pendant dix heures.","html":"Elle a dormi <span class=\"gt-end\">pendant</span> dix heures.","en":"She slept for ten hours.","note":"A stretch that is over."},{"at":0.0,"label":"depuis → now","fr":"J'habite ici depuis trois ans.","html":"J'habite ici <span class=\"gt-end\">depuis</span> trois ans.","en":"I have lived here for three years.","note":"It started in the past and is <b>still going on</b>: present tense in French."},{"at":0.65,"label":"dans","fr":"Je pars dans deux jours.","html":"Je pars <span class=\"gt-end\">dans</span> deux jours.","en":"I'm leaving in two days.","note":"A point in the future, counted from now."}]},{"tool":"sort","title":"depuis, pendant, il y a or dans?","sub":"Tap the box for each sentence.","boxes":[{"k":"dep","label":"depuis","sub":"still going on"},{"k":"pen","label":"pendant","sub":"a finished stretch"},{"k":"ily","label":"il y a","sub":"ago"},{"k":"dans","label":"dans","sub":"from now"}],"cards":[{"t":"J'apprends le français … deux ans.","box":"dep","why":"Still learning: <b>depuis</b>.","say":"J'apprends le français depuis deux ans."},{"t":"Il a plu … tout le week-end.","box":"pen","why":"Over: <b>pendant</b>.","say":"Il a plu pendant tout le week-end."},{"t":"Elle est partie … une semaine.","box":"ily","why":"A week ago: <b>il y a</b>.","say":"Elle est partie il y a une semaine."},{"t":"Le train part … dix minutes.","box":"dans","why":"Ten minutes from now: <b>dans</b>.","say":"Le train part dans dix minutes."},{"t":"Je t'attends … une heure !","box":"dep","why":"Still waiting: <b>depuis</b>.","say":"Je t'attends depuis une heure !"},{"t":"Nous avons travaillé … trois heures.","box":"pen","why":"Over: <b>pendant</b>.","say":"Nous avons travaillé pendant trois heures."}]}],"practice":{"choose":[{"q":"J'habite ici ___ trois ans.","en":"I have lived here for three years.","opts":["depuis","pendant","il y a","dans"],"a":"depuis","why":"Still living here…","hint":"<b>depuis</b>."},{"q":"Je suis arrivé ___ une heure.","en":"I arrived an hour ago.","opts":["il y a","depuis","dans","pendant"],"a":"il y a","why":"ago…","hint":"<b>il y a</b>."},{"q":"Je pars ___ deux jours.","en":"I'm leaving in two days.","opts":["dans","en","depuis","il y a"],"a":"dans","why":"From now…","hint":"<b>dans</b>."},{"q":"Elle a dormi ___ dix heures.","en":"She slept for ten hours.","opts":["pendant","depuis","il y a","dans"],"a":"pendant","why":"A finished stretch.","hint":"<b>pendant</b>."},{"q":"J'___ le français depuis deux ans.","en":"I have been learning French for two years.","opts":["apprends","ai appris","apprenais","apprendrai"],"a":"apprends","why":"With depuis, still going on: which tense?","hint":"depuis + the <b>present</b>."},{"q":"Je t'attends ___ midi.","en":"I've been waiting for you since noon.","opts":["depuis","pendant","il y a","dans"],"a":"depuis","why":"since…","hint":"<b>depuis</b> midi."}],"build":[{"en":"I have lived here for three years.","tiles":["J'habite","ici","depuis","trois ans."],"trap":"J'ai habité","why":"Still going on: the present.","hint":"<b>j'habite</b> ici depuis …"},{"en":"I arrived an hour ago.","tiles":["Je","suis","arrivé","il y a","une heure."],"trap":"depuis","why":"ago…","hint":"<b>il y a</b> une heure."},{"en":"I'm leaving in two days.","tiles":["Je","pars","dans","deux jours."],"trap":"en","why":"From now…","hint":"<b>dans</b> deux jours."},{"en":"She slept for ten hours.","tiles":["Elle","a","dormi","pendant","dix heures."],"trap":"depuis","why":"Over…","hint":"<b>pendant</b> dix heures."},{"en":"The train leaves in ten minutes.","tiles":["Le train","part","dans","dix minutes."],"trap":"il y a","why":"From now…","hint":"<b>dans</b> dix minutes."}],"spot":[{"words":["J'ai habité","ici","depuis trois ans."],"bad":0,"fix":"J'habite","hint":"Still going on, with depuis: the <b>present</b>.","look":"Which tense goes with depuis?"},{"words":["Je suis arrivé","depuis","une heure."],"bad":1,"fix":"il y a","hint":"ago: <b>il y a</b>.","look":"Is it still going on, or ago?"},{"words":["Je pars","en","deux jours."],"bad":1,"fix":"dans","hint":"From now: <b>dans</b>.","look":"Two days from now…"},{"words":["Elle a dormi","depuis","dix heures."],"bad":1,"fix":"pendant","hint":"A finished stretch: <b>pendant</b>.","look":"Is the sleep over?"},{"words":["Il est parti","dans","une semaine."],"bad":1,"fix":"il y a","hint":"In the past: <b>il y a</b>.","look":"est parti is in the past…"}]},"drill":[["I have lived here for 3 years","J'habite ici depuis trois ans. / Je vis ici depuis trois ans.","Still going on: <b>depuis</b> + the present."],["I arrived an hour ago","Je suis arrivé(e) il y a une heure.","ago: <b>il y a</b>."],["I'm leaving in two days","Je pars dans deux jours.","From now: <b>dans</b>."],["She slept for ten hours","Elle a dormi pendant dix heures. / Elle a dormi dix heures.","Over: <b>pendant</b>."],["I've been waiting for an hour.","J'attends depuis une heure.","Still waiting: <b>depuis</b> + the present."],["The train leaves in ten minutes.","Le train part dans dix minutes.","<b>dans</b> dix minutes."]]},"23":{"line":"The <b>futur simple</b> is one word: the infinitive + <b>-ai, -as, -a, -ons, -ez, -ont</b>: je parler<b>ai</b>, nous finir<b>ons</b> (-re verbs drop the e: je vendr<b>ai</b>). Some stems are irregular: <b>ser-</b> (être), <b>aur-</b> (avoir), <b>ir-</b> (aller), <b>fer-</b> (faire), <b>viendr-</b>, <b>pourr-</b>, <b>voudr-</b>, <b>verr-</b>. After quand about the future, French uses the future: Quand j'arriverai, je t'appellerai.","words":"","steps":[{"tool":"conj","title":"Infinitive + the endings","sub":"Pick a verb, then tap a person.","neg":true,"verbs":[{"inf":"parler","en":"will speak","stem":"parler","forms":["parlerai","parleras","parlera","parlerons","parlerez","parleront"],"tail":"français"},{"inf":"vendre","en":"will sell","stem":"vendr","forms":["vendrai","vendras","vendra","vendrons","vendrez","vendront"],"tail":"la voiture"},{"inf":"être","en":"will be","stem":"ser","forms":["serai","seras","sera","serons","serez","seront"],"tail":"là"},{"inf":"aller","en":"will go","stem":"ir","forms":["irai","iras","ira","irons","irez","iront"],"tail":"à Paris"}]},{"tool":"flip","title":"The irregular stems","sub":"Tap a card: the verb turns into its future stem.","cards":[{"a":"être","b":"je serai","tag":"ser-"},{"a":"avoir","b":"j'aurai","tag":"aur-"},{"a":"aller","b":"j'irai","tag":"ir-"},{"a":"faire","b":"je ferai","tag":"fer-"},{"a":"venir","b":"je viendrai","tag":"viendr-"},{"a":"pouvoir","b":"je pourrai","tag":"pourr-"},{"a":"vouloir","b":"je voudrai","tag":"voudr-"},{"a":"voir","b":"je verrai","tag":"verr-"},{"a":"devoir","b":"je devrai","tag":"devr-"},{"a":"savoir","b":"je saurai","tag":"saur-"}]},{"tool":"swap","title":"Near future → futur simple","sub":"Pick a sentence and tap « One word ».","button":["One word","Back"],"legend":[["x","the future"]],"items":[{"label":"Je vais parler.","en":["I'm going to speak.","I will speak."],"a":[["s","Je",""],["a","vais","x"],["v","parler.","x"]],"b":[["s","Je",""],["v","parlerai.","x"]]},{"label":"Nous allons partir.","en":["We're going to leave.","We will leave."],"a":[["s","Nous",""],["a","allons","x"],["v","partir.","x"]],"b":[["s","Nous",""],["v","partirons.","x"]]},{"label":"Quand j'arrive, je t'appelle.","en":["When I arrive, I call you.","When I arrive, I'll call you."],"a":[["q","Quand j'",""],["v","arrive,","x"],["s","je",""],["v2","t'appelle.","x"]],"b":[["q","Quand j'",""],["v","arriverai,","x"],["s","je",""],["v2","t'appellerai.","x"]],"note":"About the future, <b>both</b> verbs are in the future (English says « when I arrive »)."}]}],"practice":{"choose":[{"q":"Je ___ (parler) demain.","en":"I will speak tomorrow.","opts":["parlerai","parlerais","parlai","vais parlerai"],"a":"parlerai","why":"je + -ai.","hint":"je <b>parlerai</b>."},{"q":"Nous ___ (aller) en France.","en":"We will go to France.","opts":["irons","allerons","irions","allons"],"a":"irons","why":"aller has its own stem.","hint":"nous <b>irons</b>."},{"q":"Elle ___ (être) contente.","en":"She will be happy.","opts":["sera","serait","étera","est"],"a":"sera","why":"être has its own stem.","hint":"elle <b>sera</b>."},{"q":"Ils ___ (faire) du sport.","en":"They will do sport.","opts":["feront","faireront","feraient","font"],"a":"feront","why":"faire has its own stem.","hint":"ils <b>feront</b>."},{"q":"Quand j'___, je t'appellerai.","en":"When I arrive, I'll call you.","opts":["arriverai","arrive","arriverais","suis arrivé"],"a":"arriverai","why":"About the future, after quand…","hint":"quand + the <b>future</b>."},{"q":"Tu ___ (vendre) ta voiture ?","en":"Will you sell your car?","opts":["vendras","vendreras","vendrais","vends"],"a":"vendras","why":"-re verbs drop the e.","hint":"tu <b>vendras</b>."}],"build":[{"en":"I will speak.","tiles":["Je","parlerai."],"trap":"parlerais","why":"je + -ai.","hint":"je <b>parlerai</b>."},{"en":"We will go to Paris.","tiles":["Nous","irons","à","Paris."],"trap":"allerons","why":"aller → ir-.","hint":"nous <b>irons</b>."},{"en":"She will be there.","tiles":["Elle","sera","là."],"trap":"étera","why":"être → ser-.","hint":"elle <b>sera</b>."},{"en":"When I arrive, I'll call you.","tiles":["Quand j'","arriverai,","je","t'appellerai."],"trap":"arrive,","why":"After quand about the future: the future.","hint":"quand j'<b>arriverai</b>."},{"en":"They will have time.","tiles":["Ils","auront","le","temps."],"trap":"averont","why":"avoir → aur-.","hint":"ils <b>auront</b>."}],"spot":[{"words":["Nous","allerons","à Paris."],"bad":1,"fix":"irons","hint":"aller → <b>ir-</b>: nous irons.","look":"aller has its own stem."},{"words":["Elle","étera","là."],"bad":1,"fix":"sera","hint":"être → <b>ser-</b>.","look":"être has its own stem."},{"words":["Quand j'","arrive,","je t'appellerai."],"bad":1,"fix":"arriverai,","hint":"About the future: <b>quand j'arriverai</b>.","look":"Look at the verb after quand.","say":"Quand j'arriverai, je t'appellerai."},{"words":["Je","vendreai","ma voiture."],"bad":1,"fix":"vendrai","hint":"-re verbs drop the e: <b>vendrai</b>.","look":"Look at the -re verb."},{"words":["Ils","faireront","la fête."],"bad":1,"fix":"feront","hint":"faire → <b>fer-</b>.","look":"faire has its own stem."}]},"drill":[["I will speak (parler)","Je parlerai.","The infinitive + <b>-ai</b>."],["We will go (aller)","Nous irons.","aller → <b>ir-</b>."],["She will be (être)","Elle sera.","être → <b>ser-</b>."],["When I arrive, I'll call you","Quand j'arriverai, je t'appellerai. / Quand j'arriverai, je vous appellerai.","After quand about the future: the <b>future</b>."],["They will do (faire)","Ils feront.","faire → <b>fer-</b>."],["I will have (avoir)","J'aurai.","avoir → <b>aur-</b>."]]},"v17":{"line":"Most irregular verbs belong to a <b>family</b>: learn the head of the family and the others copy it, in every tense. <b>venir</b> → devenir, revenir, se souvenir (and tenir, obtenir). <b>prendre</b> → apprendre, comprendre, surprendre. <b>mettre</b> → permettre, promettre. <b>dire</b>: careful, vous <b>dites</b> (but vous contredisez). A good review of the present, the passé composé and the future.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"sort","title":"Which family?","sub":"Tap the head of the family for each verb.","boxes":[{"k":"venir","label":"venir"},{"k":"prendre","label":"prendre"},{"k":"mettre","label":"mettre"},{"k":"tenir","label":"tenir"}],"cards":[{"t":"devenir","box":"venir","why":"je deviens, je suis devenu(e)"},{"t":"apprendre","box":"prendre","why":"j'apprends, j'ai appris"},{"t":"permettre","box":"mettre","why":"je permets, j'ai permis"},{"t":"obtenir","box":"tenir","why":"j'obtiens, j'ai obtenu"},{"t":"revenir","box":"venir","why":"je reviens, je suis revenu(e)"},{"t":"comprendre","box":"prendre","why":"je comprends, j'ai compris"},{"t":"promettre","box":"mettre","why":"je promets, j'ai promis"},{"t":"appartenir","box":"tenir","why":"j'appartiens, j'ai appartenu"},{"t":"se souvenir","box":"venir","why":"je me souviens, je me suis souvenu(e)"}]},{"tool":"conj","title":"Heads of the family, in the present","sub":"Pick a verb, then tap a person.","neg":true,"verbs":[{"inf":"dire","en":"to say","forms":["dis","dis","dit","disons","dites","disent"],"tail":"bonjour"},{"inf":"mettre","en":"to put","forms":["mets","mets","met","mettons","mettez","mettent"],"tail":"la table"},{"inf":"tenir","en":"to hold","forms":["tiens","tiens","tient","tenons","tenez","tiennent"],"tail":"la porte"},{"inf":"connaître","en":"to know (a person, a place)","forms":["connais","connais","connaît","connaissons","connaissez","connaissent"],"tail":"Paris"}]},{"tool":"flip","title":"The family across the tenses","sub":"Tap a card: present → passé composé or future.","cards":[{"a":"je deviens","b":"je suis devenu(e)","tag":"passé composé, with être"},{"a":"nous mettons","b":"nous mettrons","tag":"future"},{"a":"ils prennent","b":"ils ont pris","tag":"passé composé"},{"a":"je viens","b":"je viendrai","tag":"future: viendr-"},{"a":"vous dites","b":"vous avez dit","tag":"passé composé"},{"a":"il obtient","b":"il obtiendra","tag":"future: obtiendr-"}]}],"practice":{"choose":[{"q":"Ils ___ le bus. (prendre)","en":"They take the bus.","opts":["prennent","prenent","prendent","prend"],"a":"prennent","why":"prendre with ils.","hint":"ils <b>prennent</b>."},{"q":"Vous ___ quoi ? (dire)","en":"What are you saying?","opts":["dites","disez","disent","dit"],"a":"dites","why":"dire with vous: irregular.","hint":"vous <b>dites</b>."},{"q":"Je suis ___ médecin. (devenir)","en":"I became a doctor.","opts":["devenu(e)","devenir","devient","devené"],"a":"devenu(e)","why":"Like venir in the past.","hint":"je suis <b>devenu(e)</b>."},{"q":"Nous ___ la table. (mettre, future)","en":"We will set the table.","opts":["mettrons","metterons","mettons","mettions"],"a":"mettrons","why":"mettre + -ons, drop the e.","hint":"nous <b>mettrons</b>."},{"q":"Elle ___ son diplôme. (obtenir, passé composé)","en":"She got her degree.","opts":["a obtenu","est obtenue","a obtient","a obteni"],"a":"a obtenu","why":"Like tenir: avoir + -u.","hint":"elle <b>a obtenu</b>."},{"q":"Tu ___ Marie ? (connaître)","en":"Do you know Marie?","opts":["connais","connait","connaît","connaissez"],"a":"connais","why":"connaître with tu.","hint":"tu <b>connais</b>."}],"build":[{"en":"They take the train.","tiles":["Ils","prennent","le","train."],"trap":"prenent","why":"Double n.","hint":"ils <b>prennent</b>."},{"en":"What are you saying? (vous)","tiles":["Vous","dites","quoi ?"],"trap":"disez","why":"dire with vous.","hint":"vous <b>dites</b>."},{"en":"I became a doctor.","tiles":["Je","suis","devenu","médecin."],"trap":"ai","why":"Like venir: être.","hint":"je <b>suis devenu</b>."},{"en":"We will set the table.","tiles":["Nous","mettrons","la","table."],"trap":"metterons","why":"mettre → mettr-.","hint":"nous <b>mettrons</b>."},{"en":"I understood.","tiles":["J'ai","compris."],"trap":"comprendu","why":"Like prendre: pris.","hint":"j'ai <b>compris</b>."}],"spot":[{"words":["Vous","disez","la vérité."],"bad":1,"fix":"dites","hint":"vous <b>dites</b>.","look":"Look at dire with vous."},{"words":["J'ai","comprendu."],"bad":1,"fix":"compris.","hint":"Like prendre: <b>compris</b>.","look":"Look at the participle."},{"words":["Il","a","devenu","riche."],"bad":1,"fix":"est","hint":"Like venir: <b>être</b>.","look":"Which helper?"},{"words":["Ils","tienent","la porte."],"bad":1,"fix":"tiennent","hint":"Double n: <b>tiennent</b>.","look":"Look at tenir with ils."},{"words":["Nous","metterons","la table."],"bad":1,"fix":"mettrons","hint":"Drop the e: <b>mettrons</b>.","look":"Look at the future of mettre."}]},"drill":[["they take (prendre)","ils prennent","prendre: ils <b>prennent</b>."],["you (vous) say (dire)","vous dites","dire: vous <b>dites</b>."],["I became (devenir, passé composé)","je suis devenu(e)","Like venir: <b>être</b> + devenu."],["we will put (mettre)","nous mettrons","mettre → <b>mettr-</b>."],["I understood (comprendre, passé composé)","j'ai compris","Like prendre: <b>compris</b>."],["they hold (tenir)","ils tiennent","Like venir: ils <b>tiennent</b>."]]}};
